import { Question } from "@/lib/types";

/**
 * Year 2 — Numerical Methods § 10.2 Iteration
 * Ref: y2nm2
 * 70 questions on fixed-point iteration to find roots:
 *   • rearranging f(x) = 0 into x = g(x)
 *   • running the recurrence x_{n+1} = g(x_n) from a start value x_0
 *   • convergence behaviour (including the |g'(α)| < 1 criterion)
 *   • identifying which rearrangement converges, and accuracy to given d.p.
 */
export const questions: Question[] = [
  { id: "y2nm2-001", topicRef: "y2nm2", topicTitle: "Iteration 01", difficulty: "Foundation", questionText: "Show that the equation \\(x^{3} - x - 1 = 0\\) can be rearranged into the form \\(x = \\sqrt[3]{x + 1}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy overview.", workingLatex: "x^{3} - x - 1 = 0 \\;\\longrightarrow\\; x = g(x)", explanation: "Our plan is to manipulate the polynomial so that a single \\(x\\) is isolated on the left and an expression in \\(x\\) sits on the right — the canonical \\(x = g(x)\\) form. Once we have it, the recurrence \\(x_{n+1} = g(x_{n})\\) drops out for free, and we can iterate from any reasonable starting point." }, { stepNumber: 2, description: "Why this particular form is useful.", workingLatex: "x = g(x) \\;\\Longleftrightarrow\\; \\text{fixed point of } g", explanation: "A solution of \\(f(x) = 0\\) becomes a fixed point of \\(g\\) — a value that the iteration sends to itself. Geometrically the root sits exactly where the curve \\(y = g(x)\\) crosses the line \\(y = x\\)." }, { stepNumber: 3, description: "Move the linear and constant terms across.", workingLatex: "x^{3} - x - 1 = 0 \\;\\Longleftrightarrow\\; x^{3} = x + 1", explanation: "Add \\(x\\) to both sides and add \\(1\\) to both sides. This is one reversible algebraic step — no roots are lost or gained — and it isolates the cubic term on one side." }, { stepNumber: 4, description: "Acknowledge the side we now sit on.", workingLatex: "x^{3} = x + 1\\ \\text{(cubic on the left, linear on the right)}", explanation: "The next move depends on this layout: we need to undo the cube on the left. The natural inverse is the (real) cube root." }, { stepNumber: 5, description: "Take the real cube root of both sides.", workingLatex: "\\sqrt[3]{x^{3}} = \\sqrt[3]{x + 1}", explanation: "The cube root is a one-to-one function on \\(\\mathbb{R}\\); unlike the square root, it never introduces \\(\\pm\\) ambiguity. Applying it to both sides preserves every solution and creates no spurious ones." }, { stepNumber: 6, description: "Simplify the left-hand side.", workingLatex: "\\sqrt[3]{x^{3}} = x \\quad\\text{for all real } x", explanation: "By definition of the real cube root, \\(\\sqrt[3]{x^{3}} = x\\) (no absolute-value pitfalls — those only occur with even roots)." }, { stepNumber: 7, description: "Read off the rearrangement.", workingLatex: "x = \\sqrt[3]{x + 1} \\quad\\text{Shown.}", explanation: "This is the required fixed-point form \\(x = g(x)\\) with \\(g(x) = \\sqrt[3]{x + 1}\\)." }, { stepNumber: 8, description: "Promote to a recurrence.", workingLatex: "x_{n+1} = \\sqrt[3]{x_{n} + 1}", explanation: "Attach subscripts: the right-hand side becomes \\(g(x_{n})\\), the left becomes the next iterate. This is the iteration formula corresponding to the rearrangement." }, { stepNumber: 9, description: "Geometric watch-out.", workingLatex: "y = g(x)\\ \\text{meets}\\ y = x\\ \\text{near}\\ x \\approx 1.32", explanation: "Common mistake: students sometimes square or cube in a way that introduces spurious roots. Cube roots avoid this. A quick sanity check: \\(g(1) = \\sqrt[3]{2} \\approx 1.26\\), \\(g(2) = \\sqrt[3]{3} \\approx 1.44\\), so \\(g\\) does cross \\(y = x\\) somewhere in \\((1, 2)\\)." } ], finalAnswer: "Shown." } },
  { id: "y2nm2-002", topicRef: "y2nm2", topicTitle: "Iteration 02", difficulty: "Foundation", questionText: "The iteration \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\) is used with \\(x_{0} = 1\\). Find \\(x_{1},\\ x_{2}\\) and \\(x_{3}\\), giving each to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\sqrt[3]{x_{n} + 1},\\quad x_{0} = 1", explanation: "We will compute \\(x_{1}, x_{2}, x_{3}\\) by repeated substitution into the recurrence, keeping at least 6 d.p. of internal precision so that the 4-d.p.\\ rounding at the end is unambiguous." }, { stepNumber: 2, description: "Precision policy (avoid round-off propagation).", workingLatex: "\\text{round only for display; substitute unrounded values into the next step}", explanation: "If we round to 4 d.p.\\ then feed the rounded value back in, a small error compounds each step. Always carry the full unrounded result forward." }, { stepNumber: 3, description: "Compute \\(x_{1} = g(x_{0})\\) — substitute \\(x_{0} = 1\\).", workingLatex: "x_{1} = \\sqrt[3]{1 + 1} = \\sqrt[3]{2}", explanation: "Plug \\(x_{0} = 1\\) straight into the formula. The argument becomes \\(2\\)." }, { stepNumber: 4, description: "Evaluate the cube root.", workingLatex: "x_{1} = 1.259921\\ldots", explanation: "\\(\\sqrt[3]{2}\\) is the well-known constant just above \\(1.25\\); to 6 d.p.\\ it is \\(1.259921\\)." }, { stepNumber: 5, description: "Round \\(x_{1}\\) to 4 d.p.", workingLatex: "x_{1} \\approx 1.2599", explanation: "The fifth decimal is \\(2 < 5\\), so the fourth decimal stays unchanged — round down." }, { stepNumber: 6, description: "Compute \\(x_{2} = g(x_{1})\\) — substitute the unrounded \\(x_{1}\\).", workingLatex: "x_{2} = \\sqrt[3]{1.259921 + 1} = \\sqrt[3]{2.259921}", explanation: "The argument of the cube root is \\(2.259921\\), about \\(13\\%\\) larger than at step 3." }, { stepNumber: 7, description: "Evaluate the cube root.", workingLatex: "x_{2} = 1.312294\\ldots", explanation: "Calculator gives \\(2.259921^{1/3} = 1.312294\\) (6 d.p.). Just above \\(1.31\\)." }, { stepNumber: 8, description: "Round \\(x_{2}\\) to 4 d.p.", workingLatex: "x_{2} \\approx 1.3123", explanation: "Fifth decimal is \\(9 \\geq 5\\), so the fourth decimal rounds up from \\(2\\) to \\(3\\)." }, { stepNumber: 9, description: "Compute \\(x_{3} = g(x_{2})\\) — substitute the unrounded \\(x_{2}\\).", workingLatex: "x_{3} = \\sqrt[3]{1.312294 + 1} = \\sqrt[3]{2.312294} = 1.322354\\ldots", explanation: "Continue with the carried 6-d.p.\\ value; the cube root evaluates to \\(1.322354\\)." }, { stepNumber: 10, description: "Round \\(x_{3}\\) and note the trend.", workingLatex: "x_{3} \\approx 1.3224 \\;\\text{(differences: } 0.26,\\ 0.052,\\ 0.010\\,)", explanation: "Successive jumps shrink by roughly a factor of \\(5\\): \\(0.26 \\to 0.052 \\to 0.010\\). This is the signature of linear convergence to a fixed point near \\(1.32\\) — exactly what we expect since \\(|g'(\\alpha)| \\approx 0.19\\) (see Q29)." } ], finalAnswer: "\\(x_{1} \\approx 1.2599,\\ x_{2} \\approx 1.3123,\\ x_{3} \\approx 1.3224\\)." } },
  { id: "y2nm2-003", topicRef: "y2nm2", topicTitle: "Iteration 03", difficulty: "Foundation", questionText: "Continuing the iteration \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\) from Q2, find \\(x_{4}\\) to 4 decimal places and state the root of \\(x^{3} - x - 1 = 0\\) to 2 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{compute one more iterate, then check 2-d.p.\\ stability}", explanation: "We extend the chain from Q2 by one step to obtain \\(x_{4}\\), then we examine the sequence and confirm that the 2-d.p.\\ value has stabilised before reading off the root." }, { stepNumber: 2, description: "Recall the unrounded \\(x_{3}\\) from Q2.", workingLatex: "x_{3} \\approx 1.322354", explanation: "Use the unrounded value carried over from the previous question (not the displayed \\(1.3224\\)) — this keeps the propagated error tiny." }, { stepNumber: 3, description: "Set up \\(x_{4} = g(x_{3})\\).", workingLatex: "x_{4} = \\sqrt[3]{x_{3} + 1} = \\sqrt[3]{1.322354 + 1}", explanation: "Substitute into the iteration formula \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\)." }, { stepNumber: 4, description: "Simplify the argument.", workingLatex: "x_{4} = \\sqrt[3]{2.322354}", explanation: "Add inside the cube root before evaluating — keeps the working tidy." }, { stepNumber: 5, description: "Evaluate the cube root.", workingLatex: "x_{4} = 1.324269\\ldots", explanation: "To 6 d.p. — enough that the 4-d.p.\\ rounding step is unambiguous." }, { stepNumber: 6, description: "Round \\(x_{4}\\) to 4 d.p.", workingLatex: "x_{4} \\approx 1.3243", explanation: "Fifth decimal is \\(6 \\geq 5\\), so the fourth decimal (\\(2\\)) rounds up to \\(3\\)." }, { stepNumber: 7, description: "Assemble the sequence so far.", workingLatex: "x_{1} = 1.2599,\\ x_{2} \\approx 1.3123,\\ x_{3} \\approx 1.3224,\\ x_{4} \\approx 1.3243", explanation: "The successive differences are \\(0.052,\\ 0.010,\\ 0.0019\\) — shrinking by a factor of about \\(5\\) each time, consistent with linear convergence." }, { stepNumber: 8, description: "Check stability at the 2-d.p.\\ tolerance.", workingLatex: "|x_{4} - x_{3}| \\approx 0.0019 < 0.005", explanation: "The 2-d.p.\\ tolerance is half a unit in the second decimal, namely \\(0.005\\). Since the latest change is well below this, all later iterates will also round to the same 2-d.p.\\ value." }, { stepNumber: 9, description: "Read off the 2-d.p.\\ root.", workingLatex: "x_{1} \\to 1.26,\\ x_{2} \\to 1.31,\\ x_{3},\\ x_{4} \\to 1.32", explanation: "Every iterate from \\(x_{3}\\) onwards rounds to \\(1.32\\) at 2 d.p., so we can confidently report this as the root." }, { stepNumber: 10, description: "Sanity-check by substituting into the original equation.", workingLatex: "f(1.3243) = 1.3243^{3} - 1.3243 - 1 \\approx -0.0018", explanation: "\\(f(\\alpha) \\approx 0\\) (the residual is \\(\\sim 10^{-3}\\)), confirming that \\(\\alpha \\approx 1.32\\) is indeed a root of \\(x^{3} - x - 1 = 0\\). The exact value is \\(\\alpha \\approx 1.32472\\) — the famous plastic number." } ], finalAnswer: "\\(x_{4} \\approx 1.3243\\); root is \\(1.32\\) to 2 d.p." } },
  { id: "y2nm2-004", topicRef: "y2nm2", topicTitle: "Iteration 04", difficulty: "Foundation", questionText: "State the iteration formula obtained by rearranging \\(x^{2} - 5 = 0\\) into \\(x = \\tfrac{5}{x}\\). Apply the iteration with \\(x_{0} = 2\\) and compute \\(x_{1}\\) and \\(x_{2}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x = \\displaystyle\\frac{5}{x} \\;\\Longrightarrow\\; x_{n+1} = \\displaystyle\\frac{5}{x_{n}}", explanation: "We write down the iteration, run it from \\(x_{0} = 2\\), watch what happens to the iterates, and then explain the behaviour using the convergence criterion \\(|g'(\\alpha)| < 1\\)." }, { stepNumber: 2, description: "Read off the iteration formula.", workingLatex: "x_{n+1} = \\displaystyle\\frac{5}{x_{n}}", explanation: "Promote the rearrangement \\(x = 5/x\\) into a recurrence by attaching subscripts: the right-hand side becomes \\(g(x_{n}) = 5/x_{n}\\)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) — substitute \\(x_{0} = 2\\).", workingLatex: "x_{1} = \\displaystyle\\frac{5}{x_{0}} = \\displaystyle\\frac{5}{2} = 2.5", explanation: "Exact value; no rounding required." }, { stepNumber: 4, description: "Compute \\(x_{2}\\) — substitute \\(x_{1} = 2.5\\).", workingLatex: "x_{2} = \\displaystyle\\frac{5}{x_{1}} = \\displaystyle\\frac{5}{2.5} = 2", explanation: "We are back to the starting value — an immediate red flag." }, { stepNumber: 5, description: "Reflect on what we are seeing.", workingLatex: "x_{0} = 2,\\ x_{1} = 2.5,\\ x_{2} = 2", explanation: "The iteration has returned to its start after two steps. The sequence is exactly 2-periodic — neither convergent nor divergent." }, { stepNumber: 6, description: "Confirm by computing \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{5}{2} = 2.5 = x_{1}", explanation: "The cycle \\(2 \\to 2.5 \\to 2 \\to 2.5 \\to \\cdots\\) repeats forever; the iteration never settles." }, { stepNumber: 7, description: "Identify the fixed point.", workingLatex: "\\alpha = \\displaystyle\\frac{5}{\\alpha} \\;\\Rightarrow\\; \\alpha^{2} = 5 \\;\\Rightarrow\\; \\alpha = \\sqrt{5} \\approx 2.2361", explanation: "The true fixed point sits exactly halfway between our two oscillation values — but the iteration cannot find it." }, { stepNumber: 8, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{5}{x} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{5}{x^{2}}", explanation: "Standard derivative of \\(5x^{-1}\\)." }, { stepNumber: 9, description: "Evaluate \\(g'\\) at the fixed point.", workingLatex: "g'(\\sqrt{5}) = -\\displaystyle\\frac{5}{(\\sqrt{5})^{2}} = -\\displaystyle\\frac{5}{5} = -1", explanation: "Plug \\(\\alpha = \\sqrt{5}\\) into \\(g'\\); the denominator simplifies because \\((\\sqrt{5})^{2} = 5\\)." }, { stepNumber: 10, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| = 1\\;\\not<\\;1", explanation: "The criterion \\(|g'(\\alpha)| < 1\\) fails on the boundary. The negative sign creates oscillation (cobweb), and the magnitude exactly \\(1\\) means the oscillations neither grow nor shrink — perfect 2-cycle, exactly as observed." }, { stepNumber: 11, description: "Conclude and suggest a fix.", workingLatex: "x_{1} = 2.5,\\ x_{2} = 2,\\ \\text{oscillates; useless scheme}", explanation: "A working rearrangement for \\(\\sqrt{5}\\) is the Babylonian \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + 5/x_{n})\\), for which \\(g'(\\sqrt{5}) = 0\\) — quadratic convergence instead of an endless cycle." } ], finalAnswer: "The sequence oscillates between 2 and 2.5 and does not converge." } },
  { id: "y2nm2-005", topicRef: "y2nm2", topicTitle: "Iteration 05", difficulty: "Foundation", questionText: "Use the iteration \\(x_{n+1} = \\cos x_{n}\\) with \\(x_{0} = 0.5\\) (radians). Find \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["iteration", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\cos x_{n},\\quad x_{0} = 0.5\\ \\text{(radians)}", explanation: "We feed \\(x_{0} = 0.5\\) into \\(\\cos\\) to obtain \\(x_{1}\\), then feed the unrounded \\(x_{1}\\) back to obtain \\(x_{2}\\). Each value is then displayed to 4 d.p." }, { stepNumber: 2, description: "Calculator mode check (common-mistake watch-out).", workingLatex: "\\text{set calculator to RAD; in DEG, } \\cos 0.5^{\\circ} \\approx 0.99996", explanation: "Switching to degrees by mistake collapses every step into essentially \\(1\\), and the iteration produces nonsense. Always confirm the angle unit before starting." }, { stepNumber: 3, description: "Compute \\(x_{1} = \\cos 0.5\\).", workingLatex: "x_{1} = \\cos 0.5 = 0.877582\\ldots", explanation: "Direct calculator evaluation in radian mode; keep 6 d.p.\\ internally." }, { stepNumber: 4, description: "Round \\(x_{1}\\) to 4 d.p.", workingLatex: "x_{1} \\approx 0.8776", explanation: "Fifth decimal is \\(8 \\geq 5\\), so round up: \\(7 \\to 8\\)." }, { stepNumber: 5, description: "Substitute the unrounded \\(x_{1}\\) into the formula.", workingLatex: "x_{2} = \\cos(x_{1}) = \\cos(0.877582)", explanation: "Carrying the full 6-d.p.\\ value avoids round-off contamination of \\(x_{2}\\)." }, { stepNumber: 6, description: "Evaluate \\(\\cos(0.877582)\\).", workingLatex: "x_{2} = 0.639012\\ldots", explanation: "Cosine decreases on \\((0, \\pi/2)\\), so the larger input \\(0.878\\) gives a smaller output than \\(\\cos 0.5\\) — exactly what we see." }, { stepNumber: 7, description: "Round \\(x_{2}\\) to 4 d.p.", workingLatex: "x_{2} \\approx 0.6390", explanation: "Fifth decimal is \\(1 < 5\\), round down." }, { stepNumber: 8, description: "Reflect on the oscillation.", workingLatex: "x_{0} = 0.5,\\ x_{1} \\approx 0.878,\\ x_{2} \\approx 0.639", explanation: "The iterate jumped up to \\(0.878\\) then dropped to \\(0.639\\) — it is bouncing around the fixed point rather than approaching it monotonically." }, { stepNumber: 9, description: "Diagnose the cobweb.", workingLatex: "g'(x) = -\\sin x,\\ g'(\\alpha) \\approx -\\sin 0.739 \\approx -0.674", explanation: "Negative derivative at the fixed point \\(\\alpha \\approx 0.7391\\) (the Dottie number) produces cobweb behaviour: errors flip sign each step. \\(|g'(\\alpha)| \\approx 0.67 < 1\\) so the iteration still converges, but slowly." } ], finalAnswer: "\\(x_{1} \\approx 0.8776,\\ x_{2} \\approx 0.6390\\)." } },
  { id: "y2nm2-006", topicRef: "y2nm2", topicTitle: "Iteration 06", difficulty: "Foundation", questionText: "Continuing Q5, compute \\(x_{3},\\ x_{4}\\) and \\(x_{5}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\cos x_{n},\\quad x_{2} = 0.639012\\ldots\\ (\\text{from Q5})", explanation: "We continue the chain by feeding the unrounded \\(x_{2}\\) into the formula, then iterate to obtain \\(x_{3}, x_{4}, x_{5}\\). Each iterate is computed at full precision and only rounded for display." }, { stepNumber: 2, description: "Compute \\(x_{3} = \\cos x_{2}\\).", workingLatex: "x_{3} = \\cos(0.639012)", explanation: "Substitute the carried unrounded value." }, { stepNumber: 3, description: "Evaluate and round \\(x_{3}\\).", workingLatex: "x_{3} = 0.802685\\ldots \\approx 0.8027", explanation: "Calculator in radian mode. Fifth decimal is \\(8\\) — round up. The iterate has jumped up: the cobweb pattern continues." }, { stepNumber: 4, description: "Set up \\(x_{4} = \\cos x_{3}\\).", workingLatex: "x_{4} = \\cos(0.802685)", explanation: "Carry the unrounded \\(x_{3}\\) forward, not the rounded display value." }, { stepNumber: 5, description: "Evaluate and round \\(x_{4}\\).", workingLatex: "x_{4} = 0.694778\\ldots \\approx 0.6948", explanation: "Cosine has dropped the value back down — the cobweb reverses direction. Fifth decimal is \\(7\\), round up." }, { stepNumber: 6, description: "Set up \\(x_{5} = \\cos x_{4}\\).", workingLatex: "x_{5} = \\cos(0.694778)", explanation: "Substitute the latest unrounded value." }, { stepNumber: 7, description: "Evaluate and round \\(x_{5}\\).", workingLatex: "x_{5} = 0.768196\\ldots \\approx 0.7682", explanation: "Back up again. Fifth decimal is \\(9\\), round up: \\(0.7681 \\to 0.7682\\)." }, { stepNumber: 8, description: "Tabulate the oscillation.", workingLatex: "x_{2} \\approx 0.6390,\\ x_{3} \\approx 0.8027,\\ x_{4} \\approx 0.6948,\\ x_{5} \\approx 0.7682", explanation: "Successive iterates alternate above and below the limit. The amplitude shrinks from \\(0.164\\) (between \\(x_{2}\\) and \\(x_{3}\\)) to \\(0.108\\) to \\(0.073\\) — about a factor of \\(\\sim 0.67\\) per step." }, { stepNumber: 9, description: "Diagnose using the convergence criterion.", workingLatex: "g'(x) = -\\sin x,\\ |g'(\\alpha)| = \\sin(0.7391) \\approx 0.674 < 1", explanation: "\\(|g'(\\alpha)| < 1\\) so the iteration converges; the negative sign explains the alternating cobweb pattern. The shrinkage factor of \\(\\sim 0.67\\) per step matches \\(|g'(\\alpha)|\\) exactly, as predicted by the linear-convergence theory." }, { stepNumber: 10, description: "State the limit.", workingLatex: "x_{n} \\to \\alpha \\approx 0.7391\\ \\text{(Dottie number)}", explanation: "The sequence is converging to the unique fixed point of \\(\\cos\\) — the famous Dottie number, \\(\\alpha = 0.739085\\ldots\\) — but it will take many more iterations to get four-d.p.\\ stability because the convergence rate (\\(0.67\\) per step) is only moderate." } ], finalAnswer: "\\(0.8027,\\ 0.6948,\\ 0.7682\\)." } },
  { id: "y2nm2-007", topicRef: "y2nm2", topicTitle: "Iteration 07", difficulty: "Foundation", questionText: "Show that the equation \\(x^{2} - 3x - 5 = 0\\) can be rearranged into \\(x = 3 + \\tfrac{5}{x}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy overview.", workingLatex: "x^{2} - 3x - 5 = 0 \\;\\longrightarrow\\; x = g(x)\\ \\text{with}\\ g(x) = 3 + \\displaystyle\\frac{5}{x}", explanation: "We will divide through by \\(x\\) (after confirming this is legitimate) to bring the quadratic down to a linear-plus-rational form, then collect the \\(x\\) on its own. The result is a fixed-point form ready for iteration." }, { stepNumber: 2, description: "Check the division by \\(x\\) is legitimate.", workingLatex: "x = 0 \\;\\Rightarrow\\; 0 - 0 - 5 = -5 \\neq 0", explanation: "\\(x = 0\\) is not a root of the original equation, so we may safely divide by \\(x\\) without losing any roots. (This check is essential — dividing by a variable can introduce or destroy solutions if not handled carefully.)" }, { stepNumber: 3, description: "Divide every term by \\(x\\).", workingLatex: "\\displaystyle\\frac{x^{2}}{x} - \\displaystyle\\frac{3x}{x} - \\displaystyle\\frac{5}{x} = 0", explanation: "Apply the operation term-by-term so the structure of the equation is visible." }, { stepNumber: 4, description: "Simplify each term.", workingLatex: "x - 3 - \\displaystyle\\frac{5}{x} = 0", explanation: "\\(x^{2}/x = x\\); \\(3x/x = 3\\); the last term \\(5/x\\) cannot simplify further. We now have a linear-plus-rational expression equal to zero." }, { stepNumber: 5, description: "Move the \\(-3\\) to the other side.", workingLatex: "x - \\displaystyle\\frac{5}{x} = 3", explanation: "Add \\(3\\) to both sides." }, { stepNumber: 6, description: "Move the \\(-5/x\\) across as well.", workingLatex: "x = 3 + \\displaystyle\\frac{5}{x}", explanation: "Add \\(5/x\\) to both sides. The single \\(x\\) is now isolated on the left; the right-hand side is a function of \\(x\\)." }, { stepNumber: 7, description: "Conclude.", workingLatex: "x = 3 + \\displaystyle\\frac{5}{x} \\quad\\text{Shown.}", explanation: "This is the required fixed-point form \\(x = g(x)\\) with \\(g(x) = 3 + 5/x\\)." }, { stepNumber: 8, description: "Promote to a recurrence.", workingLatex: "x_{n+1} = 3 + \\displaystyle\\frac{5}{x_{n}}", explanation: "Attach subscripts. The corresponding iteration is now ready to be applied with any reasonable starting value." }, { stepNumber: 9, description: "Quick sanity sketch.", workingLatex: "g(4) = 3 + 1.25 = 4.25,\\ g(5) = 3 + 1 = 4,\\ g(4.2) = 3 + 1.19\\ldots \\approx 4.19", explanation: "Values of \\(g\\) near \\(x = 4\\) hover around \\(4.2\\) — encouraging, since the larger root of \\(x^{2} - 3x - 5\\) is \\((3+\\sqrt{29})/2 \\approx 4.193\\)." } ], finalAnswer: "Shown." } },
  { id: "y2nm2-008", topicRef: "y2nm2", topicTitle: "Iteration 08", difficulty: "Foundation", questionText: "Apply the iteration \\(x_{n+1} = 3 + \\tfrac{5}{x_{n}}\\) with \\(x_{0} = 4\\). Find \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = 3 + \\displaystyle\\frac{5}{x_{n}},\\quad x_{0} = 4", explanation: "Substitute \\(x_{0} = 4\\) into the recurrence to get \\(x_{1}\\), then substitute the unrounded \\(x_{1}\\) to obtain \\(x_{2}\\). Each value is displayed to 4 d.p." }, { stepNumber: 2, description: "Set up \\(x_{1} = g(x_{0})\\).", workingLatex: "x_{1} = 3 + \\displaystyle\\frac{5}{4}", explanation: "Plug \\(x_{0} = 4\\) into the formula \\(g(x) = 3 + 5/x\\)." }, { stepNumber: 3, description: "Evaluate the reciprocal term.", workingLatex: "\\displaystyle\\frac{5}{4} = 1.25\\ \\text{(exact)}", explanation: "\\(5\\) divided by \\(4\\) is a terminating decimal — no rounding required." }, { stepNumber: 4, description: "Sum and report \\(x_{1}\\).", workingLatex: "x_{1} = 3 + 1.25 = 4.2500\\ \\text{(4 d.p.)}", explanation: "Already exact at 4 d.p.\\ so no rounding error to track." }, { stepNumber: 5, description: "Set up \\(x_{2} = g(x_{1})\\).", workingLatex: "x_{2} = 3 + \\displaystyle\\frac{5}{4.25}", explanation: "Substitute the unrounded \\(x_{1} = 4.25\\) into the formula." }, { stepNumber: 6, description: "Evaluate the reciprocal term.", workingLatex: "\\displaystyle\\frac{5}{4.25} = \\displaystyle\\frac{20}{17} = 1.176470\\ldots", explanation: "Cleaner as a fraction: \\(5/4.25 = 5 \\times (4/17) = 20/17\\), giving the recurring decimal \\(1.176470\\overline{588235}\\)." }, { stepNumber: 7, description: "Sum to get \\(x_{2}\\).", workingLatex: "x_{2} = 3 + 1.176470\\ldots = 4.176470\\ldots", explanation: "Keep 6 d.p.\\ for the next step (we won't need them here, but it's good practice)." }, { stepNumber: 8, description: "Round \\(x_{2}\\) to 4 d.p.", workingLatex: "x_{2} \\approx 4.1765", explanation: "Fifth decimal is \\(7 \\geq 5\\), so the fourth (\\(4\\)) rounds up to \\(5\\)." }, { stepNumber: 9, description: "Reflect on convergence.", workingLatex: "x_{0} = 4,\\ x_{1} = 4.25,\\ x_{2} \\approx 4.1765;\\ \\alpha = \\displaystyle\\frac{3+\\sqrt{29}}{2} \\approx 4.193", explanation: "The iterates bracket the larger root \\(\\alpha \\approx 4.193\\) — first overshooting at \\(4.25\\), then undershooting at \\(4.1765\\). \\(g'(x) = -5/x^{2}\\) gives \\(g'(\\alpha) \\approx -0.284\\), so the convergence is cobweb-like with shrinkage factor \\(\\sim 0.28\\) per step." } ], finalAnswer: "\\(x_{1} = 4.25,\\ x_{2} \\approx 4.1765\\)." } },
  { id: "y2nm2-009", topicRef: "y2nm2", topicTitle: "Iteration 09", difficulty: "Foundation", questionText: "Verify that \\(x = \\tfrac{1}{2}(x^{2} + 1)\\) is a rearrangement of \\(x^{2} - 2x + 1 = 0\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{2} - 2x + 1 = 0 \\;\\longrightarrow\\; x = \\displaystyle\\frac{1}{2}(x^{2} + 1)", explanation: "We will move the linear term \\(-2x\\) across to the other side, swap sides so the lone \\(2x\\) sits on the left, and divide by 2 to isolate a single \\(x\\). Every step is reversible, so the rearrangement is equivalent (no roots gained or lost)." }, { stepNumber: 2, description: "Start with the given equation.", workingLatex: "x^{2} - 2x + 1 = 0", explanation: "Observe in passing that \\(x^{2} - 2x + 1 = (x - 1)^{2}\\), so the only root is \\(x = 1\\) (a repeated root). This will become important when we analyse convergence." }, { stepNumber: 3, description: "Add \\(2x\\) to both sides.", workingLatex: "x^{2} + 1 = 2x", explanation: "This isolates the single \\(x\\) (in the form \\(2x\\)) on one side and the quadratic + constant on the other." }, { stepNumber: 4, description: "Swap sides for readability.", workingLatex: "2x = x^{2} + 1", explanation: "Putting the \\(2x\\) on the left makes the next step (dividing by \\(2\\)) clearer." }, { stepNumber: 5, description: "Divide both sides by \\(2\\).", workingLatex: "x = \\displaystyle\\frac{x^{2} + 1}{2}", explanation: "Dividing by \\(2\\) is always valid (\\(2 \\neq 0\\)), so no roots are introduced or removed." }, { stepNumber: 6, description: "Factor out the \\(\\tfrac{1}{2}\\).", workingLatex: "x = \\displaystyle\\frac{1}{2}\\left(x^{2} + 1\\right) \\quad\\text{Shown.}", explanation: "This is the required rearrangement \\(x = g(x)\\) with \\(g(x) = \\tfrac{1}{2}(x^{2} + 1)\\)." }, { stepNumber: 7, description: "Write down the corresponding iteration.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{2}(x_{n}^{2} + 1)", explanation: "Promote the rearrangement to a recurrence by attaching subscripts." }, { stepNumber: 8, description: "Check convergence at the fixed point.", workingLatex: "g'(x) = x \\;\\Rightarrow\\; g'(1) = 1", explanation: "\\(g(x) = \\tfrac{1}{2}(x^{2} + 1)\\) differentiates to \\(g'(x) = x\\), so at the (only) fixed point \\(\\alpha = 1\\), \\(|g'(\\alpha)| = 1\\). The convergence criterion \\(|g'(\\alpha)| < 1\\) just fails — this is the boundary (neutral) case." }, { stepNumber: 9, description: "Watch-out: what this means for iteration.", workingLatex: "x_{0} > 1 \\;\\Rightarrow\\; x_{1} > x_{0};\\ \\text{iteration escapes}", explanation: "Common mistake: students assume that any rearrangement gives a convergent iteration. Here, for \\(x_{0}\\) just above \\(1\\), \\(g(x_{0}) = \\tfrac{1}{2}(x_{0}^{2} + 1) > x_{0}\\), so the iterates run away. For \\(x_{0} < 1\\) they creep toward \\(1\\) but agonisingly slowly. The boundary case is delicate." } ], finalAnswer: "Shown." } },
  { id: "y2nm2-010", topicRef: "y2nm2", topicTitle: "Iteration 10", difficulty: "Foundation", questionText: "Rearrange the equation \\(x^{3} + 2x - 5 = 0\\) into the iterative form \\(x = \\sqrt[3]{5 - 2x}\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{3} + 2x - 5 = 0 \\;\\longrightarrow\\; x = \\sqrt[3]{5 - 2x}", explanation: "We read the target backwards: the cube on the right is undone by a cube root, so we need to isolate \\(x^{3}\\) first, then cube-root both sides. Every step is reversible (cube root is one-to-one on \\(\\mathbb{R}\\))." }, { stepNumber: 2, description: "Start from the given equation.", workingLatex: "x^{3} + 2x - 5 = 0", explanation: "A cubic with a linear-plus-constant tail. The two non-cubic terms are \\(+2x\\) and \\(-5\\)." }, { stepNumber: 3, description: "Move \\(+2x\\) to the right.", workingLatex: "x^{3} - 5 = -2x", explanation: "Subtract \\(2x\\) from both sides." }, { stepNumber: 4, description: "Move \\(-5\\) to the right as well.", workingLatex: "x^{3} = 5 - 2x", explanation: "Add \\(5\\) to both sides. The cubic now stands alone on the left." }, { stepNumber: 5, description: "Take the real cube root of both sides.", workingLatex: "\\sqrt[3]{x^{3}} = \\sqrt[3]{5 - 2x}", explanation: "Cube-rooting is one-to-one on \\(\\mathbb{R}\\) (unlike the even-index square root). No \\(\\pm\\) ambiguity and no extraneous solutions appear." }, { stepNumber: 6, description: "Simplify the left side.", workingLatex: "\\sqrt[3]{x^{3}} = x", explanation: "True for all real \\(x\\)." }, { stepNumber: 7, description: "Read off the rearrangement.", workingLatex: "x = \\sqrt[3]{5 - 2x} \\quad\\text{Shown.}", explanation: "This is the required \\(x = g(x)\\) form with \\(g(x) = \\sqrt[3]{5 - 2x}\\)." }, { stepNumber: 8, description: "Preview convergence behaviour.", workingLatex: "g'(x) = -\\displaystyle\\frac{2}{3}(5 - 2x)^{-2/3};\\ g'(1.33) \\approx -0.378", explanation: "At the root \\(\\alpha \\approx 1.33\\), \\(|g'(\\alpha)| \\approx 0.38 < 1\\), so the iteration \\(x_{n+1} = \\sqrt[3]{5 - 2x_{n}}\\) will converge — with error shrinking by a factor of about \\(2.6\\) per step. The negative sign tells us the convergence is cobweb-like (alternating)." } ], finalAnswer: "Shown." } },
  { id: "y2nm2-011", topicRef: "y2nm2", topicTitle: "Iteration 11", difficulty: "Foundation", questionText: "Apply \\(x_{n+1} = \\sqrt{x_{n} + 1}\\) with \\(x_{0} = 1\\). Find \\(x_{1},\\ x_{2}\\) and \\(x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\sqrt{x_{n} + 1},\\quad x_{0} = 1", explanation: "We compute \\(x_{1}, x_{2}, x_{3}\\) by substituting each unrounded iterate into the formula, then round only for display. The fixed-point equation is \\(\\alpha^{2} - \\alpha - 1 = 0\\), the golden-ratio quadratic — so we expect convergence to \\(\\varphi \\approx 1.618\\)." }, { stepNumber: 2, description: "Compute \\(x_{1} = \\sqrt{x_{0} + 1}\\).", workingLatex: "x_{1} = \\sqrt{1 + 1} = \\sqrt{2}", explanation: "Substitute \\(x_{0} = 1\\) into the formula." }, { stepNumber: 3, description: "Evaluate \\(\\sqrt{2}\\).", workingLatex: "x_{1} = 1.414213\\ldots", explanation: "Standard value of \\(\\sqrt{2}\\); keep 6 d.p.\\ internally." }, { stepNumber: 4, description: "Round \\(x_{1}\\) to 4 d.p.", workingLatex: "x_{1} \\approx 1.4142", explanation: "Fifth decimal is \\(1 < 5\\), round down." }, { stepNumber: 5, description: "Set up \\(x_{2} = \\sqrt{x_{1} + 1}\\) with the unrounded value.", workingLatex: "x_{2} = \\sqrt{1.414213 + 1} = \\sqrt{2.414213}", explanation: "Add inside the radical before taking the square root." }, { stepNumber: 6, description: "Evaluate and round \\(x_{2}\\).", workingLatex: "x_{2} = 1.553774\\ldots \\approx 1.5538", explanation: "Fifth decimal is \\(7 \\geq 5\\), so the fourth (\\(7\\)) rounds up to \\(8\\)." }, { stepNumber: 7, description: "Set up \\(x_{3} = \\sqrt{x_{2} + 1}\\) with the unrounded \\(x_{2}\\).", workingLatex: "x_{3} = \\sqrt{1.553774 + 1} = \\sqrt{2.553774}", explanation: "Continue carrying full precision." }, { stepNumber: 8, description: "Evaluate and round \\(x_{3}\\).", workingLatex: "x_{3} = 1.598053\\ldots \\approx 1.5981", explanation: "Fifth decimal is \\(5\\), round up." }, { stepNumber: 9, description: "Watch the gaps shrink.", workingLatex: "\\Delta_{1} = 0.414,\\ \\Delta_{2} = 0.140,\\ \\Delta_{3} = 0.044", explanation: "Successive differences shrink by roughly a factor of \\(0.31\\) per step — a clean signature of linear convergence." }, { stepNumber: 10, description: "Identify the limit and shrinkage factor.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2\\sqrt{x+1}};\\ g'(\\varphi) = \\displaystyle\\frac{1}{2\\varphi} \\approx 0.309", explanation: "At the fixed point \\(\\alpha = \\varphi = (1+\\sqrt{5})/2 \\approx 1.6180\\), \\(g'(\\varphi) \\approx 0.309 > 0\\) — positive, so this is staircase convergence (monotone increasing). The \\(0.31\\)-per-step rate matches the observed shrinkage exactly." } ], finalAnswer: "\\(1.4142,\\ 1.5538,\\ 1.5981\\)." } },
  { id: "y2nm2-012", topicRef: "y2nm2", topicTitle: "Iteration 12", difficulty: "Foundation", questionText: "The iteration \\(x_{n+1} = \\sqrt{x_{n} + 1}\\) converges to a root \\(\\alpha\\). State the equation satisfied by \\(\\alpha\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy: pass to the limit in the recurrence.", workingLatex: "x_{n+1} = g(x_{n}),\\ x_{n} \\to \\alpha \\;\\Rightarrow\\; \\alpha = g(\\alpha)", explanation: "If a sequence converges to \\(\\alpha\\), both \\(x_{n}\\) and \\(x_{n+1}\\) (just a re-indexing) converge to the same \\(\\alpha\\). Substituting the limit into both sides of the recurrence gives the fixed-point equation." }, { stepNumber: 2, description: "Why the fixed-point condition takes this form.", workingLatex: "\\text{a fixed point is a value the iteration sends to itself}", explanation: "Geometrically, \\(\\alpha\\) is where the curve \\(y = g(x)\\) crosses the line \\(y = x\\): at that point, applying \\(g\\) leaves the value unchanged." }, { stepNumber: 3, description: "Substitute \\(x_{n+1} = x_{n} = \\alpha\\) into the given iteration.", workingLatex: "\\alpha = \\sqrt{\\alpha + 1}", explanation: "This is the defining equation for the fixed point of the specific iteration we are given." }, { stepNumber: 4, description: "Square both sides.", workingLatex: "\\alpha^{2} = \\alpha + 1", explanation: "Both sides are non-negative (the limit is positive, and the square root of a positive number is positive), so squaring is reversible — no extraneous solution is introduced." }, { stepNumber: 5, description: "Rearrange to standard polynomial form.", workingLatex: "\\alpha^{2} - \\alpha - 1 = 0", explanation: "Subtract \\(\\alpha + 1\\) from both sides so the right-hand side is zero. This is the equation \\(\\alpha\\) satisfies." }, { stepNumber: 6, description: "Apply the quadratic formula to identify the value.", workingLatex: "\\alpha = \\displaystyle\\frac{1 \\pm \\sqrt{1 + 4}}{2} = \\displaystyle\\frac{1 \\pm \\sqrt{5}}{2}", explanation: "Discriminant \\(b^{2} - 4ac = 1 + 4 = 5\\); two real roots." }, { stepNumber: 7, description: "Select the positive root.", workingLatex: "\\alpha = \\displaystyle\\frac{1 + \\sqrt{5}}{2} \\approx 1.6180", explanation: "The minus branch gives \\(\\approx -0.618\\), which contradicts \\(\\sqrt{\\alpha + 1} > 0\\). So we keep only the positive root — the famous golden ratio \\(\\varphi\\)." }, { stepNumber: 8, description: "Sanity-check by substitution.", workingLatex: "\\sqrt{1.6180 + 1} = \\sqrt{2.6180} = 1.6180\\ \\checkmark", explanation: "Plugging \\(\\varphi\\) back into \\(\\sqrt{x + 1}\\) reproduces \\(\\varphi\\) — confirming that this is the limit the iteration found." }, { stepNumber: 9, description: "Geometric watch-out.", workingLatex: "\\alpha \\approx -0.618\\ \\text{is also a root of } \\alpha^{2} - \\alpha - 1 = 0", explanation: "Common mistake: squaring \\(\\alpha = \\sqrt{\\alpha + 1}\\) introduces both roots of the quadratic, but only the positive one actually solves the original square-root equation. Always check after squaring." } ], finalAnswer: "\\(\\alpha^{2} - \\alpha - 1 = 0\\) (the golden ratio)." } },
  { id: "y2nm2-013", topicRef: "y2nm2", topicTitle: "Iteration 13", difficulty: "Foundation", questionText: "A fixed point of the iteration \\(x_{n+1} = g(x_{n})\\) satisfies which equation? Explain in one line.", marks: 1, examStyle: false, yearCreated: 2026, tags: ["fixed point", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy: derive the equation from the definition.", workingLatex: "\\text{Fixed point} \\;\\longleftrightarrow\\; \\text{stays the same under iteration}", explanation: "We make the definition precise, substitute it into the recurrence, and read off the equation. The whole argument is a single substitution." }, { stepNumber: 2, description: "Define a fixed point.", workingLatex: "\\alpha\\ \\text{is a fixed point of } g \\;\\Longleftrightarrow\\; g(\\alpha) = \\alpha", explanation: "A value that the function \\(g\\) sends to itself — applying \\(g\\) does nothing to it." }, { stepNumber: 3, description: "Translate to the iteration setting.", workingLatex: "x_{n} = \\alpha \\;\\Rightarrow\\; x_{n+1} = g(\\alpha) = \\alpha", explanation: "If the iteration is currently sitting at \\(\\alpha\\), the next value is also \\(\\alpha\\) — the sequence is stuck (in a good way)." }, { stepNumber: 4, description: "Read off the algebraic condition.", workingLatex: "x_{n+1} = x_{n} \\;\\Longleftrightarrow\\; g(\\alpha) = \\alpha", explanation: "The 'no change' requirement is exactly the equation \\(g(\\alpha) = \\alpha\\)." }, { stepNumber: 5, description: "State the answer.", workingLatex: "\\alpha = g(\\alpha)", explanation: "This is the equation every fixed point satisfies — and is the form we always use to compute the equation \\(\\alpha\\) solves." }, { stepNumber: 6, description: "Geometric interpretation.", workingLatex: "y = g(x)\\ \\text{meets}\\ y = x\\ \\text{at}\\ x = \\alpha", explanation: "On a graph, fixed points are exactly the crossings of \\(y = g(x)\\) with the diagonal line \\(y = x\\). This is why cobweb diagrams use that diagonal as a reflection line — to read \\(x_{n+1}\\) back into the next \\(x_{n}\\)." }, { stepNumber: 7, description: "Common-mistake watch-out.", workingLatex: "g(\\alpha) = \\alpha\\ \\text{(not}\\ g'(\\alpha) = \\alpha\\text{)}", explanation: "Students sometimes confuse the fixed-point condition with the convergence criterion \\(|g'(\\alpha)| < 1\\). The former defines what \\(\\alpha\\) is; the latter decides whether iteration can find it." }, { stepNumber: 8, description: "Note the link to root-finding.", workingLatex: "g(\\alpha) = \\alpha \\;\\Longleftrightarrow\\; f(\\alpha) = 0\\ \\text{with}\\ f(x) = x - g(x)", explanation: "Fixed points of \\(g\\) are exactly the roots of \\(f(x) = x - g(x)\\). Iteration and root-finding are the same problem in two languages — explored more fully in Q14." } ], finalAnswer: "\\(\\alpha = g(\\alpha)\\)." } },
  { id: "y2nm2-014", topicRef: "y2nm2", topicTitle: "Iteration 14", difficulty: "Foundation", questionText: "Explain why solving \\(x = g(x)\\) is equivalent to finding a root of \\(x - g(x) = 0\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{prove}\\ \\{x: x = g(x)\\} = \\{x: x - g(x) = 0\\}", explanation: "We show the two solution sets coincide by proving both inclusions (forward and reverse), using nothing more than the reversible operation of adding/subtracting \\(g(x)\\)." }, { stepNumber: 2, description: "Introduce \\(f\\).", workingLatex: "f(x) := x - g(x)", explanation: "Define a new function whose zeros we want to study. The set we are after is \\(\\{x: f(x) = 0\\}\\)." }, { stepNumber: 3, description: "Forward direction: fixed point implies root.", workingLatex: "x = g(x) \\;\\Rightarrow\\; x - g(x) = 0", explanation: "Subtract \\(g(x)\\) from both sides — a single reversible operation." }, { stepNumber: 4, description: "Rewrite using \\(f\\).", workingLatex: "x - g(x) = 0 \\;\\Rightarrow\\; f(x) = 0", explanation: "By definition of \\(f\\). So every fixed point of \\(g\\) is a root of \\(f\\)." }, { stepNumber: 5, description: "Reverse direction: root implies fixed point.", workingLatex: "f(x) = 0 \\;\\Rightarrow\\; x - g(x) = 0", explanation: "Just unpack the definition of \\(f\\)." }, { stepNumber: 6, description: "Add \\(g(x)\\) to both sides.", workingLatex: "x - g(x) = 0 \\;\\Rightarrow\\; x = g(x)", explanation: "Reverses step 3. So every root of \\(f\\) is a fixed point of \\(g\\)." }, { stepNumber: 7, description: "Combine.", workingLatex: "\\{x: x = g(x)\\} = \\{x: f(x) = 0\\}", explanation: "Both inclusions hold, so the two solution sets are identical — not just numerically equal but the same set of points." }, { stepNumber: 8, description: "Practical takeaway.", workingLatex: "f(x) = 0 \\;\\longleftrightarrow\\; x = g(x)", explanation: "This duality is why every root-finding problem can be recast as iteration (just pick a rearrangement) and every iteration converges to a root of \\(f(x) = x - g(x)\\). Choosing \\(g\\) cleverly is the art of making the iteration converge fast." } ], finalAnswer: "Roots of \\(f(x) = x - g(x)\\) are precisely the fixed points of \\(g\\)." } },
  { id: "y2nm2-015", topicRef: "y2nm2", topicTitle: "Iteration 15", difficulty: "Foundation", questionText: "Show that \\(x^{2} - 6 = 0\\) can be rearranged as \\(x = \\tfrac{1}{2}\\!\\left(x + \\tfrac{6}{x}\\right)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{2} = 6 \\;\\longrightarrow\\; x = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{6}{x}\\right)", explanation: "We will derive two equivalent expressions for the root, namely \\(x\\) itself and \\(6/x\\), then average them. The arithmetic mean of two equal quantities is again the same quantity — so the mean is also equal to \\(x\\) at the root." }, { stepNumber: 2, description: "Isolate \\(x^{2}\\).", workingLatex: "x^{2} - 6 = 0 \\;\\Longleftrightarrow\\; x^{2} = 6", explanation: "Add \\(6\\) to both sides." }, { stepNumber: 3, description: "Check that dividing by \\(x\\) is legitimate.", workingLatex: "x = 0 \\;\\Rightarrow\\; 0 - 6 = -6 \\neq 0", explanation: "Zero is not a root, so we lose nothing by dividing by \\(x\\)." }, { stepNumber: 4, description: "Divide by \\(x\\) to obtain a second expression.", workingLatex: "x = \\displaystyle\\frac{6}{x}", explanation: "Both sides of this equation evaluate to \\(\\sqrt{6}\\) at the positive root. So at \\(x = \\sqrt{6}\\), the quantity \\(6/x\\) equals \\(x\\) itself." }, { stepNumber: 5, description: "Average the two expressions.", workingLatex: "\\text{Mean of } x \\text{ and } \\displaystyle\\frac{6}{x} = \\displaystyle\\frac{1}{2}\\left(x + \\displaystyle\\frac{6}{x}\\right)", explanation: "Standard arithmetic mean of two quantities — sum them, divide by two." }, { stepNumber: 6, description: "Argue that the mean equals \\(x\\) at the root.", workingLatex: "x = \\displaystyle\\frac{6}{x} \\;\\Rightarrow\\; \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{6}{x}\\right) = \\displaystyle\\frac{1}{2}(x + x) = x", explanation: "At the root, the two quantities being averaged are equal, so their mean is the same value — namely \\(x\\)." }, { stepNumber: 7, description: "Read off the rearrangement.", workingLatex: "x = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{6}{x}\\right) \\quad\\text{Shown.}", explanation: "This is the required fixed-point form. The corresponding iteration is \\(x_{n+1} = \\tfrac{1}{2}\\!\\left(x_{n} + 6/x_{n}\\right)\\)." }, { stepNumber: 8, description: "Differentiate \\(g\\) and evaluate at the root.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{6}{x^{2}}\\right);\\ g'(\\sqrt{6}) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{6}{6}\\right) = 0", explanation: "Differentiate using the quotient/chain rule. At \\(\\alpha = \\sqrt{6}\\), we have \\(\\alpha^{2} = 6\\), so the bracket vanishes." }, { stepNumber: 9, description: "Why averaging works so well.", workingLatex: "g'(\\alpha) = 0 \\;\\Rightarrow\\; \\text{quadratic convergence}", explanation: "Vanishing first derivative at the fixed point means the linear error term disappears — the next iterate's error is proportional to the square of the previous error. Each step roughly doubles the number of correct digits. This is the Babylonian/Newton scheme — vastly superior to \\(x = 6/x\\) (which has \\(g'(\\sqrt 6) = -1\\) and cycles)." } ], finalAnswer: "Shown (this is the Babylonian iteration)." } },
  { id: "y2nm2-016", topicRef: "y2nm2", topicTitle: "Iteration 16", difficulty: "Standard", questionText: "Apply the iteration \\(x_{n+1} = \\tfrac{1}{2}\\!\\left(x_{n} + \\tfrac{6}{x_{n}}\\right)\\) with \\(x_{0} = 2\\). Find \\(x_{1},\\ x_{2}\\) and \\(x_{3}\\) to 4 decimal places and compare with \\(\\sqrt{6}\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{2}\\!\\left(x_{n} + \\displaystyle\\frac{6}{x_{n}}\\right),\\quad x_{0} = 2", explanation: "We compute \\(x_{1}, x_{2}, x_{3}\\) by repeated averaging, then compare with \\(\\sqrt{6} \\approx 2.4495\\). Since \\(g'(\\sqrt{6}) = 0\\) (see Q15), we expect quadratic convergence — the number of correct digits should roughly double each step." }, { stepNumber: 2, description: "Compute \\(x_{1}\\) — substitute \\(x_{0} = 2\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}\\!\\left(2 + \\displaystyle\\frac{6}{2}\\right) = \\displaystyle\\frac{1}{2}(2 + 3) = \\displaystyle\\frac{5}{2}", explanation: "\\(6/2 = 3\\) exactly; the mean of \\(2\\) and \\(3\\) is \\(2.5\\)." }, { stepNumber: 3, description: "Report \\(x_{1}\\).", workingLatex: "x_{1} = 2.5000\\ \\text{(exact)}", explanation: "No rounding required." }, { stepNumber: 4, description: "Compute the reciprocal term for \\(x_{2}\\).", workingLatex: "\\displaystyle\\frac{6}{2.5} = 2.4\\ \\text{(exact)}", explanation: "Short division gives a terminating decimal." }, { stepNumber: 5, description: "Average to get \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}(2.5 + 2.4) = \\displaystyle\\frac{4.9}{2} = 2.4500", explanation: "Already correct to 2 d.p.\\ at \\(\\sqrt{6} \\approx 2.4495\\) — only one step from the start." }, { stepNumber: 6, description: "Compute the reciprocal term for \\(x_{3}\\).", workingLatex: "\\displaystyle\\frac{6}{2.45} = 2.448979\\ldots\\ (\\text{recurring})", explanation: "\\(6/2.45 = 600/245 = 120/49\\); we keep 6 d.p." }, { stepNumber: 7, description: "Average to get \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}(2.45 + 2.448979) = \\displaystyle\\frac{4.898979}{2} = 2.449490\\ldots", explanation: "The sum is \\(4.898979\\); halve it for the mean." }, { stepNumber: 8, description: "Round \\(x_{3}\\) to 4 d.p.", workingLatex: "x_{3} \\approx 2.4495", explanation: "Strictly \\(2.449490\\ldots \\to 2.4495\\) (fifth decimal \\(9\\), round up)." }, { stepNumber: 9, description: "Compare with \\(\\sqrt{6}\\).", workingLatex: "\\sqrt{6} = 2.449489\\ldots \\approx 2.4495\\ \\text{(4 d.p.)}", explanation: "\\(x_{3}\\) and \\(\\sqrt{6}\\) agree to 4 d.p.\\ already." }, { stepNumber: 10, description: "Confirm quadratic convergence.", workingLatex: "|x_{1} - \\sqrt{6}| \\approx 0.05;\\ |x_{2} - \\sqrt{6}| \\approx 5.1\\times 10^{-4};\\ |x_{3} - \\sqrt{6}| \\approx 5.3\\times 10^{-8}", explanation: "Each error is roughly the square of the previous one — quadratic convergence in action. Errors go \\(\\sim 0.05 \\to \\sim 5\\times 10^{-4} \\to \\sim 5\\times 10^{-8}\\): about \\(1, 3, 7\\) correct digits — doubling each step, exactly as predicted by \\(g'(\\alpha) = 0\\)." } ], finalAnswer: "Converges rapidly to \\(\\sqrt{6}\\)." } },
  { id: "y2nm2-017", topicRef: "y2nm2", topicTitle: "Iteration 17", difficulty: "Standard", questionText: "Apply \\(x_{n+1} = \\ln(x_{n} + 3)\\) with \\(x_{0} = 2\\). Find \\(x_{1},\\ x_{2}\\) and \\(x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\ln(x_{n} + 3),\\quad x_{0} = 2", explanation: "We feed each unrounded iterate into the natural logarithm to obtain the next, then round only for display. Natural log (base \\(e\\)) — the argument \\(x + 3\\) is positive for \\(x > -3\\), so the iteration is well-defined throughout." }, { stepNumber: 2, description: "Compute \\(x_{1} = \\ln(x_{0} + 3)\\).", workingLatex: "x_{1} = \\ln(2 + 3) = \\ln 5", explanation: "Substitute \\(x_{0} = 2\\). The argument simplifies to \\(5\\)." }, { stepNumber: 3, description: "Evaluate \\(\\ln 5\\).", workingLatex: "x_{1} = 1.609437\\ldots", explanation: "Standard value; \\(\\ln 5 = \\ln 10 - \\ln 2 \\approx 2.3026 - 0.6931 = 1.6094\\). Keep 6 d.p.\\ internally." }, { stepNumber: 4, description: "Round \\(x_{1}\\) to 4 d.p.", workingLatex: "x_{1} \\approx 1.6094", explanation: "Fifth decimal is \\(3 < 5\\), round down." }, { stepNumber: 5, description: "Set up \\(x_{2} = \\ln(x_{1} + 3)\\).", workingLatex: "x_{2} = \\ln(1.609437 + 3) = \\ln(4.609437)", explanation: "Use the unrounded \\(x_{1}\\) — propagating the rounded \\(1.6094\\) would seed a tiny error." }, { stepNumber: 6, description: "Evaluate and round \\(x_{2}\\).", workingLatex: "x_{2} = 1.528105\\ldots \\approx 1.5281", explanation: "Fifth decimal is \\(0\\), round down. The iterate has dropped — the iteration is heading downwards toward the limit." }, { stepNumber: 7, description: "Set up \\(x_{3} = \\ln(x_{2} + 3)\\).", workingLatex: "x_{3} = \\ln(1.528105 + 3) = \\ln(4.528105)", explanation: "Carry the unrounded \\(x_{2}\\) forward." }, { stepNumber: 8, description: "Evaluate and round \\(x_{3}\\).", workingLatex: "x_{3} = 1.510303\\ldots \\approx 1.5103", explanation: "Fifth decimal is \\(0\\), round down." }, { stepNumber: 9, description: "Inspect the shrinkage.", workingLatex: "\\Delta_{1} \\approx 0.39,\\ \\Delta_{2} \\approx 0.081,\\ \\Delta_{3} \\approx 0.018", explanation: "Each successive difference is about \\(0.22\\) times the previous one — clean linear convergence." }, { stepNumber: 10, description: "Diagnose using the convergence criterion.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{x + 3};\\ g'(1.505) \\approx 0.222", explanation: "At the fixed point \\(\\alpha \\approx 1.5052\\), \\(|g'(\\alpha)| = 1/(1.5052 + 3) \\approx 0.222 < 1\\). Positive derivative means staircase (monotone) convergence — the iterates approach from one side. The shrinkage factor \\(0.22\\) matches the observed decay perfectly." } ], finalAnswer: "\\(1.6094,\\ 1.5281,\\ 1.5103\\)." } },
  { id: "y2nm2-018", topicRef: "y2nm2", topicTitle: "Iteration 18", difficulty: "Standard", questionText: "Rearrange \\(e^{x} - x - 2 = 0\\) into \\(x = \\ln(x + 2)\\) and apply the iteration with \\(x_{0} = 1\\) to find \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "e^{x} = x + 2 \\;\\longrightarrow\\; x = \\ln(x + 2)", explanation: "We isolate \\(e^{x}\\) (the awkward term), undo with \\(\\ln\\), and run the resulting iteration with \\(x_{0} = 1\\). Each iterate is computed at full precision and only rounded to 4 d.p.\\ for display." }, { stepNumber: 2, description: "Start from the given equation.", workingLatex: "e^{x} - x - 2 = 0", explanation: "An equation mixing exponential and polynomial parts — not solvable in closed form, so iteration is the right tool." }, { stepNumber: 3, description: "Isolate \\(e^{x}\\).", workingLatex: "e^{x} = x + 2", explanation: "Add \\(x + 2\\) to both sides." }, { stepNumber: 4, description: "Check the argument of \\(\\ln\\) is positive.", workingLatex: "x + 2 > 0 \\;\\Leftrightarrow\\; x > -2", explanation: "The root sits near \\(x \\approx 1.15\\), comfortably positive, so \\(\\ln(x + 2)\\) is well-defined throughout the iteration." }, { stepNumber: 5, description: "Apply \\(\\ln\\) to both sides.", workingLatex: "x = \\ln(x + 2)", explanation: "\\(\\ln(e^{x}) = x\\). This is the required fixed-point form; the corresponding iteration is \\(x_{n+1} = \\ln(x_{n} + 2)\\)." }, { stepNumber: 6, description: "Compute \\(x_{1} = \\ln(x_{0} + 2)\\).", workingLatex: "x_{1} = \\ln(1 + 2) = \\ln 3", explanation: "Substitute \\(x_{0} = 1\\); argument simplifies to \\(3\\)." }, { stepNumber: 7, description: "Evaluate \\(\\ln 3\\) and round.", workingLatex: "x_{1} = 1.098612\\ldots \\approx 1.0986", explanation: "Standard value; fifth decimal is \\(1\\), round down." }, { stepNumber: 8, description: "Set up \\(x_{2} = \\ln(x_{1} + 2)\\) with unrounded value.", workingLatex: "x_{2} = \\ln(1.098612 + 2) = \\ln(3.098612)", explanation: "Carry the full 6-d.p.\\ value of \\(x_{1}\\) forward." }, { stepNumber: 9, description: "Evaluate and round \\(x_{2}\\).", workingLatex: "x_{2} = 1.130954\\ldots \\approx 1.1310", explanation: "Fifth decimal is \\(5\\), round up. The iterates are increasing — approaching the limit from below." }, { stepNumber: 10, description: "Diagnose convergence.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{x + 2};\\ g'(1.146) \\approx 0.318", explanation: "At the fixed point \\(\\alpha \\approx 1.1462\\), \\(|g'(\\alpha)| \\approx 0.318 < 1\\), so the iteration converges. Positive derivative \\(\\Rightarrow\\) staircase convergence (monotone increasing). The shrinkage factor \\(0.318\\) means each step reduces the error by about two-thirds." } ], finalAnswer: "\\(x_{1} \\approx 1.0986,\\ x_{2} \\approx 1.1310\\)." } },
  { id: "y2nm2-019", topicRef: "y2nm2", topicTitle: "Iteration 19", difficulty: "Standard", questionText: "Show that \\(x^{3} - 5x + 1 = 0\\) can be rearranged as (a) \\(x = \\tfrac{x^{3} + 1}{5}\\) and (b) \\(x = \\sqrt[3]{5x - 1}\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{(a) isolate}\\ 5x;\\ \\text{(b) isolate}\\ x^{3}", explanation: "Two different rearrangements come from isolating two different terms of the cubic. We will derive each one, then differentiate both to see which converges near which root." }, { stepNumber: 2, description: "(a) Move \\(-5x\\) across.", workingLatex: "x^{3} - 5x + 1 = 0 \\;\\Longleftrightarrow\\; x^{3} + 1 = 5x", explanation: "Add \\(5x\\) to both sides. Now the only \\(x\\) term on the right is \\(5x\\)." }, { stepNumber: 3, description: "Divide by \\(5\\).", workingLatex: "x = \\displaystyle\\frac{x^{3} + 1}{5} \\quad\\text{Shown for (a).}", explanation: "Dividing by \\(5\\) is always valid (\\(5 \\neq 0\\)), so no roots are lost. The iteration is \\(x_{n+1} = (x_{n}^{3} + 1)/5\\)." }, { stepNumber: 4, description: "(b) Move \\(-5x\\) and \\(+1\\) across to isolate \\(x^{3}\\).", workingLatex: "x^{3} - 5x + 1 = 0 \\;\\Longleftrightarrow\\; x^{3} = 5x - 1", explanation: "Add \\(5x\\) and subtract \\(1\\) from both sides." }, { stepNumber: 5, description: "Take the real cube root.", workingLatex: "x = \\sqrt[3]{5x - 1} \\quad\\text{Shown for (b).}", explanation: "Cube-rooting is one-to-one on \\(\\mathbb{R}\\); valid for any sign of \\(5x - 1\\). The iteration is \\(x_{n+1} = \\sqrt[3]{5x_{n} - 1}\\)." }, { stepNumber: 6, description: "Differentiate each \\(g\\).", workingLatex: "g_{a}'(x) = \\displaystyle\\frac{3x^{2}}{5},\\quad g_{b}'(x) = \\displaystyle\\frac{5}{3(5x - 1)^{2/3}}", explanation: "Standard chain-rule differentiation. We need these to predict which iteration converges where." }, { stepNumber: 7, description: "Evaluate \\(|g_{a}'|\\) at the small root \\(\\alpha \\approx 0.2\\).", workingLatex: "|g_{a}'(0.2)| = \\displaystyle\\frac{3 \\times 0.04}{5} = 0.024 \\ll 1", explanation: "Iteration (a) converges very fast near \\(0.2\\) (error shrinks by a factor of about \\(40\\) per step). Bad news at the other roots: \\(|g_{a}'(2.13)| \\approx 2.72 > 1\\), so iteration (a) diverges there." }, { stepNumber: 8, description: "Evaluate \\(|g_{b}'|\\) at the larger root \\(\\alpha \\approx 2.13\\).", workingLatex: "|g_{b}'(2.13)| \\approx 0.368 < 1", explanation: "Iteration (b) converges near the large positive root, though more slowly than (a) does near the small root. At the small root \\(\\alpha \\approx 0.2\\), \\(|g_{b}'(0.2)| \\approx 16.7\\) — useless." }, { stepNumber: 9, description: "Conclude.", workingLatex: "\\text{(a)\\ } \\to\\ \\alpha \\approx 0.2;\\ \\text{(b)\\ } \\to\\ \\alpha \\approx 2.13", explanation: "Same cubic, three real roots, but each rearrangement is built to find a different one. Choosing the right rearrangement is the art of fixed-point iteration." } ], finalAnswer: "Both shown." } },
  { id: "y2nm2-020", topicRef: "y2nm2", topicTitle: "Iteration 20", difficulty: "Standard", questionText: "Apply \\(x_{n+1} = \\tfrac{x_{n}^{3} + 1}{5}\\) with \\(x_{0} = 0\\). Find \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places and state what they appear to converge to.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\displaystyle\\frac{x_{n}^{3} + 1}{5},\\quad x_{0} = 0", explanation: "Three iterates by direct substitution, then identify the limit as a root of \\(x^{3} - 5x + 1 = 0\\) and verify by substitution. We expect very fast convergence because \\(g'(\\alpha) = 3\\alpha^{2}/5\\) is tiny near \\(\\alpha \\approx 0.2\\)." }, { stepNumber: 2, description: "Compute \\(x_{1}\\) — substitute \\(x_{0} = 0\\).", workingLatex: "x_{1} = \\displaystyle\\frac{0^{3} + 1}{5} = \\displaystyle\\frac{1}{5} = 0.2000", explanation: "Exact; the cube of zero is zero." }, { stepNumber: 3, description: "Compute the cube for \\(x_{2}\\).", workingLatex: "(0.2)^{3} = 0.008\\ \\text{(exact)}", explanation: "\\(0.2^{3} = 2^{3}/10^{3} = 8/1000\\)." }, { stepNumber: 4, description: "Assemble \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{0.008 + 1}{5} = \\displaystyle\\frac{1.008}{5} = 0.2016\\ \\text{(exact)}", explanation: "Add inside the fraction first, then divide. Exact value." }, { stepNumber: 5, description: "Compute the cube for \\(x_{3}\\).", workingLatex: "(0.2016)^{3} = 0.008193\\ldots", explanation: "Calculator: \\((0.2016)^{3} = 0.008193540\\ldots\\). Keep 6 d.p." }, { stepNumber: 6, description: "Assemble \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{0.008193 + 1}{5} = \\displaystyle\\frac{1.008193}{5} = 0.201638\\ldots", explanation: "Add and divide as before." }, { stepNumber: 7, description: "Round \\(x_{3}\\) to 4 d.p.", workingLatex: "x_{3} \\approx 0.2016", explanation: "Fifth decimal is \\(3 < 5\\), round down. Same display value as \\(x_{2}\\) — the iteration has effectively converged at 4 d.p." }, { stepNumber: 8, description: "Differentiate \\(g\\) and check the rate.", workingLatex: "g(x) = \\displaystyle\\frac{x^{3} + 1}{5} \\;\\Rightarrow\\; g'(x) = \\displaystyle\\frac{3x^{2}}{5}", explanation: "Standard derivative of \\((x^{3} + 1)/5\\)." }, { stepNumber: 9, description: "Evaluate \\(|g'|\\) at the fixed point.", workingLatex: "g'(0.2016) = \\displaystyle\\frac{3 \\times 0.04064}{5} \\approx 0.0244 \\ll 1", explanation: "Each iteration shrinks the error by a factor of about \\(40\\) — that is why we reach 4 d.p.\\ in just two steps. Positive derivative \\(\\Rightarrow\\) staircase convergence (monotone increasing)." }, { stepNumber: 10, description: "Verify by substituting back into the original equation.", workingLatex: "f(0.2016) = (0.2016)^{3} - 5(0.2016) + 1 \\approx 0.00819 - 1.008 + 1 \\approx 0.00019", explanation: "\\(f(\\alpha) \\approx 0\\), so \\(\\alpha \\approx 0.2016\\) is genuinely the smallest real root of \\(x^{3} - 5x + 1 = 0\\). (The exact value is \\(\\alpha \\approx 0.201640\\), agreeing with our \\(x_{3}\\) to 5 d.p.\\ already.)" } ], finalAnswer: "Converges to \\(\\approx 0.2016\\) (a root of \\(x^{3} - 5x + 1 = 0\\))." } },
  { id: "y2nm2-021", topicRef: "y2nm2", topicTitle: "Iteration 21", difficulty: "Standard", questionText: "Apply the second rearrangement \\(x_{n+1} = \\sqrt[3]{5x_{n} - 1}\\) with \\(x_{0} = 2\\). Compute \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\sqrt[3]{5x_{n} - 1},\\quad x_{0} = 2", explanation: "We compute three iterates by direct substitution, carrying the unrounded value forward each step. The real cube root is single-valued, so no \\(\\pm\\) ambiguity arises." }, { stepNumber: 2, description: "Set up \\(x_{1} = \\sqrt[3]{5 x_{0} - 1}\\).", workingLatex: "x_{1} = \\sqrt[3]{5(2) - 1} = \\sqrt[3]{9}", explanation: "Substitute \\(x_{0} = 2\\). The argument simplifies to \\(10 - 1 = 9\\)." }, { stepNumber: 3, description: "Evaluate and round \\(x_{1}\\).", workingLatex: "x_{1} = 2.080083\\ldots \\approx 2.0801", explanation: "\\(\\sqrt[3]{9}\\) is just above \\(2\\) (since \\(2^{3} = 8\\)). Fifth decimal is \\(8\\), round up." }, { stepNumber: 4, description: "Set up \\(x_{2}\\) with the unrounded \\(x_{1}\\).", workingLatex: "x_{2} = \\sqrt[3]{5(2.080083) - 1} = \\sqrt[3]{9.400418}", explanation: "Multiply by 5 and subtract 1 before taking the cube root." }, { stepNumber: 5, description: "Evaluate and round \\(x_{2}\\).", workingLatex: "x_{2} = 2.110485\\ldots \\approx 2.1105", explanation: "Fifth decimal is \\(8\\), round up." }, { stepNumber: 6, description: "Set up \\(x_{3}\\) with the unrounded \\(x_{2}\\).", workingLatex: "x_{3} = \\sqrt[3]{5(2.110485) - 1} = \\sqrt[3]{9.552428}", explanation: "Same procedure with the latest iterate." }, { stepNumber: 7, description: "Evaluate and round \\(x_{3}\\).", workingLatex: "x_{3} = 2.121800\\ldots \\approx 2.1218", explanation: "Fifth decimal is \\(0\\), round down." }, { stepNumber: 8, description: "Inspect the gaps.", workingLatex: "\\Delta_{1} = 0.080,\\ \\Delta_{2} = 0.030,\\ \\Delta_{3} = 0.011", explanation: "Successive jumps shrink by a factor of about \\(0.37\\) per step — clean linear convergence." }, { stepNumber: 9, description: "Diagnose convergence.", workingLatex: "g'(x) = \\displaystyle\\frac{5}{3(5x - 1)^{2/3}};\\ g'(2.128) \\approx 0.368", explanation: "At the larger root \\(\\alpha \\approx 2.128\\), \\(|g'(\\alpha)| \\approx 0.368 < 1\\), so the iteration converges. The shrinkage factor \\(0.37\\) matches the observed decay." }, { stepNumber: 10, description: "State the limit.", workingLatex: "x_{n} \\to \\alpha \\approx 2.13", explanation: "Sequence approaches the larger positive root of \\(x^{3} - 5x + 1 = 0\\), \\(\\alpha \\approx 2.1284\\). Positive \\(g'(\\alpha)\\) means staircase (monotone) convergence — the iterates climb steadily toward the limit from below." } ], finalAnswer: "Sequence approaches \\(\\approx 2.13\\)." } },
  { id: "y2nm2-022", topicRef: "y2nm2", topicTitle: "Iteration 22", difficulty: "Standard", questionText: "The cubic \\(x^{3} - 5x + 1 = 0\\) has three real roots. Use the iteration \\(x_{n+1} = \\sqrt[3]{5x_{n} - 1}\\) with \\(x_{0} = -2\\) to find, to 2 decimal places, the negative root.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\sqrt[3]{5x_{n} - 1},\\quad x_{0} = -2", explanation: "Real cube root preserves sign (cube root of a negative is negative), so starting from \\(x_{0} = -2\\) keeps the iteration in the negative half-line — exactly what we need to capture the negative root. We iterate until two successive 2-d.p.\\ values agree." }, { stepNumber: 2, description: "Set up \\(x_{1}\\) with \\(x_{0} = -2\\).", workingLatex: "x_{1} = \\sqrt[3]{5(-2) - 1} = \\sqrt[3]{-11}", explanation: "Argument is \\(-10 - 1 = -11\\)." }, { stepNumber: 3, description: "Evaluate and round \\(x_{1}\\).", workingLatex: "x_{1} = -\\sqrt[3]{11} = -2.223980\\ldots \\approx -2.2240", explanation: "\\(\\sqrt[3]{11} \\approx 2.224\\); the minus sign carries through the real cube root. Fifth decimal of magnitude is \\(8 \\geq 5\\), so the fourth (in magnitude) rounds up." }, { stepNumber: 4, description: "Set up \\(x_{2}\\) with the unrounded \\(x_{1}\\).", workingLatex: "x_{2} = \\sqrt[3]{5(-2.223980) - 1} = \\sqrt[3]{-12.119900}", explanation: "\\(5 \\times (-2.223980) = -11.119900\\); subtract \\(1\\) for \\(-12.119900\\)." }, { stepNumber: 5, description: "Evaluate and round \\(x_{2}\\).", workingLatex: "x_{2} = -2.297028\\ldots \\approx -2.2970", explanation: "Fifth decimal of magnitude is \\(2\\), round down." }, { stepNumber: 6, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\sqrt[3]{5(-2.297028) - 1} = \\sqrt[3]{-12.485140} \\approx -2.319874", explanation: "Approaching the negative root from above in magnitude (\\(|x_{1}| < |x_{2}| < |x_{3}|\\))." }, { stepNumber: 7, description: "Continue further.", workingLatex: "x_{4} \\approx -2.3269,\\ x_{5} \\approx -2.3291,\\ x_{6} \\approx -2.3298,\\ x_{7} \\approx -2.3300", explanation: "Each step changes the iterate by less and less; by \\(x_{7}\\) we are within \\(0.001\\) of stability." }, { stepNumber: 8, description: "Inspect the shrinkage.", workingLatex: "\\Delta_{4} \\approx 0.007,\\ \\Delta_{5} \\approx 0.002,\\ \\Delta_{6} \\approx 0.001", explanation: "Shrinkage factor \\(\\sim 0.3\\) per step — consistent with \\(|g'(\\alpha)| \\approx 0.3\\) at the negative root." }, { stepNumber: 9, description: "Stability check at 2 d.p.", workingLatex: "|x_{7} - x_{6}| < 0.005", explanation: "The 2-d.p.\\ tolerance is \\(0.005\\). With \\(\\Delta_{7}\\) already below this, all later iterates will round to the same 2-d.p.\\ value." }, { stepNumber: 10, description: "Determine the 2-d.p.\\ value.", workingLatex: "x_{6}, x_{7} \\to -2.33\\ (2\\ \\text{d.p.})", explanation: "Both \\(-2.3298\\) and \\(-2.3300\\) round to \\(-2.33\\) at 2 d.p. The exact negative root is \\(\\alpha \\approx -2.3301\\)." }, { stepNumber: 11, description: "Verify by substitution.", workingLatex: "f(-2.33) = (-2.33)^{3} - 5(-2.33) + 1 \\approx 0.0007", explanation: "Residual \\(\\approx 7\\times 10^{-4}\\), well within the 2-d.p.\\ tolerance. The sign change of \\(f\\) across the rounding bracket \\([-2.335, -2.325]\\) certifies the value." } ], finalAnswer: "Negative root \\(\\approx -2.33\\)." } },
  { id: "y2nm2-023", topicRef: "y2nm2", topicTitle: "Iteration 23", difficulty: "Standard", questionText: "The iteration \\(x_{n+1} = 1 + \\tfrac{1}{x_{n}}\\) has a fixed point \\(\\alpha\\). Show that \\(\\alpha\\) satisfies \\(\\alpha^{2} - \\alpha - 1 = 0\\) and state the positive value of \\(\\alpha\\) in exact form.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = x_{n} = \\alpha \\;\\Rightarrow\\; \\alpha = g(\\alpha)", explanation: "Apply the fixed-point condition to the given recurrence, clear the fraction by multiplying by \\(\\alpha\\), rearrange to standard quadratic form, and solve with the quadratic formula. Select the positive root." }, { stepNumber: 2, description: "Substitute the fixed-point condition.", workingLatex: "\\alpha = 1 + \\displaystyle\\frac{1}{\\alpha}", explanation: "Replace both \\(x_{n+1}\\) and \\(x_{n}\\) in the recurrence by \\(\\alpha\\)." }, { stepNumber: 3, description: "Check the multiplication step is legitimate.", workingLatex: "\\alpha = 0 \\;\\Rightarrow\\; 1/\\alpha\\ \\text{undefined}", explanation: "\\(\\alpha = 0\\) is not even in the iteration's domain, so multiplying both sides by \\(\\alpha\\) is safe — no fixed point sits at zero." }, { stepNumber: 4, description: "Multiply both sides by \\(\\alpha\\).", workingLatex: "\\alpha \\cdot \\alpha = \\alpha\\!\\left(1 + \\displaystyle\\frac{1}{\\alpha}\\right) = \\alpha + 1", explanation: "Distribute the \\(\\alpha\\) on the right: \\(\\alpha \\cdot 1 = \\alpha\\) and \\(\\alpha \\cdot (1/\\alpha) = 1\\)." }, { stepNumber: 5, description: "Simplify the left side and rearrange.", workingLatex: "\\alpha^{2} = \\alpha + 1 \\;\\Longleftrightarrow\\; \\alpha^{2} - \\alpha - 1 = 0\\quad\\text{Shown.}", explanation: "This is the equation \\(\\alpha\\) satisfies — the golden-ratio quadratic." }, { stepNumber: 6, description: "Apply the quadratic formula.", workingLatex: "\\alpha = \\displaystyle\\frac{1 \\pm \\sqrt{1 + 4}}{2} = \\displaystyle\\frac{1 \\pm \\sqrt{5}}{2}", explanation: "Discriminant \\(b^{2} - 4ac = (-1)^{2} - 4(1)(-1) = 1 + 4 = 5\\); two real solutions." }, { stepNumber: 7, description: "Identify the two branches numerically.", workingLatex: "\\displaystyle\\frac{1 - \\sqrt{5}}{2} \\approx -0.618,\\ \\displaystyle\\frac{1 + \\sqrt{5}}{2} \\approx 1.618", explanation: "\\(\\sqrt{5} \\approx 2.236\\), so the minus branch is negative and the plus branch is positive." }, { stepNumber: 8, description: "Select the positive root.", workingLatex: "\\alpha = \\displaystyle\\frac{1 + \\sqrt{5}}{2}", explanation: "The question asks for the positive value, so we pick the plus branch — the famous golden ratio \\(\\varphi\\)." }, { stepNumber: 9, description: "Verify by substitution.", workingLatex: "1 + \\displaystyle\\frac{1}{1.6180} = 1 + 0.6180 = 1.6180\\ \\checkmark", explanation: "\\(1/\\varphi = \\varphi - 1\\) is a famous identity, so \\(1 + 1/\\varphi = 1 + (\\varphi - 1) = \\varphi\\) — the iteration leaves \\(\\varphi\\) unchanged, confirming the fixed point." } ], finalAnswer: "\\(\\alpha = \\displaystyle\\frac{1 + \\sqrt{5}}{2}\\) (the golden ratio)." } },
  { id: "y2nm2-024", topicRef: "y2nm2", topicTitle: "Iteration 24", difficulty: "Standard", questionText: "Apply \\(x_{n+1} = 1 + \\tfrac{1}{x_{n}}\\) with \\(x_{0} = 1\\) and find \\(x_{1},\\ x_{2},\\ x_{3},\\ x_{4}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = 1 + \\displaystyle\\frac{1}{x_{n}},\\quad x_{0} = 1", explanation: "Each iterate is one plus the reciprocal of the previous — a classic continued-fraction recurrence for the golden ratio. We carry exact rationals where possible since all four iterates turn out to be Fibonacci-quotient fractions." }, { stepNumber: 2, description: "Compute \\(x_{1}\\) — substitute \\(x_{0} = 1\\).", workingLatex: "x_{1} = 1 + \\displaystyle\\frac{1}{1} = 1 + 1 = 2.0000", explanation: "Exact value, \\(F_{3}/F_{2} = 2/1\\)." }, { stepNumber: 3, description: "Compute \\(x_{2}\\) — substitute \\(x_{1} = 2\\).", workingLatex: "x_{2} = 1 + \\displaystyle\\frac{1}{2} = \\displaystyle\\frac{3}{2} = 1.5000", explanation: "Exact rational, \\(F_{4}/F_{3} = 3/2\\)." }, { stepNumber: 4, description: "Compute \\(x_{3}\\) — substitute \\(x_{2} = 3/2\\).", workingLatex: "x_{3} = 1 + \\displaystyle\\frac{1}{3/2} = 1 + \\displaystyle\\frac{2}{3} = \\displaystyle\\frac{5}{3}", explanation: "\\(1 \\div (3/2) = 2/3\\); add 1 to get \\(5/3\\). This is \\(F_{5}/F_{4}\\)." }, { stepNumber: 5, description: "Convert \\(x_{3}\\) to decimal.", workingLatex: "x_{3} = 1.666666\\ldots\\ \\text{(recurring)}", explanation: "Standard recurring decimal for \\(5/3\\)." }, { stepNumber: 6, description: "Round \\(x_{3}\\) to 4 d.p.", workingLatex: "x_{3} \\approx 1.6667", explanation: "Fifth decimal is \\(6 \\geq 5\\), round up." }, { stepNumber: 7, description: "Compute \\(x_{4}\\) — substitute the exact \\(x_{3} = 5/3\\).", workingLatex: "x_{4} = 1 + \\displaystyle\\frac{1}{5/3} = 1 + \\displaystyle\\frac{3}{5} = \\displaystyle\\frac{8}{5}", explanation: "\\(1 \\div (5/3) = 3/5\\); add 1 to get \\(8/5\\). This is \\(F_{6}/F_{5}\\)." }, { stepNumber: 8, description: "Convert \\(x_{4}\\) to decimal.", workingLatex: "x_{4} = 1.6000\\ \\text{(exact)}", explanation: "Terminating decimal." }, { stepNumber: 9, description: "Reflect on the oscillation.", workingLatex: "1, 2, 1.5, 1.6667, 1.6000,\\ldots", explanation: "Iterates alternate above and below the limit: \\(2 > \\varphi,\\ 1.5 < \\varphi,\\ 1.6667 > \\varphi,\\ 1.6 < \\varphi\\). Each amplitude is about \\(0.38\\) times the previous one — cobweb convergence." }, { stepNumber: 10, description: "Identify the Fibonacci connection.", workingLatex: "x_{n} = \\displaystyle\\frac{F_{n+2}}{F_{n+1}};\\ g'(\\varphi) = -\\displaystyle\\frac{1}{\\varphi^{2}} \\approx -0.382", explanation: "Successive iterates are ratios of consecutive Fibonacci numbers (\\(1/1, 2/1, 3/2, 5/3, 8/5, \\ldots\\)) — they famously converge to \\(\\varphi\\). The negative derivative at \\(\\varphi\\) (with \\(|g'(\\varphi)| \\approx 0.382\\)) produces cobweb convergence with the observed shrinkage factor." } ], finalAnswer: "\\(2.0000,\\ 1.5000,\\ 1.6667,\\ 1.6000\\)." } },
  { id: "y2nm2-025", topicRef: "y2nm2", topicTitle: "Iteration 25", difficulty: "Standard", questionText: "Let \\(f(x) = x^{3} - 2x - 5\\). Show that the rearrangement \\(x = \\sqrt[3]{2x + 5}\\) is equivalent to \\(f(x) = 0\\), and use iteration with \\(x_{0} = 2\\) to find the root to 2 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration", "rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{3} = 2x + 5 \\;\\longrightarrow\\; x = \\sqrt[3]{2x + 5} \\;\\longrightarrow\\; \\text{iterate to 2 d.p.}", explanation: "Three parts: (i) rearrange the cubic into the given fixed-point form by isolating \\(x^{3}\\) and cube-rooting; (ii) iterate from \\(x_{0} = 2\\) until two consecutive iterates agree at 2 d.p.; (iii) verify by substituting back into \\(f\\)." }, { stepNumber: 2, description: "Isolate \\(x^{3}\\) in the original equation.", workingLatex: "x^{3} - 2x - 5 = 0 \\;\\Longleftrightarrow\\; x^{3} = 2x + 5", explanation: "Add \\(2x + 5\\) to both sides." }, { stepNumber: 3, description: "Take the real cube root.", workingLatex: "x = \\sqrt[3]{2x + 5}", explanation: "Cube-rooting is one-to-one on \\(\\mathbb{R}\\); no \\(\\pm\\) ambiguity. The iteration is \\(x_{n+1} = \\sqrt[3]{2x_{n} + 5}\\)." }, { stepNumber: 4, description: "Compute \\(x_{1}\\) with \\(x_{0} = 2\\).", workingLatex: "x_{1} = \\sqrt[3]{2(2) + 5} = \\sqrt[3]{9} = 2.080083\\ldots", explanation: "\\(\\sqrt[3]{9}\\) just above \\(2\\) (since \\(2^{3} = 8\\))." }, { stepNumber: 5, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\sqrt[3]{2(2.080083) + 5} = \\sqrt[3]{9.160167} = 2.092349\\ldots", explanation: "Use the unrounded \\(x_{1}\\)." }, { stepNumber: 6, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\sqrt[3]{2(2.092349) + 5} = \\sqrt[3]{9.184699} = 2.094216\\ldots", explanation: "Iterate continues toward the limit." }, { stepNumber: 7, description: "Compute \\(x_{4}\\) for stability check.", workingLatex: "x_{4} = \\sqrt[3]{2(2.094216) + 5} = \\sqrt[3]{9.188432} = 2.094500\\ldots", explanation: "Successive iterates now agree to 3 d.p.\\ already." }, { stepNumber: 8, description: "Inspect the shrinkage.", workingLatex: "\\Delta_{2} \\approx 0.012,\\ \\Delta_{3} \\approx 0.002,\\ \\Delta_{4} \\approx 0.0003", explanation: "Each gap is roughly \\(0.15\\) times the previous — fast linear convergence." }, { stepNumber: 9, description: "Confirm 2-d.p.\\ agreement.", workingLatex: "|x_{4} - x_{3}| \\approx 3\\times 10^{-4} \\ll 0.005", explanation: "Comfortably below the 2-d.p.\\ tolerance \\(0.005\\); all further iterates will round to the same 2-d.p.\\ value." }, { stepNumber: 10, description: "Read off the root.", workingLatex: "x_{2}, x_{3}, x_{4} \\to 2.09\\ (2\\ \\text{d.p.})", explanation: "All round to \\(2.09\\)." }, { stepNumber: 11, description: "Verify by substitution.", workingLatex: "f(2.0945) = 2.0945^{3} - 2(2.0945) - 5 \\approx 9.1879 - 4.189 - 5 \\approx -0.001", explanation: "\\(f \\approx 0\\) at the 4-d.p.\\ value, confirming the root. The convergence criterion \\(|g'(\\alpha)|\\) gives \\(g'(x) = \\tfrac{2}{3}(2x+5)^{-2/3}\\), so \\(|g'(2.0945)| \\approx 0.152 < 1\\), explaining the observed shrinkage factor of \\(\\sim 0.15\\)." } ], finalAnswer: "Root \\(\\approx 2.09\\)." } },
  { id: "y2nm2-026", topicRef: "y2nm2", topicTitle: "Iteration 26", difficulty: "Standard", questionText: "Show that \\(2x - \\cos x = 0\\) can be rearranged as \\(x = \\tfrac{1}{2}\\cos x\\). Use iteration with \\(x_{0} = 0.5\\) to find \\(x_{3}\\) to 4 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "2x = \\cos x \\;\\longrightarrow\\; x = \\displaystyle\\frac{1}{2}\\cos x \\;\\longrightarrow\\; \\text{iterate to } x_{3}", explanation: "Rearrange the trig equation by isolating \\(2x\\), then divide by 2 to obtain the fixed-point form. Iterate from \\(x_{0} = 0.5\\) (in radians) and report \\(x_{3}\\) to 4 d.p." }, { stepNumber: 2, description: "Isolate \\(\\cos x\\) on one side.", workingLatex: "2x - \\cos x = 0 \\;\\Longleftrightarrow\\; 2x = \\cos x", explanation: "Add \\(\\cos x\\) to both sides." }, { stepNumber: 3, description: "Divide by 2.", workingLatex: "x = \\displaystyle\\frac{1}{2}\\cos x \\quad\\text{Shown.}", explanation: "Always valid (\\(2 \\neq 0\\)). Iteration: \\(x_{n+1} = \\tfrac{1}{2}\\cos(x_{n})\\). Calculator in radian mode throughout." }, { stepNumber: 4, description: "Compute \\(\\cos 0.5\\) for \\(x_{1}\\).", workingLatex: "\\cos 0.5 = 0.877582\\ldots", explanation: "Radian mode value; keep 6 d.p." }, { stepNumber: 5, description: "Halve to get \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}(0.877582) = 0.438791\\ldots \\approx 0.4388", explanation: "Fifth decimal is \\(9\\), round up." }, { stepNumber: 6, description: "Compute \\(\\cos x_{1}\\) for \\(x_{2}\\).", workingLatex: "\\cos(0.438791) = 0.905265\\ldots", explanation: "Cosine of a smaller angle is larger (cosine decreases on \\([0,\\pi/2]\\)), so the value bumps up from \\(0.878\\) to \\(0.905\\)." }, { stepNumber: 7, description: "Halve to get \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}(0.905265) = 0.452632\\ldots \\approx 0.4526", explanation: "Fifth decimal is \\(3\\), round down." }, { stepNumber: 8, description: "Compute \\(\\cos x_{2}\\) for \\(x_{3}\\).", workingLatex: "\\cos(0.452632) = 0.899298\\ldots", explanation: "Cosine of a slightly larger angle is slightly smaller — back down from \\(0.905\\) to \\(0.899\\)." }, { stepNumber: 9, description: "Halve to get \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}(0.899298) = 0.449649\\ldots", explanation: "Halving as before." }, { stepNumber: 10, description: "Round \\(x_{3}\\) to 4 d.p.", workingLatex: "x_{3} \\approx 0.4496", explanation: "Fifth decimal is \\(4 < 5\\), round down." }, { stepNumber: 11, description: "Diagnose convergence.", workingLatex: "g'(x) = -\\displaystyle\\frac{1}{2}\\sin x;\\ g'(0.450) \\approx -0.218", explanation: "At the fixed point \\(\\alpha \\approx 0.4502\\), \\(|g'(\\alpha)| \\approx 0.22 < 1\\). Negative derivative \\(\\Rightarrow\\) cobweb (alternating) convergence — exactly the oscillation \\(0.439 \\to 0.453 \\to 0.450\\) we see. Each amplitude shrinks by about \\(0.22\\) per step." } ], finalAnswer: "\\(x_{3} \\approx 0.4496\\)." } },
  { id: "y2nm2-027", topicRef: "y2nm2", topicTitle: "Iteration 27", difficulty: "Standard", questionText: "Verify that \\(\\tan x - x = 0\\) can be rearranged as \\(x = \\arctan(x + n\\pi)\\) for integer \\(n\\), but that \\(x_{n+1} = \\tan x_{n}\\) does not converge near the nonzero roots. Explain briefly.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["rearranging", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\tan x = x \\;\\longrightarrow\\; \\text{two rearrangements; compare}\\ |g'(\\alpha)|", explanation: "We derive the \\(\\arctan\\)-form, then compare the derivative magnitudes of the two iterations \\(g(x) = \\tan x\\) and \\(h(x) = \\arctan x + n\\pi\\) at a nonzero root. The convergence criterion \\(|g'(\\alpha)| < 1\\) decides which iteration works." }, { stepNumber: 2, description: "Read the equation \\(\\tan x = x\\) graphically.", workingLatex: "y = \\tan x\\ \\text{meets}\\ y = x\\ \\text{once per branch}", explanation: "Roots occur at \\(x = 0\\) and at one point in each interval \\((n\\pi - \\pi/2,\\ n\\pi + \\pi/2)\\) for integer \\(n \\neq 0\\)." }, { stepNumber: 3, description: "Justify the \\(\\arctan\\) rearrangement.", workingLatex: "\\tan x = x \\;\\Rightarrow\\; x = \\arctan(x) + n\\pi", explanation: "\\(\\arctan(\\tan x) = x\\) modulo \\(\\pi\\), since \\(\\tan\\) is \\(\\pi\\)-periodic. Adding the correct \\(n\\pi\\) recovers the right branch. So \\(x = \\arctan(x) + n\\pi\\) is a valid fixed-point form (one per root branch)." }, { stepNumber: 4, description: "Differentiate \\(g(x) = \\tan x\\).", workingLatex: "g'(x) = \\sec^{2}(x)", explanation: "Standard derivative." }, { stepNumber: 5, description: "Use the identity \\(\\sec^{2} = 1 + \\tan^{2}\\).", workingLatex: "g'(x) = 1 + \\tan^{2}(x)", explanation: "Pythagorean identity. This rewrite lets us substitute the root condition next." }, { stepNumber: 6, description: "Evaluate at a nonzero root.", workingLatex: "\\tan\\alpha = \\alpha \\;\\Rightarrow\\; g'(\\alpha) = 1 + \\alpha^{2} > 1", explanation: "At any root with \\(\\alpha \\neq 0\\), the derivative is strictly bigger than 1." }, { stepNumber: 7, description: "Show two iterates moving apart.", workingLatex: "x_{0} = \\alpha + 0.01 \\;\\Rightarrow\\; x_{1} - \\alpha \\approx (1 + \\alpha^{2})(0.01)\\ \\text{(grows)}", explanation: "Linearisation gives \\(x_{n+1} - \\alpha \\approx g'(\\alpha)(x_{n} - \\alpha)\\). For \\(\\alpha \\approx 4.49\\) (the smallest positive nonzero root) and a perturbation of \\(0.01\\), the next error is \\(\\sim 21 \\times 0.01 = 0.21\\) — a 20-fold blow-up in one step." }, { stepNumber: 8, description: "Conclude divergence.", workingLatex: "|g'(\\alpha)| > 1 \\;\\Rightarrow\\; \\text{iteration } x_{n+1} = \\tan x_{n}\\ \\text{diverges near every nonzero }\\alpha", explanation: "Every iterate moves further from the root, so the sequence is useless for capturing nonzero roots of \\(\\tan x = x\\)." }, { stepNumber: 9, description: "Differentiate the alternative \\(h(x) = \\arctan(x) + n\\pi\\).", workingLatex: "h'(x) = \\displaystyle\\frac{1}{1 + x^{2}}", explanation: "Standard derivative of \\(\\arctan\\); the \\(n\\pi\\) term is constant so contributes nothing." }, { stepNumber: 10, description: "Conclude that the \\(\\arctan\\)-form converges.", workingLatex: "|h'(\\alpha)| = \\displaystyle\\frac{1}{1 + \\alpha^{2}} < 1\\ \\text{for any real }\\alpha", explanation: "Strictly less than \\(1\\), so the iteration converges (slowly, since \\(|h'|\\) is small but not tiny when \\(\\alpha\\) is small). Note: \\(g'(\\alpha) \\cdot h'(\\alpha) = 1\\) — the two rearrangements are reciprocally related, so exactly one of them is contractive at any given fixed point." } ], finalAnswer: "\\(x = \\tan x\\) form diverges because \\(|(\\tan x)'| > 1\\)." } },
  { id: "y2nm2-028", topicRef: "y2nm2", topicTitle: "Iteration 28", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = g(x_{n})\\), state the condition on \\(g'(\\alpha)\\) that guarantees convergence near the fixed point \\(\\alpha\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{linearise}\\ g\\ \\text{near}\\ \\alpha,\\ \\text{track the error}\\ \\epsilon_{n} = x_{n} - \\alpha", explanation: "We linearise \\(g\\) about the fixed point using a Taylor expansion, deduce a one-step recurrence for the error \\(\\epsilon_{n}\\), and read off the contraction condition." }, { stepNumber: 2, description: "Taylor-expand \\(g\\) about \\(\\alpha\\).", workingLatex: "g(x) = g(\\alpha) + g'(\\alpha)(x - \\alpha) + O\\!\\left((x - \\alpha)^{2}\\right)", explanation: "Standard first-order Taylor expansion, assuming \\(g\\) is differentiable at \\(\\alpha\\)." }, { stepNumber: 3, description: "Use the fixed-point condition.", workingLatex: "g(\\alpha) = \\alpha", explanation: "Substituting reduces the linearisation to one in terms of \\(x - \\alpha\\)." }, { stepNumber: 4, description: "Subtract \\(\\alpha\\) from both sides.", workingLatex: "g(x) - \\alpha \\approx g'(\\alpha)(x - \\alpha)", explanation: "Both sides are now in 'displacement from \\(\\alpha\\)' form." }, { stepNumber: 5, description: "Translate to the iteration.", workingLatex: "x_{n+1} - \\alpha = g(x_{n}) - \\alpha \\approx g'(\\alpha)\\,(x_{n} - \\alpha)", explanation: "Apply the linearisation with \\(x = x_{n}\\); use \\(x_{n+1} = g(x_{n})\\)." }, { stepNumber: 6, description: "Introduce the error notation.", workingLatex: "\\epsilon_{n+1} \\approx g'(\\alpha)\\,\\epsilon_{n}", explanation: "Each iteration multiplies the error by approximately \\(g'(\\alpha)\\)." }, { stepNumber: 7, description: "Take absolute values.", workingLatex: "|\\epsilon_{n+1}| \\approx |g'(\\alpha)|\\,|\\epsilon_{n}|", explanation: "For convergence we need \\(|\\epsilon_{n}| \\to 0\\); this happens iff each ratio is strictly below \\(1\\)." }, { stepNumber: 8, description: "State the convergence criterion.", workingLatex: "|g'(\\alpha)| < 1", explanation: "If \\(|g'(\\alpha)| < 1\\), errors shrink by a factor less than \\(1\\) each step and the iteration converges (linearly). If \\(|g'(\\alpha)| > 1\\) errors grow and the iteration diverges; \\(|g'(\\alpha)| = 1\\) is the neutral boundary case (the iteration may cycle, drift, or do something delicate)." }, { stepNumber: 9, description: "Classify by sign.", workingLatex: "0 < g'(\\alpha) < 1\\ \\text{: staircase};\\ -1 < g'(\\alpha) < 0\\ \\text{: cobweb}", explanation: "Positive \\(g'\\): error keeps the same sign each step, so iterates approach monotonically (staircase). Negative \\(g'\\): error flips sign, so iterates alternate above and below \\(\\alpha\\) (cobweb)." } ], finalAnswer: "\\(|g'(\\alpha)| < 1\\)." } },
  { id: "y2nm2-029", topicRef: "y2nm2", topicTitle: "Iteration 29", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\), show that near the fixed point \\(\\alpha \\approx 1.3247\\) the convergence condition \\(|g'(\\alpha)| < 1\\) is satisfied.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = (x+1)^{1/3} \\;\\longrightarrow\\; g'(x) \\;\\longrightarrow\\; g'(\\alpha) \\;\\longrightarrow\\; |g'(\\alpha)| < 1?", explanation: "Differentiate \\(g\\), evaluate at \\(\\alpha \\approx 1.3247\\), and compare with \\(1\\). We will also use the algebraic shortcut \\((\\alpha + 1)^{1/3} = \\alpha\\) to simplify the numerical work." }, { stepNumber: 2, description: "Identify \\(g\\).", workingLatex: "g(x) = \\sqrt[3]{x + 1} = (x + 1)^{1/3}", explanation: "Rewrite the cube root in exponent form to make differentiation immediate." }, { stepNumber: 3, description: "Differentiate using the chain rule.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{3}(x + 1)^{-2/3} \\cdot 1 = \\displaystyle\\frac{1}{3(x + 1)^{2/3}}", explanation: "Power rule on a composite: bring the exponent down (\\(\\tfrac{1}{3}\\)), reduce the exponent by \\(1\\) (gives \\(-\\tfrac{2}{3}\\)), multiply by the inner derivative (which is \\(1\\))." }, { stepNumber: 4, description: "Set up \\(g'\\) at the fixed point.", workingLatex: "g'(1.3247) = \\displaystyle\\frac{1}{3(2.3247)^{2/3}}", explanation: "Substitute \\(\\alpha = 1.3247\\); the inner argument becomes \\(\\alpha + 1 = 2.3247\\)." }, { stepNumber: 5, description: "Use the fixed-point shortcut.", workingLatex: "\\alpha = (\\alpha + 1)^{1/3} \\;\\Rightarrow\\; \\alpha^{2} = (\\alpha + 1)^{2/3}", explanation: "Square both sides of the fixed-point equation \\(\\alpha = (\\alpha + 1)^{1/3}\\). This means the awkward two-thirds power equals the simpler square." }, { stepNumber: 6, description: "Compute \\(\\alpha^{2}\\).", workingLatex: "\\alpha^{2} = (1.3247)^{2} = 1.7548", explanation: "Direct calculation." }, { stepNumber: 7, description: "Substitute the simplified denominator.", workingLatex: "g'(1.3247) = \\displaystyle\\frac{1}{3 \\times 1.7548} = \\displaystyle\\frac{1}{5.2644}", explanation: "Now just one short division." }, { stepNumber: 8, description: "Evaluate.", workingLatex: "g'(\\alpha) \\approx 0.190", explanation: "Final numerical value of the derivative at the fixed point." }, { stepNumber: 9, description: "Compare with the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 0.190 < 1 \\;\\checkmark", explanation: "The criterion \\(|g'(\\alpha)| < 1\\) holds with plenty of margin." }, { stepNumber: 10, description: "Classify the convergence.", workingLatex: "g'(\\alpha) > 0 \\;\\Rightarrow\\; \\text{staircase};\\ \\text{shrink factor} \\approx 0.19", explanation: "Positive \\(g'\\), so the iteration converges monotonically (staircase). The small value of \\(\\sim 0.19\\) means each step shrinks the error by a factor of about \\(5\\) — relatively fast linear convergence, consistent with the Q2/Q3 numerical observations." } ], finalAnswer: "\\(|g'(\\alpha)| \\approx 0.19 < 1\\); convergence." } },
  { id: "y2nm2-030", topicRef: "y2nm2", topicTitle: "Iteration 30", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = x_{n}^{3} - 1\\), show that the fixed points are roots of \\(x^{3} - x - 1 = 0\\) but that iteration from a nearby start diverges.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{(i) fixed-point}\\ \\alpha = g(\\alpha)\\ \\text{; (ii) compute}\\ |g'(\\alpha)|\\ \\text{; (iii) show divergence by example}", explanation: "First derive the polynomial \\(\\alpha\\) satisfies. Then differentiate \\(g\\), evaluate at \\(\\alpha\\), and use the convergence criterion. Finally, run two iterates from a nearby start to display the blow-up." }, { stepNumber: 2, description: "Apply the fixed-point condition.", workingLatex: "\\alpha = \\alpha^{3} - 1", explanation: "Set \\(x_{n+1} = x_{n} = \\alpha\\) in the iteration." }, { stepNumber: 3, description: "Rearrange to standard form.", workingLatex: "\\alpha^{3} - \\alpha - 1 = 0 \\quad\\text{Shown.}", explanation: "Subtract \\(\\alpha\\) and add nothing — exactly the original cubic. So fixed points of this iteration are the same as roots of \\(x^{3} - x - 1 = 0\\) (the equation from Q1). Same equation, different iteration." }, { stepNumber: 4, description: "Differentiate \\(g\\).", workingLatex: "g(x) = x^{3} - 1 \\;\\Rightarrow\\; g'(x) = 3x^{2}", explanation: "Power rule on the cubic; the constant disappears." }, { stepNumber: 5, description: "Evaluate \\(g'\\) at the real root \\(\\alpha \\approx 1.3247\\).", workingLatex: "g'(1.3247) = 3(1.3247)^{2} = 3 \\times 1.7548 = 5.2645", explanation: "Use \\(\\alpha^{2} = 1.7548\\) (computed in Q29)." }, { stepNumber: 6, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 5.26 > 1\\;\\not<\\;1", explanation: "The criterion \\(|g'(\\alpha)| < 1\\) fails by a factor of \\(5\\). Errors are amplified, not damped." }, { stepNumber: 7, description: "Demonstrate divergence with a near-start.", workingLatex: "x_{0} = 1.32\\ (\\text{within}\\ 0.005\\ \\text{of}\\ \\alpha)", explanation: "Take a starting value just slightly below the root." }, { stepNumber: 8, description: "Compute one iterate to see the blow-up.", workingLatex: "x_{1} = 1.32^{3} - 1 = 2.300 - 1 = 1.300", explanation: "Already \\(|x_{1} - \\alpha| \\approx 0.025\\), roughly \\(5\\) times bigger than the initial deviation. Linearisation predicted \\(5.26 \\times 0.005 \\approx 0.026\\), matching the observation." }, { stepNumber: 9, description: "Compute a second iterate.", workingLatex: "x_{2} = 1.300^{3} - 1 = 2.197 - 1 = 1.197", explanation: "Now \\(|x_{2} - \\alpha| \\approx 0.128\\) — about \\(5\\) times bigger than \\(|x_{1} - \\alpha|\\). The errors are growing geometrically by a factor of about \\(5\\) per step, exactly as the criterion predicted." }, { stepNumber: 10, description: "Observe the iterates moving apart.", workingLatex: "x_{0} = 1.32,\\ x_{1} = 1.300,\\ x_{2} = 1.197;\\ \\text{moving away from}\\ \\alpha \\approx 1.3247", explanation: "Each subsequent iterate moves further from the root — the divergence is now visible without invoking the derivative." }, { stepNumber: 11, description: "Conclude.", workingLatex: "|g'(\\alpha)| > 1 \\;\\Rightarrow\\; \\text{iteration diverges from any nearby start}", explanation: "Same equation as Q1, but this rearrangement is useless as a numerical scheme — exactly the opposite outcome from the convergent \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\). Choice of \\(g\\) matters." } ], finalAnswer: "\\(|g'(\\alpha)| > 1\\) so the iteration diverges." } },
  { id: "y2nm2-031", topicRef: "y2nm2", topicTitle: "Iteration 31", difficulty: "Standard", questionText: "Apply \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + \\tfrac{20}{x_{n}})\\) with \\(x_{0} = 4\\). Find \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places, and state what \\(x_{n}\\) is approximating.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{2}\\!\\left(x_{n} + \\displaystyle\\frac{20}{x_{n}}\\right) \\;\\longrightarrow\\; \\sqrt{20}", explanation: "Recognise the Babylonian/Newton scheme: fixed-point condition \\(\\alpha = \\tfrac{1}{2}(\\alpha + 20/\\alpha)\\) gives \\(\\alpha^{2} = 20\\), so the iteration converges to \\(\\sqrt{20}\\). We expect quadratic convergence because \\(g'(\\sqrt{20}) = 0\\)." }, { stepNumber: 2, description: "Compute the reciprocal term for \\(x_{1}\\).", workingLatex: "\\displaystyle\\frac{20}{4} = 5\\ \\text{(exact)}", explanation: "Short division." }, { stepNumber: 3, description: "Average to get \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}(4 + 5) = \\displaystyle\\frac{9}{2} = 4.5000\\ \\text{(exact)}", explanation: "Mean of \\(4\\) and \\(5\\)." }, { stepNumber: 4, description: "Compute the reciprocal term for \\(x_{2}\\).", workingLatex: "\\displaystyle\\frac{20}{4.5} = \\displaystyle\\frac{40}{9} = 4.444444\\ldots", explanation: "Recurring decimal; keep 6 d.p." }, { stepNumber: 5, description: "Sum the inputs for the average.", workingLatex: "4.5 + 4.444444 = 8.944444", explanation: "Bring the two values together before halving." }, { stepNumber: 6, description: "Halve to get \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{8.944444}{2} = 4.472222\\ldots", explanation: "Standard mean." }, { stepNumber: 7, description: "Round \\(x_{2}\\) to 4 d.p.", workingLatex: "x_{2} \\approx 4.4722", explanation: "Fifth decimal is \\(2\\), round down." }, { stepNumber: 8, description: "Compare with \\(\\sqrt{20}\\).", workingLatex: "\\sqrt{20} = 4.472135\\ldots \\approx 4.4721\\ \\text{(4 d.p.)}", explanation: "Off by less than \\(10^{-4}\\)." }, { stepNumber: 9, description: "Differentiate \\(g\\) and check the rate.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{20}{x^{2}}\\right);\\ g'(\\sqrt{20}) = \\displaystyle\\frac{1}{2}(1 - 1) = 0", explanation: "\\(g'(\\alpha) = 0\\) signals quadratic convergence: the linear error term vanishes and the next error is proportional to the square of the previous." }, { stepNumber: 10, description: "Confirm quadratic convergence numerically.", workingLatex: "|x_{1} - \\sqrt{20}| \\approx 0.028;\\ |x_{2} - \\sqrt{20}| \\approx 8.6\\times 10^{-5};\\ |x_{3} - \\sqrt{20}| \\approx 8\\times 10^{-10}", explanation: "Errors go \\(\\sim 3\\times 10^{-2} \\to \\sim 10^{-4} \\to \\sim 10^{-9}\\) — each is roughly the square of the previous. Three steps yields nearly 9 correct digits." } ], finalAnswer: "\\(x_{n} \\to \\sqrt{20} \\approx 4.4721\\)." } },
  { id: "y2nm2-032", topicRef: "y2nm2", topicTitle: "Iteration 32", difficulty: "Standard", questionText: "Using \\(x_{n+1} = \\sqrt[3]{x_{n} + 1}\\) with \\(x_{0} = 1\\), find the root \\(\\alpha\\) of \\(x^{3} - x - 1 = 0\\) correct to 3 decimal places. State how many iterations are required.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{iterate until }|x_{n+1} - x_{n}| < 0.0005", explanation: "The 3-d.p.\\ tolerance is half a unit in the third decimal, i.e.\\ \\(0.0005\\). We carry full precision internally, iterate until two consecutive iterates round to the same 3-d.p.\\ value, then certify by sign change of \\(f\\) across the rounding bracket." }, { stepNumber: 2, description: "Set up the iteration.", workingLatex: "x_{n+1} = \\sqrt[3]{x_{n} + 1},\\quad x_{0} = 1", explanation: "Standard cube-root recurrence." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) and \\(x_{2}\\).", workingLatex: "x_{1} = \\sqrt[3]{2} = 1.259921;\\ x_{2} = \\sqrt[3]{2.259921} = 1.312294", explanation: "Same first two iterates as Q2; gap is \\(\\sim 0.052\\) — too coarse for 3 d.p." }, { stepNumber: 4, description: "Compute \\(x_{3}\\) and \\(x_{4}\\).", workingLatex: "x_{3} = \\sqrt[3]{2.312294} = 1.322354;\\ x_{4} = \\sqrt[3]{2.322354} = 1.324269", explanation: "Differences shrinking: \\(|x_{3} - x_{2}| \\approx 0.010\\), \\(|x_{4} - x_{3}| \\approx 0.0019\\) — still above tolerance." }, { stepNumber: 5, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = \\sqrt[3]{2.324269} = 1.324633", explanation: "Now \\(|x_{5} - x_{4}| \\approx 0.000364 < 0.0005\\) — first occurrence of agreement at the 3-d.p.\\ tolerance." }, { stepNumber: 6, description: "Compute \\(x_{6}\\) to confirm.", workingLatex: "x_{6} = \\sqrt[3]{2.324633} = 1.324702", explanation: "\\(|x_{6} - x_{5}| \\approx 0.00007\\) — comfortably below the tolerance." }, { stepNumber: 7, description: "Watch the shrinkage pattern.", workingLatex: "\\Delta\\ \\text{ratios:}\\ 0.20,\\ 0.19,\\ 0.19,\\ 0.19", explanation: "Each gap is about \\(0.19\\) times the previous one — exactly the value of \\(|g'(\\alpha)|\\) (see Q29). Clean linear convergence." }, { stepNumber: 8, description: "Round to 3 d.p.", workingLatex: "x_{5} \\approx 1.325,\\ x_{6} \\approx 1.325", explanation: "Both round to the same value." }, { stepNumber: 9, description: "Certify by sign change of \\(f\\).", workingLatex: "f(x) = x^{3} - x - 1;\\ f(1.3245) \\approx -0.00093,\\ f(1.3255) \\approx +0.00334", explanation: "\\(f\\) changes sign across the 3-d.p.\\ rounding bracket \\([1.3245, 1.3255]\\), so the root sits strictly inside, certifying \\(1.325\\) as correct to 3 d.p." }, { stepNumber: 10, description: "Sanity-check by direct substitution.", workingLatex: "f(1.325) = 1.325^{3} - 1.325 - 1 \\approx 0.0012", explanation: "Small residual, of the right order for an error of \\(\\sim 3 \\times 10^{-4}\\) in \\(x\\)." }, { stepNumber: 11, description: "State the answer.", workingLatex: "\\alpha \\approx 1.325\\ \\text{(3 d.p.)};\\ \\text{iterations required} = 6", explanation: "Six iterations bring us safely within 3 d.p. (the strict requirement is two consecutive agreements at the 3-d.p.\\ tolerance, which first occurs at \\(x_{5}\\) and \\(x_{6}\\))." } ], finalAnswer: "\\(\\alpha \\approx 1.325\\); 6 iterations required." } },
  { id: "y2nm2-033", topicRef: "y2nm2", topicTitle: "Iteration 33", difficulty: "Standard", questionText: "An iteration converges linearly when \\(|x_{n+1} - \\alpha| \\approx k|x_{n} - \\alpha|\\) for some constant \\(k\\) with \\(|k| < 1\\). State the value of \\(k\\) for the iteration \\(x_{n+1} = g(x_{n})\\) near a fixed point \\(\\alpha\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{linearise}\\ g\\ \\text{near}\\ \\alpha,\\ \\text{compare with}\\ |\\epsilon_{n+1}| \\approx k|\\epsilon_{n}|", explanation: "Same approach as Q28 but expressed in the standard 'linear-convergence constant \\(k\\)' language. We linearise \\(g\\), derive the one-step error recurrence, and read off \\(k\\)." }, { stepNumber: 2, description: "Define the error.", workingLatex: "\\epsilon_{n} = x_{n} - \\alpha", explanation: "Displacement of the current iterate from the fixed point — positive or negative." }, { stepNumber: 3, description: "Taylor-expand \\(g\\) about \\(\\alpha\\).", workingLatex: "g(x) = g(\\alpha) + g'(\\alpha)(x - \\alpha) + O\\!\\left((x - \\alpha)^{2}\\right)", explanation: "First-order Taylor expansion — accurate for \\(x\\) close to \\(\\alpha\\)." }, { stepNumber: 4, description: "Use the fixed-point condition.", workingLatex: "g(\\alpha) = \\alpha \\;\\Rightarrow\\; g(x) - \\alpha \\approx g'(\\alpha)(x - \\alpha)", explanation: "Subtract \\(\\alpha\\) from both sides — both sides are now 'displacements from \\(\\alpha\\)'." }, { stepNumber: 5, description: "Translate to the iteration.", workingLatex: "\\epsilon_{n+1} = x_{n+1} - \\alpha = g(x_{n}) - \\alpha \\approx g'(\\alpha)\\,\\epsilon_{n}", explanation: "Use the recurrence and the linearisation in one substitution." }, { stepNumber: 6, description: "Take absolute values.", workingLatex: "|\\epsilon_{n+1}| \\approx |g'(\\alpha)|\\,|\\epsilon_{n}|", explanation: "Strip out the sign — the magnitude of the error shrinks (or grows) by the factor \\(|g'(\\alpha)|\\) each step." }, { stepNumber: 7, description: "Compare with the linear-convergence form.", workingLatex: "|\\epsilon_{n+1}| \\approx k\\,|\\epsilon_{n}| \\;\\Rightarrow\\; k = |g'(\\alpha)|", explanation: "Match coefficients. The 'linear convergence constant' \\(k\\) is exactly \\(g'(\\alpha)\\) (up to a sign convention)." }, { stepNumber: 8, description: "Read off \\(k\\).", workingLatex: "k = g'(\\alpha)", explanation: "The derivative of \\(g\\) at the fixed point is the linear-convergence constant. Sign convention: many textbooks treat \\(k\\) as signed (so positive \\(k\\) gives staircase, negative \\(k\\) gives cobweb); others write \\(|k| = |g'(\\alpha)|\\)." }, { stepNumber: 9, description: "Connect to the convergence criterion.", workingLatex: "|k| < 1 \\;\\Longleftrightarrow\\; |g'(\\alpha)| < 1", explanation: "This is why the convergence criterion takes the form \\(|g'(\\alpha)| < 1\\) — it is exactly the requirement that errors shrink by a factor less than \\(1\\) each step. The smaller \\(|k|\\), the faster the convergence." } ], finalAnswer: "\\(k = g'(\\alpha)\\)." } },
  { id: "y2nm2-034", topicRef: "y2nm2", topicTitle: "Iteration 34", difficulty: "Standard", questionText: "Given \\(x_{n+1} = \\tfrac{1}{4}(x_{n}^{2} + 3)\\), show that the fixed points are \\(x = 1\\) and \\(x = 3\\), and determine which fixed point is attractive.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["fixed point", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{(i) solve}\\ \\alpha = g(\\alpha);\\ \\text{(ii) compute}\\ g'(\\alpha)\\ \\text{at each fixed point}", explanation: "Find both fixed points by setting up and factoring the resulting quadratic, then classify each using the convergence criterion \\(|g'(\\alpha)| < 1\\)." }, { stepNumber: 2, description: "Apply the fixed-point condition.", workingLatex: "\\alpha = \\displaystyle\\frac{1}{4}(\\alpha^{2} + 3)", explanation: "Set \\(x_{n+1} = x_{n} = \\alpha\\) in the recurrence." }, { stepNumber: 3, description: "Clear the fraction.", workingLatex: "4\\alpha = \\alpha^{2} + 3", explanation: "Multiply both sides by 4." }, { stepNumber: 4, description: "Rearrange to standard quadratic form.", workingLatex: "\\alpha^{2} - 4\\alpha + 3 = 0", explanation: "Move every term to one side." }, { stepNumber: 5, description: "Factorise.", workingLatex: "(\\alpha - 1)(\\alpha - 3) = 0 \\;\\Rightarrow\\; \\alpha = 1\\ \\text{or}\\ \\alpha = 3", explanation: "Two real fixed points — both genuine, but we now decide which is reachable by iteration." }, { stepNumber: 6, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{1}{4}(x^{2} + 3) \\;\\Rightarrow\\; g'(x) = \\displaystyle\\frac{x}{2}", explanation: "Differentiate term by term. The constant \\(3\\) disappears; the \\(x^{2}\\) gives \\(2x\\), and the \\(\\tfrac{1}{4}\\) factor turns \\(2x\\) into \\(x/2\\)." }, { stepNumber: 7, description: "Test \\(\\alpha = 1\\).", workingLatex: "|g'(1)| = \\left|\\displaystyle\\frac{1}{2}\\right| = 0.5 < 1", explanation: "Criterion satisfied. \\(\\alpha = 1\\) is attracting — the iteration converges from any nearby start, with errors shrinking by half each step (positive \\(g'\\) means staircase convergence)." }, { stepNumber: 8, description: "Test \\(\\alpha = 3\\).", workingLatex: "|g'(3)| = \\left|\\displaystyle\\frac{3}{2}\\right| = 1.5 > 1", explanation: "Criterion fails. \\(\\alpha = 3\\) is repelling — errors are amplified by \\(1.5\\) per step." }, { stepNumber: 9, description: "Sanity-check by running from a nearby start.", workingLatex: "x_{0} = 2.9 \\;\\Rightarrow\\; x_{1} = \\displaystyle\\frac{1}{4}(8.41 + 3) = 2.8525\\ (\\text{moved away from}\\ 3)", explanation: "Starting at \\(2.9\\) (within \\(0.1\\) of \\(3\\)), one iterate drops to \\(2.8525\\) — a displacement of \\(0.1475\\), about \\(1.5\\) times the original deviation. The iteration heads not toward \\(3\\) but toward \\(1\\) (the basin of attraction)." }, { stepNumber: 10, description: "Conclude.", workingLatex: "\\alpha = 1\\ \\text{attractive};\\ \\alpha = 3\\ \\text{repelling}", explanation: "Only \\(\\alpha = 1\\) can be reached by this iteration; \\(\\alpha = 3\\) is unstable and would require a different rearrangement (the quadratic \\(\\alpha^{2} - 4\\alpha + 3 = 0\\) can equally well be written as \\(\\alpha = 4 - 3/\\alpha\\), which has a different \\(g'\\) profile)." } ], finalAnswer: "\\(\\alpha = 1\\) is the attractive fixed point." } },
  { id: "y2nm2-035", topicRef: "y2nm2", topicTitle: "Iteration 35", difficulty: "Standard", questionText: "A root of \\(\\sin x = x - 1\\) lies near \\(x = 2\\). Write this as \\(x = \\sin x + 1\\) and apply three iterations with \\(x_{0} = 2\\) to 4 decimal places. Work in radians.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\sin x = x - 1 \\;\\longrightarrow\\; x = \\sin x + 1 \\;\\longrightarrow\\; x_{1}, x_{2}, x_{3}", explanation: "Rearrange to fixed-point form, iterate from \\(x_{0} = 2\\) (radians), and report each iterate to 4 d.p. We carry the unrounded value forward each step to avoid round-off contamination." }, { stepNumber: 2, description: "Rearrange the equation.", workingLatex: "\\sin x = x - 1 \\;\\Longleftrightarrow\\; x = \\sin x + 1", explanation: "Add \\(1\\) to both sides. Iteration: \\(x_{n+1} = \\sin(x_{n}) + 1\\). Calculator in radian mode." }, { stepNumber: 3, description: "Compute \\(\\sin 2\\) for \\(x_{1}\\).", workingLatex: "\\sin 2 = 0.909297\\ldots\\ (\\text{radians})", explanation: "Argument is past \\(\\pi/2 \\approx 1.5708\\), so we are on the descending branch of \\(\\sin\\); the value sits just below \\(\\sin(\\pi/2) = 1\\)." }, { stepNumber: 4, description: "Add \\(1\\) to get \\(x_{1}\\) and round.", workingLatex: "x_{1} = 0.909297 + 1 = 1.909297\\ldots \\approx 1.9093", explanation: "Fifth decimal is \\(9 \\geq 5\\), round up." }, { stepNumber: 5, description: "Compute \\(\\sin x_{1}\\) for \\(x_{2}\\).", workingLatex: "\\sin(1.909297) = 0.943253\\ldots", explanation: "We are on the descending branch \\((\\pi/2, \\pi)\\) where \\(\\sin\\) is decreasing. Since \\(1.909 < 2\\), \\(\\sin(1.909) > \\sin(2)\\) — the value bumps up from \\(0.909\\) to \\(0.943\\)." }, { stepNumber: 6, description: "Add \\(1\\) and round \\(x_{2}\\).", workingLatex: "x_{2} = 0.943253 + 1 = 1.943253\\ldots \\approx 1.9433", explanation: "Fifth decimal is \\(5 \\geq 5\\), round up." }, { stepNumber: 7, description: "Compute \\(\\sin x_{2}\\) for \\(x_{3}\\).", workingLatex: "\\sin(1.943253) = 0.931436\\ldots", explanation: "Continue carrying full precision; \\(1.943 > 1.909\\), so the descending branch gives a slightly smaller \\(\\sin\\) than before." }, { stepNumber: 8, description: "Add \\(1\\) and round \\(x_{3}\\).", workingLatex: "x_{3} = 0.931436 + 1 = 1.931436\\ldots \\approx 1.9314", explanation: "Fifth decimal is \\(3 < 5\\), round down." }, { stepNumber: 9, description: "Reflect on the oscillation.", workingLatex: "x_{0} = 2,\\ x_{1} \\approx 1.9093,\\ x_{2} \\approx 1.9433,\\ x_{3} \\approx 1.9314", explanation: "Iterates oscillate: down, up, down, ... with shrinking amplitude (\\(0.09, 0.034, 0.012\\)). Cobweb pattern." }, { stepNumber: 10, description: "Diagnose convergence.", workingLatex: "g'(x) = \\cos x;\\ g'(1.9346) = \\cos(1.9346) \\approx -0.356", explanation: "At the fixed point \\(\\alpha \\approx 1.9346\\), \\(|g'(\\alpha)| \\approx 0.356 < 1\\), so the iteration converges. Negative \\(g'\\) \\(\\Rightarrow\\) cobweb (alternating). Shrinkage factor \\(\\approx 0.36\\) matches the observed amplitude decay (\\(0.034/0.09 \\approx 0.38\\), \\(0.012/0.034 \\approx 0.35\\))." } ], finalAnswer: "\\(x_{1} \\approx 1.9093,\\ x_{2} \\approx 1.9433,\\ x_{3} \\approx 1.9314\\)." } },
  { id: "y2nm2-036", topicRef: "y2nm2", topicTitle: "Iteration 36", difficulty: "Standard", questionText: "Starting from \\(x_{0} = 1\\), apply the iteration \\(x_{n+1} = 3 - \\tfrac{1}{x_{n}^{2}}\\) until two successive values agree to 3 decimal places. Give the final value.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "State the strategy.", workingLatex: "x_{n+1} = g(x_{n}),\\quad g(x) = 3 - \\displaystyle\\frac{1}{x^{2}}", explanation: "We will iterate from \\(x_{0} = 1\\), carry at least 4 d.p. of working through each step, stop when two consecutive iterates agree to 3 d.p., and finally check convergence by evaluating \\(|g'(\\alpha)|\\) and verifying the fixed-point equation." }, { stepNumber: 2, description: "Record the stopping rule.", workingLatex: "\\left|x_{n+1} - x_{n}\\right| < 5 \\times 10^{-4} \\;\\Rightarrow\\; \\text{stop at 3 d.p.}", explanation: "Two iterates rounding to the same 3 d.p. value is the standard exam criterion. Carrying one extra working digit (4 d.p.) avoids round-off bias." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = 3 - \\displaystyle\\frac{1}{1^{2}} = 3 - 1 = 2.0000", explanation: "Substitute \\(x_{0} = 1\\). The first iterate jumps from 1 to 2 because the reciprocal of 1 is large." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = 3 - \\displaystyle\\frac{1}{2^{2}} = 3 - 0.25 = 2.7500", explanation: "Now \\(\\displaystyle\\frac{1}{x_{n}^{2}}\\) is much smaller, so the iterate climbs further towards the eventual root." }, { stepNumber: 5, description: "Compute \\(x_{3}\\) — unrounded.", workingLatex: "x_{3} = 3 - \\displaystyle\\frac{1}{2.75^{2}} = 3 - \\displaystyle\\frac{1}{7.5625}", explanation: "Square first, then take the reciprocal. \\(2.75^{2} = 7.5625\\) exactly." }, { stepNumber: 6, description: "Round \\(x_{3}\\).", workingLatex: "x_{3} = 3 - 0.13223\\ldots \\approx 2.8678", explanation: "Change from \\(x_{2}\\) is about \\(0.12\\) — still large, so we are not yet at the 3 d.p. answer." }, { stepNumber: 7, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = 3 - \\displaystyle\\frac{1}{2.8678^{2}} = 3 - \\displaystyle\\frac{1}{8.2243} \\approx 2.8784", explanation: "The reciprocal is shrinking, so successive corrections are getting smaller — typical staircase behaviour." }, { stepNumber: 8, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = 3 - \\displaystyle\\frac{1}{2.8784^{2}} = 3 - \\displaystyle\\frac{1}{8.2852} \\approx 2.8793", explanation: "Change from \\(x_{4}\\) is \\(\\approx 0.0009\\), already below the 3 d.p. threshold of \\(5 \\times 10^{-4}\\) when rounded." }, { stepNumber: 9, description: "Compute \\(x_{6}\\) to confirm.", workingLatex: "x_{6} = 3 - \\displaystyle\\frac{1}{2.8793^{2}} = 3 - \\displaystyle\\frac{1}{8.2904} \\approx 2.8794", explanation: "\\(x_{5}\\) and \\(x_{6}\\) both round to \\(2.879\\) at 3 d.p. — the stopping criterion is satisfied." }, { stepNumber: 10, description: "Check the convergence rate.", workingLatex: "g'(x) = \\displaystyle\\frac{2}{x^{3}} \\;\\Rightarrow\\; g'(2.879) \\approx \\displaystyle\\frac{2}{23.87} \\approx 0.084", explanation: "Since \\(|g'(\\alpha)| \\approx 0.08 < 1\\) and \\(g'(\\alpha) > 0\\), local convergence is guaranteed and the iterates approach \\(\\alpha\\) monotonically (staircase pattern), exactly as observed." }, { stepNumber: 11, description: "Sanity-check by substitution.", workingLatex: "g(2.879) = 3 - \\displaystyle\\frac{1}{2.879^{2}} \\approx 3 - 0.1206 \\approx 2.8794", explanation: "Substituting the rounded root back into \\(g\\) returns essentially the same value — \\(\\alpha\\) is a true fixed point to 3 d.p." }, { stepNumber: 12, description: "Record the root.", workingLatex: "\\alpha \\approx 2.879", explanation: "Two consecutive iterates agree to 3 d.p., the derivative test confirms convergence, and the sanity substitution confirms the root." } ], finalAnswer: "\\(\\alpha \\approx 2.879\\) to 3 d.p." } },
  { id: "y2nm2-037", topicRef: "y2nm2", topicTitle: "Iteration 37", difficulty: "Standard", questionText: "Show that \\(x^{3} - 3x + 1 = 0\\) can be rearranged as \\(x = \\tfrac{x^{3} + 1}{3}\\). Apply this iteration with \\(x_{0} = 0\\) and find the root it converges to, to 3 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "State the strategy.", workingLatex: "x^{3} - 3x + 1 = 0 \\;\\longrightarrow\\; x = g(x) = \\displaystyle\\frac{x^{3} + 1}{3}", explanation: "We will (i) rearrange algebraically into \\(x = g(x)\\) form, (ii) iterate from \\(x_{0} = 0\\) to 4 d.p. of working, (iii) stop when two consecutive iterates agree to 3 d.p., and (iv) verify \\(|g'(\\alpha)| < 1\\) so convergence is genuine." }, { stepNumber: 2, description: "Move the linear term across.", workingLatex: "x^{3} - 3x + 1 = 0 \\;\\Longrightarrow\\; 3x = x^{3} + 1", explanation: "Add \\(3x\\) to both sides; the linear term now stands alone on the right." }, { stepNumber: 3, description: "Divide through by 3 to isolate \\(x\\).", workingLatex: "x = \\displaystyle\\frac{x^{3} + 1}{3}", explanation: "Dividing by \\(3 \\neq 0\\) is reversible, so the rearrangement is equivalent to the original cubic — no roots gained or lost." }, { stepNumber: 4, description: "State the iteration formula.", workingLatex: "x_{n+1} = \\displaystyle\\frac{x_{n}^{3} + 1}{3},\\quad x_{0} = 0", explanation: "Promote the rearrangement to a recurrence by attaching subscripts." }, { stepNumber: 5, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{0^{3} + 1}{3} = \\displaystyle\\frac{1}{3} \\approx 0.3333", explanation: "Cube of 0 is 0; the iterate immediately leaps from 0 to \\(\\tfrac{1}{3}\\)." }, { stepNumber: 6, description: "Compute \\(x_{2}\\) — un-rounded.", workingLatex: "x_{2} = \\displaystyle\\frac{0.3333^{3} + 1}{3} = \\displaystyle\\frac{0.03703 + 1}{3} = \\displaystyle\\frac{1.03703}{3}", explanation: "Cube the iterate, add 1, then divide by 3. Computing \\(0.3333^{3}\\) precisely: \\(0.3333^{2} = 0.11109\\), times \\(0.3333\\) is \\(0.03703\\)." }, { stepNumber: 7, description: "Round \\(x_{2}\\).", workingLatex: "x_{2} \\approx 0.3457", explanation: "Change from \\(x_{1}\\) is \\(\\approx 0.012\\) — still bigger than the 3 d.p. threshold, so keep iterating." }, { stepNumber: 8, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{0.3457^{3} + 1}{3} = \\displaystyle\\frac{0.04131 + 1}{3} = \\displaystyle\\frac{1.04131}{3} \\approx 0.3471", explanation: "Change from \\(x_{2}\\) shrinks to \\(\\approx 0.0014\\) — getting close to the 3 d.p. answer." }, { stepNumber: 9, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\displaystyle\\frac{0.3471^{3} + 1}{3} = \\displaystyle\\frac{0.04182 + 1}{3} \\approx 0.3473", explanation: "Change from \\(x_{3}\\) is now \\(\\approx 0.0002\\), well below \\(5 \\times 10^{-4}\\)." }, { stepNumber: 10, description: "Read off the 3 d.p. value.", workingLatex: "x_{3} \\approx 0.347,\\ x_{4} \\approx 0.347 \\;\\Rightarrow\\; \\alpha \\approx 0.347", explanation: "Two consecutive iterates agree to 3 d.p. — stopping criterion satisfied." }, { stepNumber: 11, description: "Check the convergence criterion.", workingLatex: "g'(x) = x^{2} \\;\\Rightarrow\\; g'(0.347) \\approx 0.120", explanation: "\\(|g'(\\alpha)| \\approx 0.12 < 1\\) (and positive), so the iteration converges monotonically (staircase) — consistent with the iterates climbing smoothly upward." }, { stepNumber: 12, description: "Sanity-check by substitution.", workingLatex: "0.347^{3} - 3(0.347) + 1 \\approx 0.0418 - 1.041 + 1 \\approx 0.0008", explanation: "Substituting \\(\\alpha = 0.347\\) into the original cubic gives essentially zero — confirming the root to 3 d.p." } ], finalAnswer: "Converges to \\(\\approx 0.347\\)." } },
  { id: "y2nm2-038", topicRef: "y2nm2", topicTitle: "Iteration 38", difficulty: "Standard", questionText: "Given \\(x_{n+1} = \\tfrac{2 + x_{n}^{2}}{2x_{n}}\\) with \\(x_{0} = 1\\), show that \\(x_{n}\\) converges to \\(\\sqrt{2}\\) and compute \\(x_{3}\\) to 6 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "State the strategy.", workingLatex: "g(x) = \\displaystyle\\frac{2 + x^{2}}{2x};\\quad \\text{find fixed point, iterate, verify convergence}", explanation: "We first find the fixed-point equation by setting \\(x_{n+1} = x_{n} = \\alpha\\), then iterate three steps from \\(x_{0} = 1\\), then check that the iteration is in fact the Newton scheme so convergence is quadratic." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{2 + \\alpha^{2}}{2\\alpha}", explanation: "A fixed point of \\(g\\) satisfies \\(g(\\alpha) = \\alpha\\). Substitute into the formula." }, { stepNumber: 3, description: "Clear the denominator.", workingLatex: "2\\alpha^{2} = 2 + \\alpha^{2}", explanation: "Multiply both sides by \\(2\\alpha\\) (valid since \\(\\alpha \\neq 0\\) — the formula is undefined at 0)." }, { stepNumber: 4, description: "Solve for \\(\\alpha\\).", workingLatex: "\\alpha^{2} = 2 \\;\\Longrightarrow\\; \\alpha = \\pm\\sqrt{2}", explanation: "Starting from \\(x_{0} = 1 > 0\\) and noting \\(g(x) > 0\\) for \\(x > 0\\), the iteration stays positive, so the relevant fixed point is \\(\\alpha = \\sqrt{2}\\)." }, { stepNumber: 5, description: "Recognise the iteration.", workingLatex: "g(x) = \\displaystyle\\frac{1}{2}\\left(x + \\displaystyle\\frac{2}{x}\\right)", explanation: "Splitting the fraction: \\(\\displaystyle\\frac{2 + x^{2}}{2x} = \\displaystyle\\frac{x}{2} + \\displaystyle\\frac{1}{x}\\), which is the Babylonian (= Newton–Raphson) iteration for \\(\\sqrt{2}\\). This guarantees quadratic convergence." }, { stepNumber: 6, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{2 + 1^{2}}{2 \\cdot 1} = \\displaystyle\\frac{3}{2} = 1.500000", explanation: "Substitute \\(x_{0} = 1\\). Exact value — no rounding." }, { stepNumber: 7, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{2 + 1.5^{2}}{2 \\cdot 1.5} = \\displaystyle\\frac{2 + 2.25}{3} = \\displaystyle\\frac{4.25}{3}", explanation: "Numerator: \\(1.5^{2} = 2.25\\) exactly. Denominator: \\(2 \\times 1.5 = 3\\) exactly." }, { stepNumber: 8, description: "Evaluate \\(x_{2}\\) at 6 d.p.", workingLatex: "x_{2} \\approx 1.416667", explanation: "\\(\\tfrac{4.25}{3} = 1.4166\\overline{6}\\) — round to \\(1.416667\\)." }, { stepNumber: 9, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\displaystyle\\frac{2 + 1.416667^{2}}{2 \\cdot 1.416667} = \\displaystyle\\frac{2 + 2.006946}{2.833333} = \\displaystyle\\frac{4.006946}{2.833333}", explanation: "Numerator: \\(1.416667^{2} = 2.006946\\) (carrying extra digits). Denominator: \\(2 \\times 1.416667 = 2.833333\\)." }, { stepNumber: 10, description: "Evaluate \\(x_{3}\\) at 6 d.p.", workingLatex: "x_{3} \\approx 1.414216", explanation: "Long division: \\(\\tfrac{4.006946}{2.833333} \\approx 1.4142157\\), rounding to \\(1.414216\\)." }, { stepNumber: 11, description: "Verify quadratic convergence.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2}\\left(1 - \\displaystyle\\frac{2}{x^{2}}\\right) \\;\\Rightarrow\\; g'(\\sqrt{2}) = \\displaystyle\\frac{1}{2}(1 - 1) = 0", explanation: "Differentiating and evaluating at \\(\\sqrt{2}\\) gives exactly zero — \\(|g'(\\alpha)| = 0\\), the hallmark of Newton's method, so the error squares each step (quadratic convergence)." }, { stepNumber: 12, description: "Sanity-check.", workingLatex: "1.414216^{2} \\approx 2.000007 \\;\\Rightarrow\\; \\sqrt{2} \\approx 1.414214", explanation: "\\(x_{3}\\) is already correct to 5 d.p.; the true value \\(\\sqrt{2} = 1.4142135\\ldots\\) differs only in the 6th decimal." } ], finalAnswer: "\\(x_{3} \\approx 1.414216\\)." } },
  { id: "y2nm2-039", topicRef: "y2nm2", topicTitle: "Iteration 39", difficulty: "Standard", questionText: "Use the iteration \\(x_{n+1} = \\tfrac{3}{x_{n} + 1}\\) with \\(x_{0} = 1\\). Compute \\(x_{1},\\ x_{2},\\ x_{3}\\) and \\(x_{4}\\) to 4 decimal places, and find the equation whose root the iteration converges to.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration", "fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "State the strategy.", workingLatex: "g(x) = \\displaystyle\\frac{3}{x + 1};\\quad \\text{iterate, then solve } \\alpha = g(\\alpha)", explanation: "We iterate four times from \\(x_{0} = 1\\) to track the oscillation, then derive the fixed-point quadratic, solve it for the positive root, and finally verify convergence via \\(|g'(\\alpha)|\\)." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = \\displaystyle\\frac{3}{x_{n} + 1},\\quad x_{0} = 1", explanation: "Each iterate is 3 divided by (previous + 1) — simple but oscillatory because \\(g\\) is decreasing." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{3}{1 + 1} = \\displaystyle\\frac{3}{2} = 1.5000", explanation: "Exact value; no rounding needed." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{3}{1.5 + 1} = \\displaystyle\\frac{3}{2.5} = 1.2000", explanation: "Iterate dropped below the start; the iteration has just crossed the (suspected) limit." }, { stepNumber: 5, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{3}{1.2 + 1} = \\displaystyle\\frac{3}{2.2} \\approx 1.3636", explanation: "And back up again — cobweb is in full swing." }, { stepNumber: 6, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\displaystyle\\frac{3}{1.3636 + 1} = \\displaystyle\\frac{3}{2.3636} \\approx 1.2692", explanation: "Down once more. The oscillation amplitude is visibly shrinking (\\(0.5 \\to 0.3 \\to 0.16 \\to 0.09\\))." }, { stepNumber: 7, description: "Tabulate to spot the convergence centre.", workingLatex: "1.5000,\\ 1.2000,\\ 1.3636,\\ 1.2692 \\;\\to\\; \\alpha \\approx 1.30", explanation: "Odd-indexed iterates are decreasing from \\(1.5\\) and even-indexed iterates are increasing from \\(1.2\\); they sandwich the true limit near \\(1.30\\)." }, { stepNumber: 8, description: "Derive the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{3}{\\alpha + 1}", explanation: "A fixed point of the iteration satisfies \\(\\alpha = g(\\alpha)\\)." }, { stepNumber: 9, description: "Clear the denominator.", workingLatex: "\\alpha(\\alpha + 1) = 3 \\;\\Longrightarrow\\; \\alpha^{2} + \\alpha - 3 = 0", explanation: "Multiply both sides by \\((\\alpha + 1)\\) and expand. The fixed points are the (real) roots of this quadratic." }, { stepNumber: 10, description: "Solve the quadratic.", workingLatex: "\\alpha = \\displaystyle\\frac{-1 \\pm \\sqrt{1 + 12}}{2} = \\displaystyle\\frac{-1 \\pm \\sqrt{13}}{2}", explanation: "Discriminant \\(= 1 + 12 = 13\\). Two roots: positive and negative." }, { stepNumber: 11, description: "Choose the positive root.", workingLatex: "\\alpha = \\displaystyle\\frac{-1 + \\sqrt{13}}{2} \\approx \\displaystyle\\frac{-1 + 3.6056}{2} \\approx 1.3028", explanation: "The iterates are clearly positive and converging to \\(\\approx 1.3\\), so this is the relevant root." }, { stepNumber: 12, description: "Verify convergence via \\(g'\\).", workingLatex: "g'(x) = -\\displaystyle\\frac{3}{(x + 1)^{2}} \\;\\Rightarrow\\; g'(1.3028) \\approx -\\displaystyle\\frac{3}{5.302} \\approx -0.566", explanation: "\\(|g'(\\alpha)| \\approx 0.57 < 1\\) (so convergent) with \\(g'(\\alpha) < 0\\) (so cobweb pattern — alternating sides) — exactly what we observed." } ], finalAnswer: "\\(\\alpha^{2} + \\alpha - 3 = 0\\); positive root \\(\\approx 1.3028\\)." } },
  { id: "y2nm2-040", topicRef: "y2nm2", topicTitle: "Iteration 40", difficulty: "Standard", questionText: "Describe, in one sentence, the difference between a staircase diagram and a cobweb diagram for an iteration \\(x_{n+1} = g(x_{n})\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Both diagrams visualise }x_{n+1} = g(x_{n})\\text{ on the }(x, y)\\text{ plane}", explanation: "We will recall the shared construction (the curve and the diagonal), explain the two distinct visual patterns, link each to the sign of \\(g'(\\alpha)\\), and finish with a one-line summary." }, { stepNumber: 2, description: "Recall the shared construction.", workingLatex: "y = g(x)\\;\\text{ and }\\;y = x", explanation: "On the same axes draw the iteration function \\(y = g(x)\\) and the diagonal \\(y = x\\). Fixed points sit where the two graphs cross." }, { stepNumber: 3, description: "How to read one iteration step.", workingLatex: "x_{n} \\to (x_{n}, g(x_{n})) \\to (g(x_{n}), g(x_{n})) = (x_{n+1}, x_{n+1})", explanation: "Bouncing vertically from the \\(x\\)-axis to the curve produces \\(g(x_{n})\\); bouncing horizontally from there to the diagonal moves to the point \\((x_{n+1}, x_{n+1})\\), ready for the next step." }, { stepNumber: 4, description: "Staircase: monotone case.", workingLatex: "0 < g'(\\alpha) < 1 \\;\\Longrightarrow\\; \\text{staircase}", explanation: "When \\(g'(\\alpha) > 0\\) and below 1, the curve has positive slope below the diagonal; iterates approach \\(\\alpha\\) from the same side, drawing an \\(L\\)-shaped step pattern that converges monotonically." }, { stepNumber: 5, description: "Cobweb: alternating case.", workingLatex: "-1 < g'(\\alpha) < 0 \\;\\Longrightarrow\\; \\text{cobweb}", explanation: "When \\(g'(\\alpha) < 0\\) with magnitude below 1, the curve has negative slope; iterates jump alternately above and below \\(\\alpha\\), drawing a spiral that shrinks inwards — the cobweb." }, { stepNumber: 6, description: "Divergent variants for reference.", workingLatex: "|g'(\\alpha)| > 1 \\;\\Longrightarrow\\; \\text{steps fly outward (divergent)}", explanation: "If \\(|g'(\\alpha)| > 1\\), the same shapes appear but expanding outward instead of inward — divergent staircase (\\(g' > 1\\)) or divergent cobweb (\\(g' < -1\\))." }, { stepNumber: 7, description: "Common-mistake watch-out.", workingLatex: "g'(\\alpha) = 0 \\;\\not\\Rightarrow\\; \\text{cycle}", explanation: "Don't confuse zero derivative with a flat line: \\(g'(\\alpha) = 0\\) gives super-fast (quadratic) convergence in a degenerate staircase pattern. Cycling occurs only at \\(|g'(\\alpha)| = 1\\) exactly." }, { stepNumber: 8, description: "Summarise.", workingLatex: "\\text{sign of } g'(\\alpha) \\text{ decides the pattern; magnitude decides convergence}", explanation: "Magnitude \\(|g'(\\alpha)| < 1\\) gives convergence in both cases; the sign of \\(g'(\\alpha)\\) decides whether the picture is a staircase (positive slope, same-side approach) or a cobweb (negative slope, alternating approach)." } ], finalAnswer: "Staircase \\(= 0 < g' < 1\\) (monotone); cobweb \\(= -1 < g' < 0\\) (alternating)." } },
  { id: "y2nm2-041", topicRef: "y2nm2", topicTitle: "Iteration 41", difficulty: "Standard", questionText: "The iteration \\(x_{n+1} = \\tfrac{1}{2}\\!\\left(1 + \\tfrac{3}{x_{n}}\\right)\\) is applied to solve \\(2x^{2} - x - 3 = 0\\). Verify that a fixed point satisfies \\(2x^{2} - x - 3 = 0\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = g(\\alpha) \\;\\longrightarrow\\; \\text{clear fractions} \\;\\longrightarrow\\; 2\\alpha^{2} - \\alpha - 3 = 0", explanation: "We will substitute \\(\\alpha\\) into the iteration formula, clear both fractions step-by-step, rearrange to the standard quadratic, factorise to find both fixed points explicitly, and then verify each by direct substitution into \\(g\\)." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{1}{2}\\!\\left(1 + \\displaystyle\\frac{3}{\\alpha}\\right)", explanation: "A fixed point of \\(x_{n+1} = g(x_{n})\\) satisfies \\(\\alpha = g(\\alpha)\\) — substitute \\(x = \\alpha\\) on both sides." }, { stepNumber: 3, description: "Multiply by 2 to clear the leading half.", workingLatex: "2\\alpha = 1 + \\displaystyle\\frac{3}{\\alpha}", explanation: "Multiplying by \\(2\\) is reversible (\\(2 \\neq 0\\)) so no roots are introduced or lost." }, { stepNumber: 4, description: "Multiply through by \\(\\alpha\\).", workingLatex: "2\\alpha \\cdot \\alpha = \\alpha + 3 \\;\\Longrightarrow\\; 2\\alpha^{2} = \\alpha + 3", explanation: "Valid because \\(\\alpha \\neq 0\\) — the original formula contains \\(\\tfrac{3}{\\alpha}\\), which is undefined at zero, so zero cannot be a fixed point." }, { stepNumber: 5, description: "Bring all terms to one side.", workingLatex: "2\\alpha^{2} - \\alpha - 3 = 0", explanation: "This is exactly the quadratic the question asked us to verify. Shown." }, { stepNumber: 6, description: "Factorise.", workingLatex: "2\\alpha^{2} - \\alpha - 3 = (2\\alpha - 3)(\\alpha + 1) = 0", explanation: "Look for two numbers multiplying to \\(2 \\cdot (-3) = -6\\) and summing to \\(-1\\): they are \\(-3\\) and \\(+2\\). Split \\(-\\alpha = -3\\alpha + 2\\alpha\\) and factor by grouping." }, { stepNumber: 7, description: "Read off the fixed points.", workingLatex: "\\alpha = \\displaystyle\\frac{3}{2}\\ \\text{or}\\ \\alpha = -1", explanation: "Two candidate limits. Either could be reached, depending on the starting value \\(x_{0}\\)." }, { stepNumber: 8, description: "Verify \\(\\alpha = \\tfrac{3}{2}\\) by substitution.", workingLatex: "g(3/2) = \\displaystyle\\frac{1}{2}\\!\\left(1 + \\displaystyle\\frac{3}{3/2}\\right) = \\displaystyle\\frac{1}{2}(1 + 2) = \\displaystyle\\frac{3}{2}\\ \\checkmark", explanation: "Substituting \\(\\alpha = \\tfrac{3}{2}\\) into \\(g\\) returns \\(\\tfrac{3}{2}\\) — confirming the fixed-point relation." }, { stepNumber: 9, description: "Verify \\(\\alpha = -1\\) by substitution.", workingLatex: "g(-1) = \\displaystyle\\frac{1}{2}\\!\\left(1 + \\displaystyle\\frac{3}{-1}\\right) = \\displaystyle\\frac{1}{2}(1 - 3) = -1\\ \\checkmark", explanation: "Likewise \\(g(-1) = -1\\). Both algebraic roots are genuine fixed points of \\(g\\)." }, { stepNumber: 10, description: "Classify the fixed points.", workingLatex: "g'(x) = -\\displaystyle\\frac{3}{2x^{2}} \\;\\Rightarrow\\; g'(3/2) = -\\displaystyle\\frac{2}{3} \\approx -0.667,\\ g'(-1) = -\\displaystyle\\frac{3}{2}", explanation: "At \\(\\alpha = \\tfrac{3}{2}\\): \\(|g'| \\approx 0.67 < 1\\) — attracting (cobweb pattern, since \\(g' < 0\\)). At \\(\\alpha = -1\\): \\(|g'| = 1.5 > 1\\) — repelling. So only the positive root \\(\\tfrac{3}{2}\\) is found by iteration." } ], finalAnswer: "Fixed points \\(\\alpha = \\tfrac{3}{2}\\) and \\(-1\\), which also satisfy \\(2x^{2} - x - 3 = 0\\)." } },
  { id: "y2nm2-042", topicRef: "y2nm2", topicTitle: "Iteration 42", difficulty: "Standard", questionText: "An iteration is given by \\(x_{n+1} = \\tfrac{x_{n} + 2}{x_{n}^{2}}\\) with \\(x_{0} = 2\\). Compute \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "State the strategy.", workingLatex: "g(x) = \\displaystyle\\frac{x + 2}{x^{2}};\\quad \\text{iterate, then check }|g'(\\alpha)|", explanation: "We iterate three times, watch the values bounce around, then derive the fixed-point equation, evaluate \\(|g'(\\alpha)|\\) at the true root, and conclude whether the iteration diverges or converges from this start." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = \\displaystyle\\frac{x_{n} + 2}{x_{n}^{2}},\\quad x_{0} = 2", explanation: "Each step: add 2 to the previous iterate, then divide by its square." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{2 + 2}{2^{2}} = \\displaystyle\\frac{4}{4} = 1.0000", explanation: "Substitute \\(x_{0} = 2\\). Exact value." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1 + 2}{1^{2}} = \\displaystyle\\frac{3}{1} = 3.0000", explanation: "The iterate has jumped from 1 back up to 3 — a 200% swing in one step. Not a sign of convergence." }, { stepNumber: 5, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{3 + 2}{3^{2}} = \\displaystyle\\frac{5}{9} \\approx 0.5556", explanation: "Now the iterate crashes down to about \\(0.56\\). The sequence is clearly not settling — successive values move \\emph{further apart}, not closer." }, { stepNumber: 6, description: "Reflect: what would convergence look like?", workingLatex: "2.0000 \\to 1.0000 \\to 3.0000 \\to 0.5556", explanation: "Convergence would show shrinking gaps between consecutive iterates. Here the gaps are growing: \\(|1 - 2| = 1\\), \\(|3 - 1| = 2\\), \\(|0.56 - 3| = 2.44\\). Successive errors are increasing." }, { stepNumber: 7, description: "Derive the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{\\alpha + 2}{\\alpha^{2}} \\;\\Longrightarrow\\; \\alpha^{3} = \\alpha + 2 \\;\\Longrightarrow\\; \\alpha^{3} - \\alpha - 2 = 0", explanation: "Multiply both sides by \\(\\alpha^{2}\\) (\\(\\alpha \\neq 0\\)) and rearrange. The real root is \\(\\alpha \\approx 1.5214\\)." }, { stepNumber: 8, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{x + 2}{x^{2}} = \\displaystyle\\frac{1}{x} + \\displaystyle\\frac{2}{x^{2}} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{1}{x^{2}} - \\displaystyle\\frac{4}{x^{3}}", explanation: "Split \\(g\\) before differentiating: each term is a simple negative power." }, { stepNumber: 9, description: "Evaluate \\(g'(\\alpha)\\).", workingLatex: "g'(1.5214) = -\\displaystyle\\frac{1}{2.3146} - \\displaystyle\\frac{4}{3.5212} \\approx -0.432 - 1.136 \\approx -1.568", explanation: "\\(|g'(\\alpha)| \\approx 1.57 > 1\\) — the iteration is \\emph{repelling} at the fixed point, so iterates near \\(\\alpha\\) get pushed away." }, { stepNumber: 10, description: "Conclude.", workingLatex: "|g'(\\alpha)| > 1 \\;\\Rightarrow\\; \\text{divergence from any nearby start}", explanation: "Although a real root exists, this rearrangement cannot find it from \\(x_{0} = 2\\) (or any value close to \\(\\alpha\\)). A different rearrangement is needed — see Q43 for the working Babylonian style." } ], finalAnswer: "\\(x_{1} = 1.0000,\\ x_{2} = 3.0000,\\ x_{3} \\approx 0.5556\\) (sequence does not converge)." } },
  { id: "y2nm2-043", topicRef: "y2nm2", topicTitle: "Iteration 43", difficulty: "Standard", questionText: "Given \\(f(x) = x^{2} - 7\\), derive the iteration \\(x_{n+1} = \\tfrac{1}{2}\\!\\left(x_{n} + \\tfrac{7}{x_{n}}\\right)\\) and use it to estimate \\(\\sqrt{7}\\) to 4 decimal places starting from \\(x_{0} = 3\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "f(x) = 0 \\;\\longrightarrow\\; x = g(x) \\;\\longrightarrow\\; \\text{average to damp};\\;\\text{iterate;}\\;\\text{verify}", explanation: "We first turn \\(f(x) = 0\\) into \\(x = 7/x\\), notice that this on its own oscillates, then average it with \\(x\\) itself to produce the Babylonian iteration. We verify the fixed point is \\(\\sqrt{7}\\), iterate three times from \\(x_{0} = 3\\) at 4 d.p. precision, and verify \\(g'(\\sqrt{7}) = 0\\) (quadratic convergence)." }, { stepNumber: 2, description: "Move the constant across.", workingLatex: "x^{2} - 7 = 0 \\;\\Longrightarrow\\; x^{2} = 7", explanation: "Add \\(7\\) to both sides — the standard first move." }, { stepNumber: 3, description: "Divide by \\(x\\) to get one rearrangement.", workingLatex: "x = \\displaystyle\\frac{7}{x}\\quad (x \\neq 0)", explanation: "Iterating this alone is hopeless: it just flips between \\(x_{0}\\) and \\(7/x_{0}\\). We need to damp the oscillation." }, { stepNumber: 4, description: "Average with \\(x\\) itself.", workingLatex: "x = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{7}{x}\\right)", explanation: "At the root both \\(x\\) and \\(7/x\\) equal \\(\\sqrt{7}\\), so their average is also \\(\\sqrt{7}\\) — the rearrangement is valid. Crucially the average damps the oscillation and gives the Newton step for \\(f\\)." }, { stepNumber: 5, description: "State the iteration.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{2}\\!\\left(x_{n} + \\displaystyle\\frac{7}{x_{n}}\\right),\\quad x_{0} = 3", explanation: "Promote the rearrangement to a recurrence." }, { stepNumber: 6, description: "Verify the fixed point.", workingLatex: "\\alpha = \\displaystyle\\frac{1}{2}\\!\\left(\\alpha + \\displaystyle\\frac{7}{\\alpha}\\right) \\;\\Longrightarrow\\; 2\\alpha^{2} = \\alpha^{2} + 7 \\;\\Longrightarrow\\; \\alpha^{2} = 7 \\;\\Longrightarrow\\; \\alpha = \\sqrt{7}", explanation: "Standard manipulation — multiply by 2 and by \\(\\alpha\\), simplify. The positive root is selected since \\(x_{0} > 0\\)." }, { stepNumber: 7, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}\\!\\left(3 + \\displaystyle\\frac{7}{3}\\right) = \\displaystyle\\frac{1}{2}(3 + 2.3333) = \\displaystyle\\frac{1}{2}(5.3333) \\approx 2.6667", explanation: "Substitute \\(x_{0} = 3\\). Note \\(\\tfrac{7}{3} = 2.3333\\ldots\\), carry 4 d.p." }, { stepNumber: 8, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}\\!\\left(2.6667 + \\displaystyle\\frac{7}{2.6667}\\right)", explanation: "\\(\\tfrac{7}{2.6667} = 2.6250\\) (to 4 d.p.)." }, { stepNumber: 9, description: "Evaluate \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}(2.6667 + 2.6250) = \\displaystyle\\frac{1}{2}(5.2917) \\approx 2.6458", explanation: "Already close to the answer — Newton converges fast." }, { stepNumber: 10, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}\\!\\left(2.6458 + \\displaystyle\\frac{7}{2.6458}\\right)", explanation: "\\(\\tfrac{7}{2.6458} \\approx 2.6457\\)." }, { stepNumber: 11, description: "Evaluate \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}(2.6458 + 2.6457) \\approx 2.6458", explanation: "\\(x_{2}\\) and \\(x_{3}\\) agree to 4 d.p. — the iteration has converged at this precision." }, { stepNumber: 12, description: "Confirm quadratic convergence.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{7}{x^{2}}\\right) \\;\\Rightarrow\\; g'(\\sqrt{7}) = \\displaystyle\\frac{1}{2}(1 - 1) = 0", explanation: "\\(g'(\\alpha) = 0\\) — the Babylonian iteration has the Newton property, so the error squares each step. Two iterates were enough." }, { stepNumber: 13, description: "Sanity-check.", workingLatex: "2.6458^{2} = 6.99974 \\approx 7\\ \\checkmark", explanation: "Squaring the answer gives essentially \\(7\\). The true value is \\(\\sqrt{7} = 2.6457513\\ldots\\), so \\(2.6458\\) is correct to 4 d.p." } ], finalAnswer: "\\(\\sqrt{7} \\approx 2.6458\\)." } },
  { id: "y2nm2-044", topicRef: "y2nm2", topicTitle: "Iteration 44", difficulty: "Standard", questionText: "Apply the iteration \\(x_{n+1} = \\sqrt{2 + x_{n}}\\) with \\(x_{0} = 0\\). Compute \\(x_{1}\\) to \\(x_{5}\\) to 4 decimal places and state the limit.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = \\sqrt{2 + x}; \\quad\\text{iterate, then solve }g(\\alpha) = \\alpha", explanation: "We iterate five times from \\(x_{0} = 0\\), watch the monotonic climb, derive the fixed-point quadratic by squaring, choose the positive root, and verify the convergence rate \\(|g'(\\alpha)|\\)." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = \\sqrt{2 + x_{n}},\\quad x_{0} = 0", explanation: "Add 2, take the (positive) square root. Stays positive throughout because the radicand stays at least 2." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\sqrt{2 + 0} = \\sqrt{2} \\approx 1.4142", explanation: "\\(\\sqrt{2} = 1.41421356\\ldots\\), rounding to 4 d.p." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\sqrt{2 + 1.4142} = \\sqrt{3.4142} \\approx 1.8478", explanation: "\\(3.4142^{0.5} = 1.84776\\), rounding gives \\(1.8478\\)." }, { stepNumber: 5, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\sqrt{2 + 1.8478} = \\sqrt{3.8478} \\approx 1.9616", explanation: "Change from \\(x_{2}\\) is \\(\\approx 0.114\\) — still substantial. Iterates still climbing." }, { stepNumber: 6, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\sqrt{2 + 1.9616} = \\sqrt{3.9616} \\approx 1.9904", explanation: "Change shrinks to \\(\\approx 0.029\\). The iteration is decelerating as it approaches the limit from below." }, { stepNumber: 7, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = \\sqrt{2 + 1.9904} = \\sqrt{3.9904} \\approx 1.9976", explanation: "Change now only \\(\\approx 0.007\\). All iterates are monotonically increasing — staircase pattern." }, { stepNumber: 8, description: "Find the fixed-point equation.", workingLatex: "\\alpha = \\sqrt{2 + \\alpha} \\;\\Longrightarrow\\; \\alpha^{2} = 2 + \\alpha \\;\\Longrightarrow\\; \\alpha^{2} - \\alpha - 2 = 0", explanation: "Square both sides (valid because \\(\\alpha \\geq 0\\) — the iteration values are all positive)." }, { stepNumber: 9, description: "Factorise.", workingLatex: "\\alpha^{2} - \\alpha - 2 = (\\alpha - 2)(\\alpha + 1) = 0", explanation: "Two numbers multiplying to \\(-2\\) and summing to \\(-1\\): \\(-2\\) and \\(+1\\)." }, { stepNumber: 10, description: "Choose the valid root.", workingLatex: "\\alpha = 2\\quad (\\text{not } -1)", explanation: "Since \\(\\alpha = \\sqrt{2 + \\alpha} \\geq 0\\), the negative root \\(-1\\) is extraneous (it solves the squared equation but not the original). Only \\(\\alpha = 2\\)." }, { stepNumber: 11, description: "Verify convergence.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2\\sqrt{2 + x}} \\;\\Rightarrow\\; g'(2) = \\displaystyle\\frac{1}{2\\sqrt{4}} = \\displaystyle\\frac{1}{4} = 0.25", explanation: "\\(|g'(\\alpha)| = 0.25 < 1\\) with \\(g'(\\alpha) > 0\\) — guaranteed monotone (staircase) convergence, consistent with the steady climb \\(0 \\to 1.41 \\to 1.85 \\to 1.96 \\to 1.99 \\to 1.998\\)." }, { stepNumber: 12, description: "Sanity-check.", workingLatex: "g(2) = \\sqrt{2 + 2} = \\sqrt{4} = 2\\ \\checkmark", explanation: "\\(\\alpha = 2\\) is indeed a fixed point of \\(g\\). The iterates are converging towards it from below." }, { stepNumber: 13, description: "State the limit.", workingLatex: "x_{n} \\to 2", explanation: "Iterates climb monotonically with shrinking gaps, so the sequence has limit \\(2\\)." } ], finalAnswer: "Converges to 2." } },
  { id: "y2nm2-045", topicRef: "y2nm2", topicTitle: "Iteration 45", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = \\tfrac{1}{2}(x_{n} + a/x_{n})\\) (the Babylonian method for \\(\\sqrt{a}\\)), show that \\(g'(\\sqrt{a}) = 0\\) and explain why this gives faster than linear convergence.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g'(\\sqrt{a}) \\stackrel{?}{=} 0 \\;\\longrightarrow\\; \\text{Taylor expansion} \\;\\longrightarrow\\; \\text{quadratic convergence}", explanation: "We differentiate \\(g\\), evaluate at \\(x = \\sqrt{a}\\), and show the derivative is exactly zero. We then explain via Taylor expansion why \\(g'(\\alpha) = 0\\) upgrades the convergence from linear to quadratic." }, { stepNumber: 2, description: "Write the iteration function.", workingLatex: "g(x) = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{a}{x}\\right) = \\displaystyle\\frac{x}{2} + \\displaystyle\\frac{a}{2x}", explanation: "Split into two terms so each can be differentiated separately." }, { stepNumber: 3, description: "Differentiate the first term.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left(\\displaystyle\\frac{x}{2}\\right) = \\displaystyle\\frac{1}{2}", explanation: "Linear function, slope \\(\\tfrac{1}{2}\\)." }, { stepNumber: 4, description: "Differentiate the second term.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left(\\displaystyle\\frac{a}{2x}\\right) = \\displaystyle\\frac{a}{2} \\cdot \\left(-\\displaystyle\\frac{1}{x^{2}}\\right) = -\\displaystyle\\frac{a}{2x^{2}}", explanation: "Use \\(\\displaystyle\\frac{d}{dx}(x^{-1}) = -x^{-2}\\)." }, { stepNumber: 5, description: "Combine.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2} - \\displaystyle\\frac{a}{2x^{2}} = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{a}{x^{2}}\\right)", explanation: "Factor out \\(\\tfrac{1}{2}\\) for clarity." }, { stepNumber: 6, description: "Substitute \\(x = \\sqrt{a}\\).", workingLatex: "g'(\\sqrt{a}) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{a}{(\\sqrt{a})^{2}}\\right) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{a}{a}\\right)", explanation: "Use \\((\\sqrt{a})^{2} = a\\). The quotient inside collapses to \\(1\\)." }, { stepNumber: 7, description: "Conclude \\(g'(\\sqrt{a}) = 0\\).", workingLatex: "g'(\\sqrt{a}) = \\displaystyle\\frac{1}{2}(1 - 1) = 0", explanation: "Shown. The slope of \\(g\\) at the fixed point is exactly zero — a striking property." }, { stepNumber: 8, description: "Recall linear convergence.", workingLatex: "|x_{n+1} - \\alpha| \\approx |g'(\\alpha)|\\,|x_{n} - \\alpha|", explanation: "For a generic fixed-point iteration, the error shrinks by a factor of \\(|g'(\\alpha)|\\) each step — linear convergence with rate \\(|g'(\\alpha)| < 1\\)." }, { stepNumber: 9, description: "Apply Taylor expansion of \\(g\\) about \\(\\alpha\\).", workingLatex: "g(x_{n}) = g(\\alpha) + g'(\\alpha)(x_{n} - \\alpha) + \\displaystyle\\frac{1}{2}g''(\\alpha)(x_{n} - \\alpha)^{2} + \\cdots", explanation: "Taylor's theorem to second order with Lagrange remainder. Since \\(g(\\alpha) = \\alpha\\) and \\(x_{n+1} = g(x_{n})\\)." }, { stepNumber: 10, description: "Use \\(g'(\\alpha) = 0\\) to kill the linear term.", workingLatex: "x_{n+1} - \\alpha = \\displaystyle\\frac{1}{2}g''(\\alpha)(x_{n} - \\alpha)^{2} + \\cdots", explanation: "The dominant error term is now \\emph{quadratic} in the previous error. Each step roughly squares the error." }, { stepNumber: 11, description: "Translate to digits.", workingLatex: "|x_{n+1} - \\alpha| \\approx \\tfrac{1}{2}|g''(\\alpha)|\\,|x_{n} - \\alpha|^{2}", explanation: "If \\(|x_{n} - \\alpha| \\sim 10^{-k}\\), then \\(|x_{n+1} - \\alpha| \\sim 10^{-2k}\\) — the number of correct decimal digits roughly doubles every step." }, { stepNumber: 12, description: "Conclude.", workingLatex: "\\text{Babylonian method: quadratic convergence near } \\sqrt{a}", explanation: "Dramatic acceleration: a typical Newton/Babylonian iteration needs only 4–5 steps to reach machine precision, whereas linear iterations need many more. This is exactly why ancient computers (and modern ones!) used this scheme to compute square roots." } ], finalAnswer: "Zero first-derivative gives quadratic (faster than linear) convergence." } },
  { id: "y2nm2-046", topicRef: "y2nm2", topicTitle: "Iteration 46", difficulty: "Standard", questionText: "Show that \\(x = \\tfrac{1}{\\sqrt{x + 1}}\\) is equivalent to \\(x^{2}(x + 1) = 1\\) and apply this iteration with \\(x_{0} = 1\\). Compute \\(x_{1}\\) and \\(x_{2}\\) to 4 decimal places.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration", "rearranging"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{2}(x + 1) = 1 \\;\\longleftrightarrow\\; x = \\displaystyle\\frac{1}{\\sqrt{x + 1}};\\;\\;\\text{iterate from }x_{0} = 1", explanation: "We will show the two equations are equivalent by isolating \\(x^{2}\\) and taking the positive square root, then iterate twice and finally check \\(|g'(\\alpha)|\\) to confirm the (slow) convergence we see." }, { stepNumber: 2, description: "Isolate \\(x^{2}\\) in the cubic form.", workingLatex: "x^{2}(x + 1) = 1 \\;\\Longrightarrow\\; x^{2} = \\displaystyle\\frac{1}{x + 1}", explanation: "Divide both sides by \\((x + 1)\\). For the positive root we are seeking, \\(x + 1 > 0\\), so this is valid and reversible." }, { stepNumber: 3, description: "Take the positive square root.", workingLatex: "x = \\displaystyle\\frac{1}{\\sqrt{x + 1}}", explanation: "Square root of \\(\\displaystyle\\frac{1}{x + 1}\\) is \\(\\displaystyle\\frac{1}{\\sqrt{x + 1}}\\). Choose the positive branch since the root sits in \\((0, 1)\\)." }, { stepNumber: 4, description: "Reversibility check.", workingLatex: "x = \\displaystyle\\frac{1}{\\sqrt{x + 1}} \\;\\Longrightarrow\\; x^{2} = \\displaystyle\\frac{1}{x + 1} \\;\\Longrightarrow\\; x^{2}(x + 1) = 1", explanation: "Squaring back recovers the cubic, so the two forms are equivalent (for \\(x > 0\\))." }, { stepNumber: 5, description: "State the iteration formula.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{\\sqrt{x_{n} + 1}},\\quad x_{0} = 1", explanation: "Promote the rearrangement to a recurrence." }, { stepNumber: 6, description: "Compute \\(x_{1}\\) — set-up.", workingLatex: "x_{1} = \\displaystyle\\frac{1}{\\sqrt{1 + 1}} = \\displaystyle\\frac{1}{\\sqrt{2}}", explanation: "Substitute \\(x_{0} = 1\\). \\(\\sqrt{2}\\) is a familiar value." }, { stepNumber: 7, description: "Evaluate \\(x_{1}\\) at 4 d.p.", workingLatex: "x_{1} = \\displaystyle\\frac{1}{1.4142} \\approx 0.7071", explanation: "\\(\\tfrac{1}{\\sqrt{2}} = 0.70710678\\ldots\\), rounding to \\(0.7071\\)." }, { stepNumber: 8, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{1}{\\sqrt{0.7071 + 1}} = \\displaystyle\\frac{1}{\\sqrt{1.7071}}", explanation: "Add 1 to the previous iterate, then take the square root." }, { stepNumber: 9, description: "Evaluate the square root.", workingLatex: "\\sqrt{1.7071} \\approx 1.3066", explanation: "\\(1.3066^{2} = 1.70720\\), close to \\(1.7071\\)." }, { stepNumber: 10, description: "Evaluate \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{1.3066} \\approx 0.7654", explanation: "\\(\\tfrac{1}{1.3066} = 0.76535\\ldots\\), rounding to \\(0.7654\\)." }, { stepNumber: 11, description: "Observe the oscillation.", workingLatex: "1.0000 \\to 0.7071 \\to 0.7654 \\to \\cdots \\to \\alpha \\approx 0.7549", explanation: "The iterates straddle the true fixed point \\(\\alpha\\) (positive root of \\(x^{3} + x^{2} - 1 = 0\\), \\(\\alpha \\approx 0.7549\\)) — first below, then above. This is the cobweb pattern, predicted by \\(g'(\\alpha) < 0\\) (see Q47 for the calculation \\(g'(\\alpha) \\approx -0.215\\))." } ], finalAnswer: "\\(x_{1} \\approx 0.7071,\\ x_{2} \\approx 0.7654\\)." } },
  { id: "y2nm2-047", topicRef: "y2nm2", topicTitle: "Iteration 47", difficulty: "Standard", questionText: "For the iteration \\(x_{n+1} = \\tfrac{1}{\\sqrt{x_{n} + 1}}\\) with fixed point \\(\\alpha\\) satisfying \\(\\alpha^{2}(\\alpha + 1) = 1\\) (so \\(\\alpha \\approx 0.7549\\)), find \\(g'(\\alpha)\\) to 3 decimal places and state whether the iteration converges.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = (x + 1)^{-1/2} \\;\\longrightarrow\\; g'(x) \\;\\longrightarrow\\; \\text{evaluate at }\\alpha \\;\\longrightarrow\\; \\text{compare to }1", explanation: "We rewrite \\(g\\) as a negative-power expression so the chain rule is clean, differentiate, substitute \\(\\alpha\\), simplify \\((1.7549)^{3/2}\\) by writing it as \\(x\\sqrt{x}\\), apply \\(|g'(\\alpha)| < 1\\) to deduce convergence, and finally classify the pattern using the sign." }, { stepNumber: 2, description: "Rewrite \\(g\\) as a power.", workingLatex: "g(x) = \\displaystyle\\frac{1}{\\sqrt{x + 1}} = (x + 1)^{-1/2}", explanation: "Putting \\(g\\) in power form makes the chain rule mechanical." }, { stepNumber: 3, description: "Apply the chain rule.", workingLatex: "g'(x) = -\\displaystyle\\frac{1}{2}(x + 1)^{-3/2} \\cdot 1", explanation: "Power rule: bring down the exponent \\(-\\tfrac{1}{2}\\), reduce by 1 (so \\(-\\tfrac{3}{2}\\)). The inner derivative \\(\\displaystyle\\frac{d}{dx}(x + 1) = 1\\) tags along." }, { stepNumber: 4, description: "Substitute \\(\\alpha \\approx 0.7549\\).", workingLatex: "g'(\\alpha) = -\\displaystyle\\frac{1}{2}(0.7549 + 1)^{-3/2} = -\\displaystyle\\frac{1}{2}(1.7549)^{-3/2}", explanation: "\\(\\alpha + 1 \\approx 1.7549\\); plug in and simplify the bracket." }, { stepNumber: 5, description: "Decompose \\((1.7549)^{3/2}\\).", workingLatex: "(1.7549)^{3/2} = 1.7549 \\cdot \\sqrt{1.7549}", explanation: "Use \\(x^{3/2} = x \\cdot x^{1/2} = x \\sqrt{x}\\) to avoid a calculator power button." }, { stepNumber: 6, description: "Compute \\(\\sqrt{1.7549}\\).", workingLatex: "\\sqrt{1.7549} \\approx 1.3247", explanation: "Check: \\(1.3247^{2} = 1.75483\\ldots\\), close to \\(1.7549\\)." }, { stepNumber: 7, description: "Multiply to get \\((1.7549)^{3/2}\\).", workingLatex: "(1.7549)^{3/2} \\approx 1.7549 \\cdot 1.3247 \\approx 2.3248", explanation: "Long multiplication: \\(1.7549 \\cdot 1.3247\\). Carry 4 d.p. throughout for accuracy." }, { stepNumber: 8, description: "Take the reciprocal.", workingLatex: "(1.7549)^{-3/2} = \\displaystyle\\frac{1}{2.3248} \\approx 0.4302", explanation: "\\(\\tfrac{1}{2.3248}\\). Long division gives \\(0.43014\\ldots\\)." }, { stepNumber: 9, description: "Halve and attach the minus sign.", workingLatex: "g'(\\alpha) = -\\displaystyle\\frac{1}{2} \\cdot 0.4302 \\approx -0.215", explanation: "Half of \\(0.4302\\) is \\(0.2151\\), so \\(g'(\\alpha) \\approx -0.215\\) to 3 d.p." }, { stepNumber: 10, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 0.215 < 1", explanation: "Strict inequality holds, so the iteration converges to \\(\\alpha\\) from any sufficiently close start." }, { stepNumber: 11, description: "Classify the convergence pattern.", workingLatex: "g'(\\alpha) < 0 \\;\\Rightarrow\\; \\text{cobweb (alternating sides)}", explanation: "Negative derivative makes \\(g\\) decreasing near \\(\\alpha\\), so iterates jump to opposite sides each step — the cobweb pattern. This is exactly what we observed in Q46: \\(1.0000 \\to 0.7071 \\to 0.7654\\) bracketing \\(\\alpha\\)." }, { stepNumber: 12, description: "Predict the convergence rate.", workingLatex: "|x_{n+1} - \\alpha| \\approx 0.215\\,|x_{n} - \\alpha|", explanation: "Each step shrinks the error by roughly a factor of \\(0.215\\) — fairly fast. After 4 iterates the error has shrunk by \\(0.215^{4} \\approx 0.0021\\), so two extra decimal places per four steps." } ], finalAnswer: "\\(g'(\\alpha) \\approx -0.215\\); \\(|g'(\\alpha)| < 1\\) so convergence (cobweb pattern)." } },
  { id: "y2nm2-048", topicRef: "y2nm2", topicTitle: "Iteration 48", difficulty: "Standard", questionText: "The iteration \\(x_{n+1} = \\tfrac{4x_{n} - 1}{x_{n}^{2}}\\) has a fixed point \\(\\alpha > 0\\). Find the equation satisfied by \\(\\alpha\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = g(\\alpha) \\;\\longrightarrow\\; \\text{clear the denominator} \\;\\longrightarrow\\; \\text{cubic in }\\alpha", explanation: "We substitute \\(\\alpha\\) into both sides of the recurrence, multiply by \\(\\alpha^{2}\\) to clear the fraction, rearrange to standard cubic form, and finally locate the roots numerically to identify the positive fixed points." }, { stepNumber: 2, description: "Write down the fixed-point relation.", workingLatex: "\\alpha = g(\\alpha) = \\displaystyle\\frac{4\\alpha - 1}{\\alpha^{2}}", explanation: "A fixed point of \\(x_{n+1} = g(x_{n})\\) satisfies \\(\\alpha = g(\\alpha)\\). Substitute \\(x = \\alpha\\) on both sides." }, { stepNumber: 3, description: "Multiply both sides by \\(\\alpha^{2}\\).", workingLatex: "\\alpha \\cdot \\alpha^{2} = 4\\alpha - 1 \\;\\Longrightarrow\\; \\alpha^{3} = 4\\alpha - 1", explanation: "\\(\\alpha^{2}\\) is the denominator; multiplying clears it. This step requires \\(\\alpha \\neq 0\\) — the iteration formula is undefined at 0, so 0 cannot be a fixed point." }, { stepNumber: 4, description: "Bring all terms to one side.", workingLatex: "\\alpha^{3} - 4\\alpha + 1 = 0", explanation: "Subtract \\(4\\alpha - 1\\) from both sides. Standard cubic form." }, { stepNumber: 5, description: "Reflect: how many roots?", workingLatex: "\\text{cubic} \\Rightarrow \\text{either 1 or 3 real roots}", explanation: "A general cubic has 1 or 3 real roots. The discriminant of \\(\\alpha^{3} + p\\alpha + q = 0\\) is \\(\\Delta = -4p^{3} - 27q^{2}\\)." }, { stepNumber: 6, description: "Compute the discriminant.", workingLatex: "p = -4,\\ q = 1 \\;\\Rightarrow\\; \\Delta = -4(-4)^{3} - 27(1)^{2} = 256 - 27 = 229 > 0", explanation: "Positive discriminant means three distinct real roots." }, { stepNumber: 7, description: "Locate by sign changes.", workingLatex: "f(0) = 1,\\ f(1) = -2,\\ f(2) = 1,\\ f(-3) = -14", explanation: "Sign changes between \\(0 \\to 1\\) (root in \\((0, 1)\\)), \\(1 \\to 2\\) (root in \\((1, 2)\\)), and \\(-3 \\to 0\\) somewhere negative." }, { stepNumber: 8, description: "Approximate each root numerically.", workingLatex: "\\alpha_{1} \\approx 0.2541,\\ \\alpha_{2} \\approx 1.8608,\\ \\alpha_{3} \\approx -2.1149", explanation: "Three distinct real roots. The two positive roots \\(\\alpha_{1}, \\alpha_{2}\\) are candidate fixed points of the iteration; the negative root \\(\\alpha_{3}\\) is too." }, { stepNumber: 9, description: "Record the polynomial.", workingLatex: "\\boxed{\\alpha^{3} - 4\\alpha + 1 = 0}", explanation: "This is the equation satisfied by every fixed point of the iteration — the question's required answer." } ], finalAnswer: "\\(\\alpha^{3} - 4\\alpha + 1 = 0\\)." } },
  { id: "y2nm2-049", topicRef: "y2nm2", topicTitle: "Iteration 49", difficulty: "Standard", questionText: "Starting from \\(x_{0} = 2\\), use \\(x_{n+1} = \\tfrac{4x_{n} - 1}{x_{n}^{2}}\\) to find a root of \\(x^{3} - 4x + 1 = 0\\) to 3 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = \\displaystyle\\frac{4x - 1}{x^{2}};\\ \\alpha \\approx 1.861\\ \\text{(from Q48)}", explanation: "We iterate from \\(x_{0} = 2\\) and watch a slow cobweb oscillation around \\(\\alpha \\approx 1.861\\). We then evaluate \\(|g'(\\alpha)|\\) to explain the slow rate, and trust the iterates' convergence by following several iterations to confirm 3 d.p. stability." }, { stepNumber: 2, description: "Write down the iteration.", workingLatex: "x_{n+1} = \\displaystyle\\frac{4x_{n} - 1}{x_{n}^{2}},\\quad x_{0} = 2", explanation: "From Q48 the fixed points satisfy \\(\\alpha^{3} - 4\\alpha + 1 = 0\\); the relevant positive root near 2 is \\(\\alpha \\approx 1.8608\\)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{4 \\cdot 2 - 1}{2^{2}} = \\displaystyle\\frac{7}{4} = 1.7500", explanation: "Substitute \\(x_{0} = 2\\); exact value." }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{4 \\cdot 1.75 - 1}{1.75^{2}} = \\displaystyle\\frac{6}{3.0625} \\approx 1.9592", explanation: "Numerator: \\(7 - 1 = 6\\). Denominator: \\(1.75^{2} = 3.0625\\)." }, { stepNumber: 5, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{4 \\cdot 1.9592 - 1}{1.9592^{2}} = \\displaystyle\\frac{6.8368}{3.8385} \\approx 1.7811", explanation: "Already a cobweb is forming: \\(1.75 \\to 1.96 \\to 1.78\\) — bouncing across \\(\\alpha \\approx 1.86\\)." }, { stepNumber: 6, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\displaystyle\\frac{4 \\cdot 1.7811 - 1}{1.7811^{2}} = \\displaystyle\\frac{6.1244}{3.1723} \\approx 1.9306", explanation: "Iterates straddle \\(\\alpha\\) and inch closer — but the amplitude shrinks slowly." }, { stepNumber: 7, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{4x - 1}{x^{2}} = \\displaystyle\\frac{4}{x} - \\displaystyle\\frac{1}{x^{2}} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{4}{x^{2}} + \\displaystyle\\frac{2}{x^{3}}", explanation: "Split into negative powers before differentiating." }, { stepNumber: 8, description: "Evaluate \\(g'(\\alpha)\\) at \\(\\alpha = 1.861\\).", workingLatex: "g'(1.861) = -\\displaystyle\\frac{4}{3.463} + \\displaystyle\\frac{2}{6.444} \\approx -1.155 + 0.310 \\approx -0.844", explanation: "\\(|g'(\\alpha)| \\approx 0.84 < 1\\), so convergent — but barely. Each step shrinks the error by only \\(\\sim 16\\%\\), so many iterates are needed." }, { stepNumber: 9, description: "Continue iterating.", workingLatex: "x_{5} \\approx 1.8036,\\ x_{6} \\approx 1.9103,\\ x_{7} \\approx 1.8199,\\ x_{8} \\approx 1.8961", explanation: "Average of two consecutive iterates is already very close to \\(\\alpha\\): \\((1.8199 + 1.8961)/2 \\approx 1.858\\)." }, { stepNumber: 10, description: "More iterates.", workingLatex: "x_{9} \\approx 1.8315,\\ x_{10} \\approx 1.8842,\\ x_{11} \\approx 1.8409,\\ x_{12} \\approx 1.8754", explanation: "Amplitude has shrunk to about \\(\\pm 0.018\\) about \\(1.86\\). Approaching 3 d.p. stability." }, { stepNumber: 11, description: "Eventual 3 d.p. value.", workingLatex: "x_{n} \\to 1.861\\ \\text{(to 3 d.p.)}", explanation: "After roughly 25–30 iterations, both odd- and even-indexed subsequences settle to \\(1.861\\) at 3 d.p." }, { stepNumber: 12, description: "Sanity-check.", workingLatex: "1.861^{3} - 4 \\cdot 1.861 + 1 \\approx 6.448 - 7.444 + 1 = 0.004 \\approx 0", explanation: "Substituting \\(\\alpha = 1.861\\) into the cubic gives essentially zero — root confirmed to 3 d.p." } ], finalAnswer: "Root \\(\\approx 1.861\\) (after more iterations)." } },
  { id: "y2nm2-050", topicRef: "y2nm2", topicTitle: "Iteration 50", difficulty: "Standard", questionText: "Use the iteration \\(x_{n+1} = \\sqrt[5]{3x_{n} + 2}\\) with \\(x_{0} = 1\\) and find \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = (3x + 2)^{1/5};\\quad \\text{iterate, then verify convergence}", explanation: "We iterate three times from \\(x_{0} = 1\\), watching a steady monotone climb. Then we derive the fixed-point equation, compute \\(g'(\\alpha)\\), and confirm \\(|g'(\\alpha)| < 1\\) (very small, since taking a fifth root flattens slopes dramatically)." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = \\sqrt[5]{3x_{n} + 2},\\quad x_{0} = 1", explanation: "Compute \\(3 \\cdot \\text{previous} + 2\\), then take the fifth root (a single \\(\\hat{}\\,0.2\\) on a calculator)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) — set-up.", workingLatex: "x_{1} = \\sqrt[5]{3 \\cdot 1 + 2} = \\sqrt[5]{5}", explanation: "Substitute \\(x_{0} = 1\\)." }, { stepNumber: 4, description: "Evaluate \\(\\sqrt[5]{5}\\).", workingLatex: "\\sqrt[5]{5} = 5^{0.2} \\approx 1.3797", explanation: "Check: \\(1.3797^{5} \\approx 4.998\\), close to \\(5\\). So \\(x_{1} \\approx 1.3797\\) to 4 d.p." }, { stepNumber: 5, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\sqrt[5]{3 \\cdot 1.3797 + 2} = \\sqrt[5]{4.1391 + 2} = \\sqrt[5]{6.1391}", explanation: "Multiply: \\(3 \\cdot 1.3797 = 4.1391\\). Add 2: \\(6.1391\\)." }, { stepNumber: 6, description: "Evaluate \\(\\sqrt[5]{6.1391}\\).", workingLatex: "x_{2} = 6.1391^{0.2} \\approx 1.4375", explanation: "Check: \\(1.4375^{5} \\approx 6.139\\). Round to \\(1.4375\\)." }, { stepNumber: 7, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\sqrt[5]{3 \\cdot 1.4375 + 2} = \\sqrt[5]{4.3125 + 2} = \\sqrt[5]{6.3125}", explanation: "" }, { stepNumber: 8, description: "Evaluate \\(\\sqrt[5]{6.3125}\\).", workingLatex: "x_{3} \\approx 1.4456", explanation: "\\(1.4456^{5} \\approx 6.313\\). Round to \\(1.4456\\)." }, { stepNumber: 9, description: "Observe the trend.", workingLatex: "1.0000 \\to 1.3797 \\to 1.4375 \\to 1.4456 \\to \\cdots", explanation: "Successive differences: \\(0.380, 0.058, 0.008\\) — shrinking by about a factor of \\(7\\) each step. Monotone (staircase) convergence." }, { stepNumber: 10, description: "Find the fixed-point equation.", workingLatex: "\\alpha = \\sqrt[5]{3\\alpha + 2} \\;\\Longrightarrow\\; \\alpha^{5} = 3\\alpha + 2 \\;\\Longrightarrow\\; \\alpha^{5} - 3\\alpha - 2 = 0", explanation: "Raising both sides to the 5th power is reversible for positive values. \\(\\alpha \\approx 1.4469\\) numerically." }, { stepNumber: 11, description: "Compute \\(g'(\\alpha)\\).", workingLatex: "g'(x) = \\displaystyle\\frac{3}{5}(3x + 2)^{-4/5} \\;\\Rightarrow\\; g'(1.4469) \\approx \\displaystyle\\frac{3}{5}(6.3407)^{-4/5} \\approx 0.143", explanation: "Chain rule: bring down \\(\\tfrac{1}{5}\\), reduce exponent to \\(-\\tfrac{4}{5}\\), multiply by inner derivative \\(3\\). At \\(\\alpha\\), \\((6.3407)^{4/5} \\approx 4.190\\); reciprocal is \\(0.239\\); times \\(\\tfrac{3}{5}\\) gives \\(\\approx 0.143\\)." }, { stepNumber: 12, description: "Confirm convergence pattern.", workingLatex: "|g'(\\alpha)| \\approx 0.143 < 1\\ \\text{and}\\ g'(\\alpha) > 0 \\;\\Rightarrow\\; \\text{staircase}", explanation: "Each step shrinks the error by \\(\\sim 14\\%\\), matching the observed \\(\\sim 1/7\\) shrinkage. Iterates approach \\(\\alpha\\) monotonically from below — exactly the staircase pattern we saw." } ], finalAnswer: "\\(x_{1} \\approx 1.3797,\\ x_{2} \\approx 1.4375,\\ x_{3} \\approx 1.4456\\)." } },
  { id: "y2nm2-051", topicRef: "y2nm2", topicTitle: "Iteration 51", difficulty: "Standard", questionText: "Use \\(x_{n+1} = \\ln(5x_{n})\\) with \\(x_{0} = 2\\) and compute \\(x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration", "log"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = \\ln(5x);\\quad \\text{iterate three times, then check convergence}", explanation: "We iterate from \\(x_{0} = 2\\) carrying 4 d.p. at every stage, deriving the fixed-point equation \\(e^{\\alpha} = 5\\alpha\\), and verifying \\(|g'(\\alpha)| < 1\\). The slow convergence rate is explained by \\(g'(\\alpha) = 1/\\alpha\\), which is barely below 1." }, { stepNumber: 2, description: "Use log-multiplication identity.", workingLatex: "\\ln(5x) = \\ln 5 + \\ln x", explanation: "Splitting helps both intuition and arithmetic. \\(\\ln 5 \\approx 1.6094\\) is a constant added every step." }, { stepNumber: 3, description: "Compute \\(x_{1}\\) — set-up.", workingLatex: "x_{1} = \\ln(5 \\cdot 2) = \\ln 10", explanation: "Substitute \\(x_{0} = 2\\). \\(5 \\cdot 2 = 10\\) exactly." }, { stepNumber: 4, description: "Evaluate \\(\\ln 10\\).", workingLatex: "x_{1} = \\ln 10 \\approx 2.3026", explanation: "Standard value: \\(\\ln 10 = 2.30258509\\ldots\\)" }, { stepNumber: 5, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\ln(5 \\cdot 2.3026) = \\ln 11.5130", explanation: "Multiply: \\(5 \\cdot 2.3026 = 11.5130\\) exactly." }, { stepNumber: 6, description: "Evaluate \\(\\ln 11.5130\\).", workingLatex: "x_{2} \\approx 2.4435", explanation: "Use \\(\\ln 11.5130 = \\ln 10 + \\ln 1.1513 \\approx 2.3026 + 0.1409 \\approx 2.4435\\). Check: \\(e^{2.4435} \\approx 11.514\\)." }, { stepNumber: 7, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\ln(5 \\cdot 2.4435) = \\ln 12.2175", explanation: "Multiply: \\(5 \\cdot 2.4435 = 12.2175\\) (a touch over the version using exact \\(\\ln 10\\), but well within 4 d.p.)." }, { stepNumber: 8, description: "Evaluate \\(\\ln 12.2175\\).", workingLatex: "x_{3} \\approx 2.5029", explanation: "\\(\\ln 12.2175 = \\ln 10 + \\ln 1.22175 \\approx 2.3026 + 0.2003 \\approx 2.5029\\). Check: \\(e^{2.5029} \\approx 12.220\\)." }, { stepNumber: 9, description: "Observe slow growth.", workingLatex: "2.0000 \\to 2.3026 \\to 2.4435 \\to 2.5029 \\to \\cdots", explanation: "Successive differences: \\(0.30, 0.14, 0.06\\) — shrinking by roughly a factor of \\(2\\) per step. Slower than the iterations of Q43 or Q44." }, { stepNumber: 10, description: "Derive the fixed-point equation.", workingLatex: "\\alpha = \\ln(5\\alpha) \\;\\Longrightarrow\\; e^{\\alpha} = 5\\alpha", explanation: "Exponentiate both sides. Transcendental, no closed form." }, { stepNumber: 11, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\ln 5 + \\ln x \\;\\Rightarrow\\; g'(x) = \\displaystyle\\frac{1}{x}", explanation: "Constant differentiates to zero; \\(\\ln x\\) differentiates to \\(\\tfrac{1}{x}\\)." }, { stepNumber: 12, description: "Evaluate \\(g'(\\alpha)\\) at \\(\\alpha \\approx 2.5426\\).", workingLatex: "g'(2.5426) = \\displaystyle\\frac{1}{2.5426} \\approx 0.393", explanation: "\\(|g'(\\alpha)| \\approx 0.39 < 1\\) (and positive), so convergence is guaranteed — monotone staircase — but rate is only \\(\\sim 40\\%\\) per step. Matches the observed shrinkage." } ], finalAnswer: "\\(x_{3} \\approx 2.5029\\)." } },
  { id: "y2nm2-052", topicRef: "y2nm2", topicTitle: "Iteration 52", difficulty: "Standard", questionText: "Two students wish to solve \\(x^{3} + x - 3 = 0\\). One uses \\(x_{n+1} = 3 - x_{n}^{3}\\); the other uses \\(x_{n+1} = \\sqrt[3]{3 - x_{n}}\\). Explain, using the condition on \\(g'\\), which is more likely to converge near the root \\(\\alpha \\approx 1.21\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence", "comparison"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{For each rearrangement compute }g'(\\alpha);\\ \\text{compare }|g'(\\alpha)|\\text{ to }1", explanation: "Both rearrangements give \\(\\alpha\\) as a fixed point (both reduce algebraically to \\(x^{3} + x - 3 = 0\\)). The convergence criterion \\(|g'(\\alpha)| < 1\\) discriminates between them: smaller \\(|g'(\\alpha)|\\) means faster convergence; \\(|g'(\\alpha)| > 1\\) means divergence." }, { stepNumber: 2, description: "State the convergence criterion.", workingLatex: "|g'(\\alpha)| < 1 \\;\\Longrightarrow\\; \\text{convergence near }\\alpha", explanation: "Strict inequality. If \\(|g'(\\alpha)| > 1\\), the iteration is locally repelling and will fly away from \\(\\alpha\\)." }, { stepNumber: 3, description: "Identify \\(g_{1}\\) and \\(g_{2}\\).", workingLatex: "g_{1}(x) = 3 - x^{3};\\quad g_{2}(x) = \\sqrt[3]{3 - x} = (3 - x)^{1/3}", explanation: "Both equal \\(\\alpha\\) at the root, since rearranging \\(x^{3} + x - 3 = 0\\) one way gives \\(x = 3 - x^{3}\\) and another way gives \\(x = \\sqrt[3]{3 - x}\\)." }, { stepNumber: 4, description: "Differentiate \\(g_{1}\\).", workingLatex: "g_{1}'(x) = -3x^{2}", explanation: "Power rule on \\(-x^{3}\\)." }, { stepNumber: 5, description: "Evaluate \\(g_{1}'(1.21)\\).", workingLatex: "g_{1}'(1.21) = -3 \\cdot (1.21)^{2} = -3 \\cdot 1.4641 = -4.3923", explanation: "Compute \\(1.21^{2} = 1.4641\\), then multiply by \\(-3\\)." }, { stepNumber: 6, description: "Check the criterion for \\(g_{1}\\).", workingLatex: "|g_{1}'(1.21)| \\approx 4.39 \\;\\gg\\; 1", explanation: "Magnitude is more than four times the convergence threshold. The first student's iteration diverges sharply." }, { stepNumber: 7, description: "Differentiate \\(g_{2}\\).", workingLatex: "g_{2}(x) = (3 - x)^{1/3} \\;\\Rightarrow\\; g_{2}'(x) = \\displaystyle\\frac{1}{3}(3 - x)^{-2/3} \\cdot (-1) = -\\displaystyle\\frac{1}{3}(3 - x)^{-2/3}", explanation: "Chain rule: power \\(\\tfrac{1}{3}\\) comes down, exponent drops to \\(-\\tfrac{2}{3}\\), and the inner derivative \\(\\tfrac{d}{dx}(3 - x) = -1\\) introduces the minus sign." }, { stepNumber: 8, description: "Set up \\(g_{2}'(1.21)\\).", workingLatex: "g_{2}'(1.21) = -\\displaystyle\\frac{1}{3}(1.79)^{-2/3}", explanation: "\\(3 - 1.21 = 1.79\\)." }, { stepNumber: 9, description: "Compute \\((1.79)^{2/3}\\).", workingLatex: "(1.79)^{2/3} = \\sqrt[3]{1.79^{2}} = \\sqrt[3]{3.2041} \\approx 1.474", explanation: "Square first, then take the cube root. Check: \\(1.474^{3} \\approx 3.202\\), close to \\(3.2041\\)." }, { stepNumber: 10, description: "Take the reciprocal and apply \\(-\\tfrac{1}{3}\\).", workingLatex: "g_{2}'(1.21) = -\\displaystyle\\frac{1}{3} \\cdot \\displaystyle\\frac{1}{1.474} \\approx -\\displaystyle\\frac{1}{3} \\cdot 0.6784 \\approx -0.226", explanation: "\\(\\tfrac{1}{1.474} \\approx 0.6784\\). Divide by 3 and attach the minus sign." }, { stepNumber: 11, description: "Check the criterion for \\(g_{2}\\).", workingLatex: "|g_{2}'(1.21)| \\approx 0.226 < 1", explanation: "Comfortably below 1. The second student's iteration converges, in a cobweb pattern (since \\(g_{2}'(\\alpha) < 0\\))." }, { stepNumber: 12, description: "Conclude.", workingLatex: "g_{1}:\\ |g'| \\approx 4.39\\ \\text{(diverges)};\\quad g_{2}:\\ |g'| \\approx 0.226\\ \\text{(converges)}", explanation: "The cube-root rearrangement \\(g_{2}\\) is the only viable scheme. The lesson: rearranging the same equation differently can give wildly different numerical behaviour — always check \\(|g'(\\alpha)|\\) before iterating." } ], finalAnswer: "Second student's iteration converges (\\(|g'(\\alpha)| \\approx 0.226 < 1\\))." } },
  { id: "y2nm2-053", topicRef: "y2nm2", topicTitle: "Iteration 53", difficulty: "Standard", questionText: "The iteration \\(x_{n+1} = g(x_{n})\\) with \\(g(x) = \\tfrac{2x + 3}{x^{2}}\\) has a fixed point \\(\\alpha > 0\\). Find the polynomial equation satisfied by \\(\\alpha\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["fixed point"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = g(\\alpha) \\;\\longrightarrow\\; \\text{clear }\\alpha^{2}\\;\\longrightarrow\\;\\text{cubic in }\\alpha", explanation: "We substitute \\(\\alpha\\) into both sides of \\(x = g(x)\\), multiply through by \\(\\alpha^{2}\\) to clear the fraction, rearrange to standard cubic form, and then check by sign analysis that the unique real root is positive." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = g(\\alpha) = \\displaystyle\\frac{2\\alpha + 3}{\\alpha^{2}}", explanation: "A fixed point of \\(x_{n+1} = g(x_{n})\\) satisfies \\(\\alpha = g(\\alpha)\\). Substitute \\(x = \\alpha\\) on both sides." }, { stepNumber: 3, description: "Multiply both sides by \\(\\alpha^{2}\\).", workingLatex: "\\alpha \\cdot \\alpha^{2} = 2\\alpha + 3 \\;\\Longrightarrow\\; \\alpha^{3} = 2\\alpha + 3", explanation: "Valid because \\(\\alpha \\neq 0\\) (the formula is undefined at 0, so 0 cannot be a fixed point)." }, { stepNumber: 4, description: "Rearrange to standard polynomial form.", workingLatex: "\\alpha^{3} - 2\\alpha - 3 = 0", explanation: "Move all terms to one side. This is the equation every fixed point satisfies." }, { stepNumber: 5, description: "Apply the rational root theorem.", workingLatex: "\\text{candidates: }\\pm 1, \\pm 3", explanation: "Any rational root \\(p/q\\) must have \\(p \\mid 3\\) and \\(q \\mid 1\\). Test \\(\\alpha = 1: 1 - 2 - 3 = -4 \\neq 0\\). Test \\(\\alpha = -1: -1 + 2 - 3 = -2 \\neq 0\\). Test \\(\\alpha = 3: 27 - 6 - 3 = 18 \\neq 0\\). No rational roots — root is irrational." }, { stepNumber: 6, description: "Compute the discriminant.", workingLatex: "p = -2,\\ q = -3:\\ \\Delta = -4p^{3} - 27q^{2} = -4 \\cdot (-8) - 27 \\cdot 9 = 32 - 243 = -211 < 0", explanation: "Negative discriminant of a depressed cubic means exactly one real root (and two complex conjugates)." }, { stepNumber: 7, description: "Locate the real root by sign change.", workingLatex: "f(1) = -4,\\ f(2) = 1 \\;\\Rightarrow\\; \\text{root in }(1, 2)", explanation: "Sign change between \\(1\\) and \\(2\\). \\(f\\) is continuous so by the IVT there is a root in this interval." }, { stepNumber: 8, description: "Refine.", workingLatex: "f(1.89) \\approx -0.029,\\ f(1.90) \\approx 0.059", explanation: "Bisection or trial: the root lies near \\(1.89\\). Numerical solution: \\(\\alpha \\approx 1.8933\\)." }, { stepNumber: 9, description: "Record the answer.", workingLatex: "\\boxed{\\alpha^{3} - 2\\alpha - 3 = 0}", explanation: "This is the polynomial equation satisfied by the (unique) positive fixed point. Numerically \\(\\alpha \\approx 1.8933\\)." } ], finalAnswer: "\\(\\alpha^{3} - 2\\alpha - 3 = 0\\)." } },
  { id: "y2nm2-054", topicRef: "y2nm2", topicTitle: "Iteration 54", difficulty: "Standard", questionText: "Starting from \\(x_{0} = 2\\), apply \\(x_{n+1} = \\tfrac{2x_{n} + 3}{x_{n}^{2}}\\) three times. Compute \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = \\displaystyle\\frac{2x + 3}{x^{2}};\\quad x_{0} = 2,\\ \\alpha \\approx 1.89\\ \\text{from Q53}", explanation: "We iterate three times, watch the amplitude \\emph{grow} (suggesting divergence), then compute \\(g'(\\alpha)\\) and confirm \\(|g'(\\alpha)| > 1\\) — explaining the observed behaviour." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = \\displaystyle\\frac{2x_{n} + 3}{x_{n}^{2}},\\quad x_{0} = 2", explanation: "Each step: double the previous iterate, add 3, divide by its square." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{2 \\cdot 2 + 3}{2^{2}} = \\displaystyle\\frac{7}{4} = 1.7500", explanation: "Numerator: \\(4 + 3 = 7\\). Denominator: \\(4\\). Exact." }, { stepNumber: 4, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{2 \\cdot 1.75 + 3}{1.75^{2}} = \\displaystyle\\frac{3.5 + 3}{3.0625} = \\displaystyle\\frac{6.5}{3.0625}", explanation: "Carry full precision: \\(1.75^{2} = 3.0625\\) exact." }, { stepNumber: 5, description: "Evaluate \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{6.5}{3.0625} \\approx 2.1224", explanation: "Long division: \\(\\tfrac{6.5}{3.0625} = 2.12244\\ldots\\), round to \\(2.1224\\)." }, { stepNumber: 6, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\displaystyle\\frac{2 \\cdot 2.1224 + 3}{2.1224^{2}} = \\displaystyle\\frac{7.2449}{4.5046}", explanation: "Numerator: \\(2 \\cdot 2.1224 + 3 = 4.2449 + 3 = 7.2449\\). Denominator: \\(2.1224^{2} \\approx 4.5046\\)." }, { stepNumber: 7, description: "Evaluate \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{7.2449}{4.5046} \\approx 1.6083", explanation: "Long division: \\(\\approx 1.6083\\). Round to 4 d.p." }, { stepNumber: 8, description: "Tabulate to spot the trend.", workingLatex: "2.0000 \\to 1.7500 \\to 2.1224 \\to 1.6083", explanation: "Successive differences (about \\(\\alpha \\approx 1.89\\)): \\(|2 - 1.89| = 0.11\\), \\(|1.75 - 1.89| = 0.14\\), \\(|2.12 - 1.89| = 0.23\\), \\(|1.61 - 1.89| = 0.28\\). Errors \\emph{growing}." }, { stepNumber: 9, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{2x + 3}{x^{2}} = \\displaystyle\\frac{2}{x} + \\displaystyle\\frac{3}{x^{2}} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{2}{x^{2}} - \\displaystyle\\frac{6}{x^{3}}", explanation: "Split into power form before differentiating." }, { stepNumber: 10, description: "Evaluate \\(g'(\\alpha)\\) at \\(\\alpha \\approx 1.8933\\).", workingLatex: "g'(1.8933) = -\\displaystyle\\frac{2}{3.585} - \\displaystyle\\frac{6}{6.787} \\approx -0.558 - 0.884 \\approx -1.442", explanation: "\\(|g'(\\alpha)| \\approx 1.44 > 1\\) — the fixed point is repelling. Iterates near \\(\\alpha\\) get pushed away with each step." }, { stepNumber: 11, description: "Conclude divergence.", workingLatex: "|g'(\\alpha)| > 1 \\;\\Rightarrow\\; \\text{divergence;}\\ g'(\\alpha) < 0 \\;\\Rightarrow\\; \\text{alternating}", explanation: "Negative \\(g'(\\alpha)\\) means the divergence shows up as growing oscillations (\\emph{divergent cobweb}), exactly the \\(2 \\to 1.75 \\to 2.12 \\to 1.61\\) pattern we computed." }, { stepNumber: 12, description: "Lesson learned.", workingLatex: "\\text{This rearrangement of } x^{3} - 2x - 3 = 0\\text{ is unsuitable}", explanation: "Although the fixed-point equation does have \\(\\alpha \\approx 1.89\\) as a root, this particular rearrangement cannot find it. Q53–Q54 illustrate that the existence of a fixed point is necessary but not sufficient for an iteration to work — \\(|g'(\\alpha)| < 1\\) is the missing condition." } ], finalAnswer: "\\(x_{1} = 1.7500,\\ x_{2} \\approx 2.1224,\\ x_{3} \\approx 1.6083\\). Sequence does not converge from this start." } },
  { id: "y2nm2-055", topicRef: "y2nm2", topicTitle: "Iteration 55", difficulty: "Challenge", questionText: "The iteration \\(x_{n+1} = \\tfrac{a}{x_{n} + b}\\) has a fixed point \\(\\alpha\\). Show that \\(\\alpha = \\tfrac{-b + \\sqrt{b^{2} + 4a}}{2}\\) (positive root), and find the condition on \\(a,\\ b\\) such that \\(|g'(\\alpha)| < 1\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["fixed point", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = g(\\alpha) \\;\\to\\; \\text{quadratic}\\;\\to\\;\\alpha = \\displaystyle\\frac{-b + \\sqrt{b^{2} + 4a}}{2};\\;\\;|g'(\\alpha)| < 1\\;\\to\\;\\text{condition}", explanation: "We derive the quadratic for \\(\\alpha\\) from \\(\\alpha = g(\\alpha)\\), apply the quadratic formula to pick the positive root, then differentiate \\(g\\), use the fixed-point relation to simplify \\(g'(\\alpha)\\) into a tidy form, and finally interpret the inequality in terms of \\(a, b\\)." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{a}{\\alpha + b}", explanation: "Substitute \\(x = \\alpha\\) into both sides." }, { stepNumber: 3, description: "Clear the denominator.", workingLatex: "\\alpha(\\alpha + b) = a", explanation: "Multiply both sides by \\((\\alpha + b)\\); valid because we are assuming the fixed point exists (so \\(\\alpha + b \\neq 0\\))." }, { stepNumber: 4, description: "Expand and bring to standard form.", workingLatex: "\\alpha^{2} + b\\alpha - a = 0", explanation: "Quadratic in \\(\\alpha\\). Discriminant: \\(b^{2} + 4a\\), which is positive when \\(a > 0\\)." }, { stepNumber: 5, description: "Apply the quadratic formula.", workingLatex: "\\alpha = \\displaystyle\\frac{-b \\pm \\sqrt{b^{2} + 4a}}{2}", explanation: "Two roots; we select the one called for in the question." }, { stepNumber: 6, description: "Choose the positive root.", workingLatex: "\\alpha = \\displaystyle\\frac{-b + \\sqrt{b^{2} + 4a}}{2}", explanation: "For \\(a > 0\\), \\(\\sqrt{b^{2} + 4a} > |b|\\), so \\(-b + \\sqrt{b^{2} + 4a} > 0\\) regardless of the sign of \\(b\\). Hence the \\(+\\) sign gives a positive \\(\\alpha\\). Shown." }, { stepNumber: 7, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{a}{x + b} = a(x + b)^{-1} \\;\\Rightarrow\\; g'(x) = -a(x + b)^{-2} = -\\displaystyle\\frac{a}{(x + b)^{2}}", explanation: "Reciprocal rule, written as a negative power for clarity." }, { stepNumber: 8, description: "Use the fixed-point relation.", workingLatex: "\\alpha + b = \\displaystyle\\frac{a}{\\alpha} \\;\\Longrightarrow\\; (\\alpha + b)^{2} = \\displaystyle\\frac{a^{2}}{\\alpha^{2}}", explanation: "Rearranging step 2 gives \\(\\alpha + b = a/\\alpha\\). Squaring both sides gives a compact expression for \\((\\alpha + b)^{2}\\)." }, { stepNumber: 9, description: "Substitute into \\(g'(\\alpha)\\).", workingLatex: "g'(\\alpha) = -\\displaystyle\\frac{a}{(\\alpha + b)^{2}} = -\\displaystyle\\frac{a}{a^{2}/\\alpha^{2}} = -\\displaystyle\\frac{\\alpha^{2}}{a}", explanation: "The substitution collapses \\(g'(\\alpha)\\) to a remarkably clean form: \\(-\\alpha^{2}/a\\)." }, { stepNumber: 10, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| < 1 \\;\\iff\\; \\displaystyle\\frac{\\alpha^{2}}{a} < 1 \\;\\iff\\; \\alpha^{2} < a", explanation: "Take absolute value (the sign is negative) and clear the denominator (\\(a > 0\\))." }, { stepNumber: 11, description: "Rewrite using the quadratic relation.", workingLatex: "\\alpha^{2} + b\\alpha - a = 0 \\;\\Rightarrow\\; \\alpha^{2} = a - b\\alpha", explanation: "From step 4." }, { stepNumber: 12, description: "Translate the criterion to \\(a, b\\).", workingLatex: "\\alpha^{2} < a \\;\\iff\\; a - b\\alpha < a \\;\\iff\\; -b\\alpha < 0 \\;\\iff\\; b\\alpha > 0", explanation: "Subtract \\(a\\) from both sides, then negate. The criterion reduces to \\(b\\alpha > 0\\)." }, { stepNumber: 13, description: "Final simplification.", workingLatex: "a > 0,\\ \\alpha > 0 \\;\\Rightarrow\\; b\\alpha > 0 \\iff b > 0", explanation: "Since \\(\\alpha > 0\\) (positive root) and the criterion is \\(b\\alpha > 0\\), it reduces to \\(b > 0\\). The iteration converges precisely when \\(a > 0\\) and \\(b > 0\\)." } ], finalAnswer: "\\(|g'(\\alpha)| < 1\\) iff \\(\\alpha^{2} < a\\); with \\(a > 0\\) this is equivalent to \\(b > 0\\)." } },
  { id: "y2nm2-056", topicRef: "y2nm2", topicTitle: "Iteration 56", difficulty: "Challenge", questionText: "A sequence defined by \\(x_{n+1} = \\tfrac{1}{3}(x_{n}^{2} + 2)\\) converges to \\(\\alpha = 1\\) if started close enough. Find the interval of starting values \\(x_{0}\\) for which \\(|g'(x_{0})| < 1\\) near \\(\\alpha = 1\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g'(x) = \\displaystyle\\frac{2x}{3};\\ \\text{solve}\\ |g'(x)| < 1\\ \\text{for }x", explanation: "We identify \\(g\\), differentiate to get \\(g'\\), translate the contraction condition \\(|g'(x)| < 1\\) into a linear inequality in \\(x\\), solve, and finally check that \\(\\alpha = 1\\) sits comfortably inside the resulting interval." }, { stepNumber: 2, description: "Identify the iteration function.", workingLatex: "g(x) = \\displaystyle\\frac{1}{3}(x^{2} + 2) = \\displaystyle\\frac{x^{2}}{3} + \\displaystyle\\frac{2}{3}", explanation: "Splitting the \\(\\tfrac{1}{3}\\) makes differentiation transparent." }, { stepNumber: 3, description: "Differentiate.", workingLatex: "g'(x) = \\displaystyle\\frac{2x}{3}", explanation: "Power rule on \\(\\tfrac{x^{2}}{3}\\); the constant \\(\\tfrac{2}{3}\\) drops." }, { stepNumber: 4, description: "Verify \\(\\alpha = 1\\) is a fixed point.", workingLatex: "g(1) = \\displaystyle\\frac{1 + 2}{3} = 1\\ \\checkmark", explanation: "Substituting \\(\\alpha = 1\\) returns \\(1\\), confirming it is a fixed point. (The other root of \\(\\tfrac{1}{3}(x^{2} + 2) = x\\) is \\(x = 2\\) — irrelevant for local convergence to \\(\\alpha = 1\\).)" }, { stepNumber: 5, description: "State the contraction condition.", workingLatex: "|g'(x)| < 1", explanation: "Where \\(|g'(x)| < 1\\), the iteration is locally a contraction; iterates close to \\(x\\) move closer together each step." }, { stepNumber: 6, description: "Translate into a linear inequality.", workingLatex: "\\left|\\displaystyle\\frac{2x}{3}\\right| < 1 \\;\\iff\\; |2x| < 3 \\;\\iff\\; |x| < \\displaystyle\\frac{3}{2}", explanation: "Multiply both sides by \\(3\\) (positive, preserves inequality)." }, { stepNumber: 7, description: "Resolve the absolute value.", workingLatex: "-\\displaystyle\\frac{3}{2} < x < \\displaystyle\\frac{3}{2}", explanation: "\\(|x| < \\tfrac{3}{2}\\) is equivalent to the two-sided inequality." }, { stepNumber: 8, description: "State the interval.", workingLatex: "x \\in \\left(-\\displaystyle\\frac{3}{2},\\ \\displaystyle\\frac{3}{2}\\right) = (-1.5,\\ 1.5)", explanation: "Inside this open interval the iteration is a strict contraction." }, { stepNumber: 9, description: "Verify the fixed point sits inside.", workingLatex: "\\alpha = 1,\\quad -1.5 < 1 < 1.5\\ \\checkmark", explanation: "And at \\(\\alpha = 1\\): \\(g'(1) = \\tfrac{2}{3} \\approx 0.667 < 1\\) — solidly inside the contraction region." }, { stepNumber: 10, description: "Classify the convergence near \\(\\alpha = 1\\).", workingLatex: "g'(1) = \\displaystyle\\frac{2}{3} > 0", explanation: "Positive derivative means the iteration approaches \\(\\alpha = 1\\) monotonically — staircase pattern. Each step shrinks the error by about a factor of \\(\\tfrac{2}{3}\\)." }, { stepNumber: 11, description: "Boundary watch-out.", workingLatex: "x = 1.5 \\Rightarrow g'(1.5) = 1\\ \\text{(neutral)};\\ x > 1.5 \\Rightarrow |g'| > 1\\ \\text{(divergent)}", explanation: "At the endpoints \\(\\pm 1.5\\), the inequality fails — the iteration is no longer locally contracting. Outside the interval iterates diverge from \\(\\alpha = 1\\) (and may instead head to the other fixed point \\(x = 2\\) or to \\(+\\infty\\))." } ], finalAnswer: "\\(-1.5 < x < 1.5\\)." } },
  { id: "y2nm2-057", topicRef: "y2nm2", topicTitle: "Iteration 57", difficulty: "Challenge", questionText: "Apply the iteration \\(x_{n+1} = (x_{n} + \\tfrac{5}{x_{n}^{2}})/2\\) with \\(x_{0} = 1\\). Compute \\(x_{1},\\ x_{2},\\ x_{3}\\) to 4 decimal places and state which root the iteration approximates.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{5}{x^{2}}\\right);\\quad \\text{find }\\alpha,\\ \\text{iterate}", explanation: "We first set \\(\\alpha = g(\\alpha)\\) to identify the target value as \\(\\sqrt[3]{5}\\), then iterate from \\(x_{0} = 1\\) carrying 4 d.p. of working, and finally evaluate \\(g'(\\alpha)\\) to confirm convergence." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = \\displaystyle\\frac{1}{2}\\!\\left(\\alpha + \\displaystyle\\frac{5}{\\alpha^{2}}\\right)", explanation: "Substitute \\(x = \\alpha\\) into the iteration formula." }, { stepNumber: 3, description: "Simplify algebraically.", workingLatex: "2\\alpha = \\alpha + \\displaystyle\\frac{5}{\\alpha^{2}} \\;\\Longrightarrow\\; \\alpha = \\displaystyle\\frac{5}{\\alpha^{2}} \\;\\Longrightarrow\\; \\alpha^{3} = 5", explanation: "Multiply by 2 to clear the half, subtract \\(\\alpha\\), then multiply by \\(\\alpha^{2}\\) to clear the fraction. We get \\(\\alpha^{3} = 5\\)." }, { stepNumber: 4, description: "Solve and identify the target root.", workingLatex: "\\alpha = \\sqrt[3]{5} \\approx 1.7100", explanation: "Numerically: \\(1.71^{3} = 5.000211\\), so \\(\\sqrt[3]{5} \\approx 1.7100\\) to 4 d.p." }, { stepNumber: 5, description: "Compute \\(x_{1}\\) — set-up.", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}\\!\\left(1 + \\displaystyle\\frac{5}{1^{2}}\\right)", explanation: "Substitute \\(x_{0} = 1\\); the reciprocal-squared term is large." }, { stepNumber: 6, description: "Evaluate \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{2}(1 + 5) = 3.0000", explanation: "A huge overshoot to \\(3.0\\) — well above the target \\(1.71\\). The iteration is not yet near the root." }, { stepNumber: 7, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}\\!\\left(3 + \\displaystyle\\frac{5}{3^{2}}\\right) = \\displaystyle\\frac{1}{2}\\!\\left(3 + \\displaystyle\\frac{5}{9}\\right)", explanation: "\\(3^{2} = 9\\); \\(5/9 \\approx 0.5556\\)." }, { stepNumber: 8, description: "Evaluate \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{2}(3 + 0.5556) = \\displaystyle\\frac{1}{2}(3.5556) \\approx 1.7778", explanation: "Big correction — from \\(3\\) down to \\(1.78\\), right next to the target. Iteration has self-corrected." }, { stepNumber: 9, description: "Compute \\(x_{3}\\) — set-up.", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}\\!\\left(1.7778 + \\displaystyle\\frac{5}{1.7778^{2}}\\right)", explanation: "Square: \\(1.7778^{2} \\approx 3.1606\\). Then \\(5/3.1606 \\approx 1.5821\\)." }, { stepNumber: 10, description: "Evaluate \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{1}{2}(1.7778 + 1.5821) = \\displaystyle\\frac{1}{2}(3.3599) \\approx 1.6800", explanation: "Slight undershoot — value drops from \\(1.78\\) to \\(1.68\\), bracketing the target \\(\\alpha \\approx 1.71\\)." }, { stepNumber: 11, description: "Confirm convergence rate.", workingLatex: "g'(x) = \\displaystyle\\frac{1}{2}\\!\\left(1 - \\displaystyle\\frac{10}{x^{3}}\\right) \\;\\Rightarrow\\; g'(\\sqrt[3]{5}) = \\displaystyle\\frac{1}{2}(1 - 2) = -\\displaystyle\\frac{1}{2}", explanation: "At \\(\\alpha = \\sqrt[3]{5}\\), \\(x^{3} = 5\\) so \\(10/x^{3} = 2\\). Derivative is \\(-\\tfrac{1}{2}\\); \\(|g'(\\alpha)| = 0.5 < 1\\) (cobweb pattern — alternating, as we see)." }, { stepNumber: 12, description: "State the target root.", workingLatex: "x_{n} \\to \\sqrt[3]{5} \\approx 1.7100", explanation: "This iteration is the cube-root analogue of the Babylonian scheme, but it lacks the magical \\(g'(\\alpha) = 0\\) property of the square-root version — hence only linear (not quadratic) convergence." } ], finalAnswer: "Approximates \\(\\sqrt[3]{5} \\approx 1.7100\\); \\(x_{1} = 3.0000,\\ x_{2} \\approx 1.7778,\\ x_{3} \\approx 1.6799\\)." } },
  { id: "y2nm2-058", topicRef: "y2nm2", topicTitle: "Iteration 58", difficulty: "Challenge", questionText: "Given the iteration \\(x_{n+1} = g(x_{n})\\) and a fixed point \\(\\alpha\\), show that if \\(g\\) is differentiable and \\(g'(\\alpha) = 0\\) then \\(|x_{n+1} - \\alpha| \\leq C|x_{n} - \\alpha|^{2}\\) for some constant \\(C\\) and for \\(x_{n}\\) close to \\(\\alpha\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Taylor expand }g(x)\\text{ about }\\alpha;\\ \\text{use }g'(\\alpha) = 0;\\ \\text{bound }|g''|", explanation: "We Taylor-expand \\(g\\) to second order about \\(\\alpha\\), use \\(g(\\alpha) = \\alpha\\) and the hypothesis \\(g'(\\alpha) = 0\\) to kill the constant and linear terms, then bound the remainder by the maximum of \\(|g''|\\) over a small neighbourhood — yielding the quadratic-error inequality." }, { stepNumber: 2, description: "State Taylor's theorem.", workingLatex: "g(x) = g(\\alpha) + g'(\\alpha)(x - \\alpha) + \\displaystyle\\frac{1}{2}g''(\\xi)(x - \\alpha)^{2}", explanation: "Second-order Taylor expansion with Lagrange remainder. \\(\\xi\\) lies somewhere strictly between \\(x\\) and \\(\\alpha\\); the equality holds for any twice-differentiable \\(g\\)." }, { stepNumber: 3, description: "Apply fixed-point relation \\(g(\\alpha) = \\alpha\\).", workingLatex: "g(x) = \\alpha + g'(\\alpha)(x - \\alpha) + \\displaystyle\\frac{1}{2}g''(\\xi)(x - \\alpha)^{2}", explanation: "Substitute \\(g(\\alpha) = \\alpha\\). The constant term becomes simply \\(\\alpha\\)." }, { stepNumber: 4, description: "Apply the hypothesis \\(g'(\\alpha) = 0\\).", workingLatex: "g(x) = \\alpha + \\displaystyle\\frac{1}{2}g''(\\xi)(x - \\alpha)^{2}", explanation: "The linear term \\(g'(\\alpha)(x - \\alpha)\\) vanishes — this is the key step. Only the quadratic-order term survives." }, { stepNumber: 5, description: "Subtract \\(\\alpha\\) from both sides.", workingLatex: "g(x) - \\alpha = \\displaystyle\\frac{1}{2}g''(\\xi)(x - \\alpha)^{2}", explanation: "Get the error \\(g(x) - \\alpha\\) on the left." }, { stepNumber: 6, description: "Translate to the iteration setting.", workingLatex: "x_{n+1} - \\alpha = \\displaystyle\\frac{1}{2}g''(\\xi_{n})(x_{n} - \\alpha)^{2}", explanation: "Substitute \\(x = x_{n}\\): then \\(g(x_{n}) = x_{n+1}\\) and \\(\\xi_{n}\\) sits between \\(x_{n}\\) and \\(\\alpha\\) (depending on \\(n\\))." }, { stepNumber: 7, description: "Take absolute values.", workingLatex: "|x_{n+1} - \\alpha| = \\displaystyle\\frac{1}{2}|g''(\\xi_{n})|\\,|x_{n} - \\alpha|^{2}", explanation: "Modulus of a product is product of moduli. Note: \\((x - \\alpha)^{2}\\) is already non-negative, so \\(|(x - \\alpha)^{2}| = (x - \\alpha)^{2} = |x - \\alpha|^{2}\\)." }, { stepNumber: 8, description: "Bound \\(|g''|\\) on a neighbourhood.", workingLatex: "|g''(t)| \\le M\\quad\\text{for all }t\\text{ within }\\delta\\text{ of }\\alpha", explanation: "By continuity of \\(g''\\) on a closed interval around \\(\\alpha\\), it attains a maximum \\(M = \\max_{|t - \\alpha| \\le \\delta} |g''(t)|\\). Provided \\(x_{n}\\) is within \\(\\delta\\) of \\(\\alpha\\), so is \\(\\xi_{n}\\)." }, { stepNumber: 9, description: "Apply the bound.", workingLatex: "|x_{n+1} - \\alpha| \\le \\displaystyle\\frac{M}{2}\\,|x_{n} - \\alpha|^{2}", explanation: "Replace \\(|g''(\\xi_{n})|\\) by its upper bound \\(M\\). The inequality only weakens — \\(\\le\\) is preserved." }, { stepNumber: 10, description: "Define the constant and state the result.", workingLatex: "C = \\displaystyle\\frac{M}{2} \\;\\Rightarrow\\; |x_{n+1} - \\alpha| \\le C\\,|x_{n} - \\alpha|^{2}", explanation: "Shown. The constant \\(C\\) depends only on the local size of \\(g''\\) — not on \\(n\\)." }, { stepNumber: 11, description: "Interpret the result.", workingLatex: "\\epsilon_{n+1} \\le C\\,\\epsilon_{n}^{2}", explanation: "If the current error is \\(\\epsilon_{n} \\sim 10^{-k}\\), the next error is at most \\(\\sim 10^{-2k}\\) (assuming \\(C\\) is moderate). Each step roughly doubles the number of correct digits — quadratic convergence." }, { stepNumber: 12, description: "Compare to linear convergence.", workingLatex: "\\text{linear: }\\epsilon_{n+1} \\sim \\rho\\,\\epsilon_{n}\\ (0 < \\rho < 1);\\quad \\text{quadratic: }\\epsilon_{n+1} \\sim C\\,\\epsilon_{n}^{2}", explanation: "Linear convergence shrinks the error by a constant factor each step — to gain one more decimal, you need a fixed number of iterations. Quadratic convergence \\emph{doubles} the digits, so reaching machine precision takes only \\(\\sim \\log_{2} 50 \\approx 6\\) iterations starting from one correct digit." } ], finalAnswer: "Quadratic convergence holds with \\(C = \\tfrac{1}{2}\\max |g''|\\) near \\(\\alpha\\)." } },
  { id: "y2nm2-059", topicRef: "y2nm2", topicTitle: "Iteration 59", difficulty: "Challenge", questionText: "Consider \\(f(x) = x^{3} - 2x - 2\\). Use any convergent iterative formula, starting from a suitable \\(x_{0}\\), to find the real root to 3 decimal places.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Locate root by sign change};\\ \\text{rearrange to }x = \\sqrt[3]{2x + 2};\\ \\text{verify }|g'(\\alpha)| < 1;\\ \\text{iterate}", explanation: "We bracket the real root via the IVT, choose the cube-root rearrangement (which damps oscillations and gives small \\(g'\\)), verify convergence, iterate from \\(x_{0} = 2\\) to 4 d.p. of working, and stop once consecutive iterates agree to 3 d.p." }, { stepNumber: 2, description: "Locate the root by sign change.", workingLatex: "f(1) = 1 - 2 - 2 = -3,\\quad f(2) = 8 - 4 - 2 = 2", explanation: "\\(f(1) < 0\\) and \\(f(2) > 0\\). By the Intermediate Value Theorem (\\(f\\) is continuous as a polynomial), there is at least one root in \\((1, 2)\\)." }, { stepNumber: 3, description: "Confirm uniqueness in this interval.", workingLatex: "f'(x) = 3x^{2} - 2 > 0\\ \\text{for }x > \\sqrt{2/3} \\approx 0.816", explanation: "\\(f\\) is strictly increasing on \\([1, 2]\\), so the root in \\((1, 2)\\) is unique." }, { stepNumber: 4, description: "Rearrange into fixed-point form.", workingLatex: "x^{3} - 2x - 2 = 0 \\;\\Longrightarrow\\; x^{3} = 2x + 2 \\;\\Longrightarrow\\; x = \\sqrt[3]{2x + 2}", explanation: "Move \\(2x + 2\\) to one side, take real cube root. Cube-root forms typically damp oscillations, so this is a good first choice." }, { stepNumber: 5, description: "State the iteration formula.", workingLatex: "x_{n+1} = \\sqrt[3]{2x_{n} + 2},\\quad x_{0} = 2", explanation: "Start at the upper bound of the bracket; \\(g(2) = \\sqrt[3]{6} \\approx 1.82 < 2\\), so we already move closer to the root." }, { stepNumber: 6, description: "Differentiate and check convergence.", workingLatex: "g(x) = (2x + 2)^{1/3} \\;\\Rightarrow\\; g'(x) = \\displaystyle\\frac{2}{3}(2x + 2)^{-2/3}", explanation: "Chain rule: bring down \\(\\tfrac{1}{3}\\), exponent drops to \\(-\\tfrac{2}{3}\\), times inner derivative \\(2\\)." }, { stepNumber: 7, description: "Evaluate \\(|g'|\\) near the root \\(x \\approx 1.77\\).", workingLatex: "g'(1.77) = \\displaystyle\\frac{2}{3}(5.54)^{-2/3} \\approx \\displaystyle\\frac{2}{3} \\cdot 0.318 \\approx 0.212", explanation: "\\((5.54)^{2/3} = (\\sqrt[3]{5.54})^{2} \\approx 1.768^{2} \\approx 3.126\\); reciprocal is \\(0.320\\); times \\(\\tfrac{2}{3}\\) gives \\(\\approx 0.212\\). \\(|g'| \\approx 0.21 < 1\\) and positive — staircase convergence." }, { stepNumber: 8, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\sqrt[3]{2 \\cdot 2 + 2} = \\sqrt[3]{6} \\approx 1.8171", explanation: "Check: \\(1.8171^{3} \\approx 5.9996\\), close to \\(6\\)." }, { stepNumber: 9, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\sqrt[3]{2 \\cdot 1.8171 + 2} = \\sqrt[3]{5.6342} \\approx 1.7794", explanation: "Change from \\(x_{1}\\) is \\(\\approx 0.038\\) — modest, consistent with rate \\(\\sim 0.21\\) acting on the previous error \\(\\sim 0.18\\)." }, { stepNumber: 10, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\sqrt[3]{2 \\cdot 1.7794 + 2} = \\sqrt[3]{5.5588} \\approx 1.7714", explanation: "Change: \\(\\approx 0.008\\), shrinking by the predicted factor." }, { stepNumber: 11, description: "Compute \\(x_{4}\\) and \\(x_{5}\\).", workingLatex: "x_{4} = \\sqrt[3]{5.5428} \\approx 1.7697,\\quad x_{5} = \\sqrt[3]{5.5394} \\approx 1.7694", explanation: "Both round to \\(1.769\\) at 3 d.p. — stopping criterion satisfied." }, { stepNumber: 12, description: "Sanity-check by substitution.", workingLatex: "1.769^{3} - 2 \\cdot 1.769 - 2 \\approx 5.535 - 3.538 - 2 = -0.003 \\approx 0", explanation: "Substituting \\(\\alpha = 1.769\\) into the original cubic gives essentially zero — root confirmed to 3 d.p." }, { stepNumber: 13, description: "State the root.", workingLatex: "\\alpha \\approx 1.769", explanation: "Iterates have converged at 3 d.p. accuracy with \\(|g'(\\alpha)| \\approx 0.21\\) ensuring monotone (staircase) approach from above. True value: \\(\\alpha = 1.76929\\ldots\\)." } ], finalAnswer: "Root \\(\\approx 1.769\\) to 3 d.p." } },
  { id: "y2nm2-060", topicRef: "y2nm2", topicTitle: "Iteration 60", difficulty: "Challenge", questionText: "For the iteration \\(x_{n+1} = \\cos x_{n}\\), show that there is exactly one fixed point in \\([0, 1]\\) and that convergence from \\(x_{0} = 0\\) is guaranteed.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["fixed point", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Existence: IVT};\\ \\text{uniqueness: monotonicity};\\ \\text{convergence: contraction}", explanation: "We first build an auxiliary function \\(h(x) = \\cos x - x\\) whose zeros are fixed points of \\(\\cos\\), apply IVT for existence and \\(h' < 0\\) for uniqueness on \\([0, 1]\\), then verify \\(|g'(\\alpha)| < 1\\) for local convergence, and finally show the iterates from \\(x_{0} = 0\\) enter the contraction's invariant interval after one step." }, { stepNumber: 2, description: "Define the auxiliary function.", workingLatex: "h(x) = \\cos x - x", explanation: "Fixed points of \\(g(x) = \\cos x\\) are exactly the zeros of \\(h\\): \\(g(\\alpha) = \\alpha \\iff h(\\alpha) = 0\\)." }, { stepNumber: 3, description: "Evaluate \\(h\\) at the endpoints.", workingLatex: "h(0) = \\cos 0 - 0 = 1 > 0,\\quad h(1) = \\cos 1 - 1 \\approx 0.5403 - 1 = -0.4597 < 0", explanation: "Sign change across \\([0, 1]\\). \\(h\\) is continuous (sum of continuous functions)." }, { stepNumber: 4, description: "Apply the IVT.", workingLatex: "h\\ \\text{continuous},\\ h(0)h(1) < 0 \\;\\Rightarrow\\; \\exists\\,\\alpha \\in (0, 1):\\ h(\\alpha) = 0", explanation: "At least one zero exists in \\((0, 1)\\) — existence established." }, { stepNumber: 5, description: "Show \\(h\\) is strictly decreasing.", workingLatex: "h'(x) = -\\sin x - 1 \\le -1 < 0\\ \\text{ for all } x \\in [0, 1]", explanation: "\\(\\sin x \\ge 0\\) on \\([0, 1]\\), so \\(-\\sin x \\le 0\\), so \\(h'(x) = -\\sin x - 1 \\le -1 < 0\\). Strict monotonicity." }, { stepNumber: 6, description: "Deduce uniqueness.", workingLatex: "h\\ \\text{strictly decreasing} \\;\\Rightarrow\\; \\text{at most one zero in }[0, 1]", explanation: "Combined with existence: exactly one. So \\(g(x) = \\cos x\\) has a unique fixed point \\(\\alpha\\) in \\([0, 1]\\)." }, { stepNumber: 7, description: "Locate \\(\\alpha\\) numerically.", workingLatex: "\\alpha \\approx 0.7391", explanation: "Standard value: the unique solution of \\(\\cos x = x\\) (the Dottie number)." }, { stepNumber: 8, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\cos x \\;\\Rightarrow\\; g'(x) = -\\sin x", explanation: "" }, { stepNumber: 9, description: "Verify the contraction criterion at \\(\\alpha\\).", workingLatex: "|g'(\\alpha)| = |\\sin 0.7391| \\approx 0.6736 < 1", explanation: "Strictly less than 1, so the iteration is a local contraction. Negative sign means cobweb (alternating) approach." }, { stepNumber: 10, description: "Track the iterates from \\(x_{0} = 0\\).", workingLatex: "x_{1} = \\cos 0 = 1,\\quad x_{2} = \\cos 1 \\approx 0.5403", explanation: "After one step we are at \\(x_{1} = 1\\); after two steps at \\(x_{2} \\approx 0.54\\) — already inside \\([0, 1]\\)." }, { stepNumber: 11, description: "Identify an invariant interval.", workingLatex: "x \\in [\\cos 1, 1] \\;\\Rightarrow\\; \\cos x \\in [\\cos 1, 1]", explanation: "Since \\(\\cos\\) is decreasing on \\([0, \\pi]\\) and maps \\([0, 1]\\) onto \\([\\cos 1, 1] \\approx [0.54, 1]\\), and \\([0.54, 1] \\subset [0, 1]\\), the interval \\([\\cos 1, 1]\\) is invariant under \\(g\\)." }, { stepNumber: 12, description: "Bound \\(|g'|\\) on the invariant interval.", workingLatex: "|g'(x)| = |\\sin x| \\le \\sin 1 \\approx 0.8415 < 1\\ \\text{ on }[\\cos 1, 1]", explanation: "\\(\\sin\\) is increasing on \\([0, \\pi/2]\\), so on \\([0.54, 1] \\subset [0, \\pi/2]\\) it attains its max at \\(x = 1\\): \\(\\sin 1 \\approx 0.8415\\)." }, { stepNumber: 13, description: "Apply the Banach contraction principle.", workingLatex: "\\text{contraction on }[\\cos 1, 1] \\;\\Rightarrow\\; \\text{unique fixed point, global convergence}", explanation: "On the invariant interval \\([\\cos 1, 1]\\), \\(g\\) is a contraction (\\(|g'| \\le 0.8415\\)). The contraction mapping theorem guarantees a unique fixed point in this set and convergence \\(x_{n} \\to \\alpha\\) from \\emph{any} start in it — including \\(x_{2} \\approx 0.54\\), so the whole iteration converges from \\(x_{0} = 0\\)." } ], finalAnswer: "Unique fixed point \\(\\alpha \\approx 0.7391\\); iteration converges from \\(x_{0} = 0\\)." } },
  { id: "y2nm2-061", topicRef: "y2nm2", topicTitle: "Iteration 61", difficulty: "Challenge", questionText: "A root of \\(e^{-x} = x\\) lies near \\(x = 0.57\\). Use iteration \\(x_{n+1} = e^{-x_{n}}\\) with \\(x_{0} = 0.5\\) and compute \\(x_{1}\\) to \\(x_{5}\\) to 5 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration", "exponential"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = e^{-x};\\quad \\text{iterate 5 times, then explain the cobweb via }g'", explanation: "We iterate from \\(x_{0} = 0.5\\) at 5 d.p. precision, watch the iterates straddle the limit \\(\\alpha\\), then differentiate \\(g\\) and evaluate at \\(\\alpha\\) — discovering the elegant identity \\(g'(\\alpha) = -\\alpha\\) that explains why the convergence is slow (\\(|g'(\\alpha)| \\approx 0.57\\), close to 1)." }, { stepNumber: 2, description: "Write down the recurrence.", workingLatex: "x_{n+1} = e^{-x_{n}},\\quad x_{0} = 0.5", explanation: "Each iterate is the exponential of the negative previous iterate. \\(g\\) is positive and decreasing on \\(\\mathbb{R}\\)." }, { stepNumber: 3, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = e^{-0.5} \\approx 0.60653", explanation: "Standard value: \\(e^{-0.5} = 1/\\sqrt{e} = 0.606530\\ldots\\)" }, { stepNumber: 4, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = e^{-0.60653} \\approx 0.54524", explanation: "Check: \\(\\ln(1/0.54524) \\approx 0.60653\\). Iterate has dropped below the start." }, { stepNumber: 5, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = e^{-0.54524} \\approx 0.57970", explanation: "Back up. Iterates are bracketing the limit \\(\\alpha \\approx 0.567\\)." }, { stepNumber: 6, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = e^{-0.57970} \\approx 0.56006", explanation: "Down again. Successive differences: \\(0.107, 0.061, 0.034, 0.020\\) — shrinking by roughly a factor of \\(0.57\\)." }, { stepNumber: 7, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = e^{-0.56006} \\approx 0.57117", explanation: "And up. Next difference \\(\\approx 0.011\\). The amplitude continues to shrink." }, { stepNumber: 8, description: "Display the pattern.", workingLatex: "0.50000 \\to 0.60653 \\to 0.54524 \\to 0.57970 \\to 0.56006 \\to 0.57117", explanation: "Five iterates produce a clear cobweb — odd-indexed iterates approach \\(\\alpha\\) from above; even-indexed from below. The two subsequences sandwich \\(\\alpha\\)." }, { stepNumber: 9, description: "Differentiate \\(g\\).", workingLatex: "g'(x) = -e^{-x}", explanation: "Chain rule on \\(e^{-x}\\): the inside is \\(-x\\), with derivative \\(-1\\)." }, { stepNumber: 10, description: "Evaluate \\(g'(\\alpha)\\) using the fixed-point relation.", workingLatex: "\\alpha = e^{-\\alpha} \\;\\Rightarrow\\; g'(\\alpha) = -e^{-\\alpha} = -\\alpha", explanation: "Lovely identity: at the fixed point, \\(g'(\\alpha) = -\\alpha\\). Numerically \\(g'(\\alpha) \\approx -0.5671\\)." }, { stepNumber: 11, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 0.567 < 1", explanation: "Just below 1, so convergent — but slowly. Each iteration shrinks the error by about \\(43\\%\\), explaining the modest decay we see." }, { stepNumber: 12, description: "Predict more iterates.", workingLatex: "x_{6} \\approx 0.56488,\\ x_{7} \\approx 0.56843,\\ \\ldots \\to \\alpha \\approx 0.5671", explanation: "After about 20 iterations both subsequences settle to 5 d.p. The true value \\(\\alpha = 0.567143\\ldots\\) (Omega-related)." } ], finalAnswer: "\\(x_{1} \\approx 0.60653,\\ x_{2} \\approx 0.54524,\\ x_{3} \\approx 0.57970,\\ x_{4} \\approx 0.56006,\\ x_{5} \\approx 0.57117\\); approaches \\(\\approx 0.5671\\)." } },
  { id: "y2nm2-062", topicRef: "y2nm2", topicTitle: "Iteration 62", difficulty: "Challenge", questionText: "Show that the iteration \\(x_{n+1} = x_{n} - \\tfrac{f(x_{n})}{f'(x_{n})}\\) (Newton–Raphson) is a fixed-point iteration with \\(g(x) = x - f(x)/f'(x)\\), and verify that \\(g'(\\alpha) = 0\\) for a simple root \\(\\alpha\\) of \\(f\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) = x - \\displaystyle\\frac{f(x)}{f'(x)} \\;\\longrightarrow\\; g(\\alpha) = \\alpha \\;\\longrightarrow\\; g'(\\alpha) = 0", explanation: "We identify the iteration function \\(g\\), verify that simple roots of \\(f\\) are fixed points of \\(g\\), differentiate \\(g\\) via the quotient rule, simplify dramatically, and evaluate at \\(\\alpha\\) where \\(f(\\alpha) = 0\\) makes the whole expression vanish. The conclusion is the famous quadratic convergence of Newton's method." }, { stepNumber: 2, description: "Identify the iteration function.", workingLatex: "x_{n+1} = g(x_{n}),\\quad g(x) = x - \\displaystyle\\frac{f(x)}{f'(x)}", explanation: "Newton–Raphson is literally a fixed-point iteration with this \\(g\\). Each step subtracts \\(f/f'\\) (a Taylor-linear correction) from the current iterate." }, { stepNumber: 3, description: "Check that roots of \\(f\\) are fixed points of \\(g\\).", workingLatex: "f(\\alpha) = 0,\\ f'(\\alpha) \\neq 0 \\;\\Rightarrow\\; g(\\alpha) = \\alpha - \\displaystyle\\frac{0}{f'(\\alpha)} = \\alpha - 0 = \\alpha", explanation: "Substitute \\(\\alpha\\) into \\(g\\). The fraction vanishes because the numerator does, leaving \\(g(\\alpha) = \\alpha\\). So every simple root of \\(f\\) is automatically a fixed point of \\(g\\)." }, { stepNumber: 4, description: "Set up the derivative via the quotient rule.", workingLatex: "g(x) = x - \\displaystyle\\frac{f(x)}{f'(x)} \\;\\Rightarrow\\; g'(x) = 1 - \\displaystyle\\frac{d}{dx}\\!\\left(\\displaystyle\\frac{f(x)}{f'(x)}\\right)", explanation: "Differentiate term by term." }, { stepNumber: 5, description: "Apply the quotient rule to the fraction.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left(\\displaystyle\\frac{f}{f'}\\right) = \\displaystyle\\frac{f' \\cdot f' - f \\cdot f''}{[f']^{2}} = \\displaystyle\\frac{[f']^{2} - f \\cdot f''}{[f']^{2}}", explanation: "Use \\(\\tfrac{d}{dx}(u/v) = (u'v - uv')/v^{2}\\) with \\(u = f\\) (so \\(u' = f'\\)) and \\(v = f'\\) (so \\(v' = f''\\))." }, { stepNumber: 6, description: "Substitute into \\(g'(x)\\).", workingLatex: "g'(x) = 1 - \\displaystyle\\frac{[f'(x)]^{2} - f(x)f''(x)}{[f'(x)]^{2}}", explanation: "Bring the result from step 5 inside step 4." }, { stepNumber: 7, description: "Combine over a common denominator.", workingLatex: "g'(x) = \\displaystyle\\frac{[f'(x)]^{2} - \\left([f'(x)]^{2} - f(x)f''(x)\\right)}{[f'(x)]^{2}}", explanation: "Write the leading \\(1\\) as \\(\\tfrac{[f']^{2}}{[f']^{2}}\\) and combine." }, { stepNumber: 8, description: "Simplify the numerator.", workingLatex: "g'(x) = \\displaystyle\\frac{f(x)\\,f''(x)}{[f'(x)]^{2}}", explanation: "\\([f']^{2}\\) cancels, leaving a remarkably clean expression for \\(g'\\) in terms of \\(f, f', f''\\)." }, { stepNumber: 9, description: "Evaluate at the simple root.", workingLatex: "g'(\\alpha) = \\displaystyle\\frac{f(\\alpha)\\,f''(\\alpha)}{[f'(\\alpha)]^{2}}", explanation: "Plug in \\(x = \\alpha\\)." }, { stepNumber: 10, description: "Use \\(f(\\alpha) = 0\\).", workingLatex: "g'(\\alpha) = \\displaystyle\\frac{0 \\cdot f''(\\alpha)}{[f'(\\alpha)]^{2}} = \\displaystyle\\frac{0}{[f'(\\alpha)]^{2}} = 0", explanation: "The numerator is zero (because \\(f(\\alpha) = 0\\)) and the denominator is non-zero (because \\(\\alpha\\) is a \\emph{simple} root, so \\(f'(\\alpha) \\neq 0\\)). Shown." }, { stepNumber: 11, description: "Connect to Q58.", workingLatex: "g'(\\alpha) = 0 \\;\\Rightarrow\\; |x_{n+1} - \\alpha| \\le C|x_{n} - \\alpha|^{2}", explanation: "From Q58, vanishing first derivative at a fixed point gives quadratic convergence — the error squares each step." }, { stepNumber: 12, description: "Interpret and watch-out.", workingLatex: "f'(\\alpha) = 0 \\;\\Rightarrow\\; \\text{Newton degrades to linear convergence at multiple roots}", explanation: "Common-mistake watch-out: at \\emph{multiple} (repeated) roots, \\(f'(\\alpha) = 0\\) and the quotient-rule simplification breaks. Newton's method still works but convergence drops back to linear (with rate \\(1 - 1/m\\) for an \\(m\\)-fold root). The \\(g'(\\alpha) = 0\\) magic relies crucially on \\(\\alpha\\) being a simple root." } ], finalAnswer: "\\(g'(\\alpha) = 0\\) for simple roots — Newton–Raphson is quadratically convergent." } },
  { id: "y2nm2-063", topicRef: "y2nm2", topicTitle: "Iteration 63", difficulty: "Challenge", questionText: "A sequence satisfies \\(x_{n+1} = x_{n}^{2} - 0.5\\). Find the two fixed points and classify each as attracting or repelling.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["fixed point", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = g(\\alpha) \\;\\to\\; \\text{quadratic}\\;\\to\\;\\text{two roots};\\;\\;|g'(\\alpha)| \\lessgtr 1\\;\\to\\;\\text{classify}", explanation: "We derive the quadratic equation for the fixed points, solve for both roots, then differentiate \\(g(x) = x^{2} - \\tfrac{1}{2}\\) and evaluate at each fixed point to apply the criterion \\(|g'(\\alpha)| < 1\\) (attracting) vs \\(|g'(\\alpha)| > 1\\) (repelling)." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = \\alpha^{2} - 0.5", explanation: "A fixed point of \\(x_{n+1} = g(x_{n})\\) satisfies \\(\\alpha = g(\\alpha)\\). Substitute \\(x = \\alpha\\)." }, { stepNumber: 3, description: "Rearrange to standard form.", workingLatex: "\\alpha^{2} - \\alpha - \\displaystyle\\frac{1}{2} = 0", explanation: "Subtract \\(\\alpha\\) from both sides; write \\(0.5 = \\tfrac{1}{2}\\) for clean fractions." }, { stepNumber: 4, description: "Apply the quadratic formula.", workingLatex: "\\alpha = \\displaystyle\\frac{1 \\pm \\sqrt{1^{2} - 4 \\cdot 1 \\cdot (-\\tfrac{1}{2})}}{2 \\cdot 1} = \\displaystyle\\frac{1 \\pm \\sqrt{1 + 2}}{2} = \\displaystyle\\frac{1 \\pm \\sqrt{3}}{2}", explanation: "Discriminant: \\(1 + 2 = 3 > 0\\), so two distinct real roots." }, { stepNumber: 5, description: "Compute the two roots numerically.", workingLatex: "\\alpha_{1} = \\displaystyle\\frac{1 + \\sqrt{3}}{2} \\approx \\displaystyle\\frac{1 + 1.7321}{2} \\approx 1.3660", explanation: "Positive root. \\(\\sqrt{3} = 1.73205\\ldots\\)" }, { stepNumber: 6, description: "And the second root.", workingLatex: "\\alpha_{2} = \\displaystyle\\frac{1 - \\sqrt{3}}{2} \\approx \\displaystyle\\frac{1 - 1.7321}{2} \\approx -0.3660", explanation: "Negative root, symmetric about \\(x = \\tfrac{1}{2}\\) (the axis of \\(g(x) = x\\) and \\(y = x\\))." }, { stepNumber: 7, description: "Differentiate \\(g\\).", workingLatex: "g(x) = x^{2} - 0.5 \\;\\Rightarrow\\; g'(x) = 2x", explanation: "Standard power rule. \\(g'\\) is linear in \\(x\\)." }, { stepNumber: 8, description: "Evaluate \\(g'(\\alpha_{1})\\).", workingLatex: "g'(\\alpha_{1}) = 2 \\cdot 1.3660 = 2.7320", explanation: "Positive. \\(|g'(\\alpha_{1})| = 2.732 > 1\\)." }, { stepNumber: 9, description: "Classify \\(\\alpha_{1}\\).", workingLatex: "|g'(\\alpha_{1})| > 1 \\;\\Rightarrow\\; \\alpha_{1}\\text{ is repelling}", explanation: "Iterates close to (but not at) \\(\\alpha_{1}\\) move away — the criterion \\(|g'| < 1\\) fails. Numerically: an iterate at \\(\\alpha_{1} + \\epsilon\\) maps to about \\(\\alpha_{1} + 2.73\\,\\epsilon\\), so the error nearly triples each step." }, { stepNumber: 10, description: "Evaluate \\(g'(\\alpha_{2})\\).", workingLatex: "g'(\\alpha_{2}) = 2 \\cdot (-0.3660) = -0.7320", explanation: "Negative. \\(|g'(\\alpha_{2})| = 0.732 < 1\\)." }, { stepNumber: 11, description: "Classify \\(\\alpha_{2}\\).", workingLatex: "|g'(\\alpha_{2})| < 1 \\;\\Rightarrow\\; \\alpha_{2}\\text{ is attracting}", explanation: "Iterates close to \\(\\alpha_{2}\\) are pulled towards it. The negative sign means the approach is via cobweb (alternating sides), and each step shrinks the error by about \\(27\\%\\) (factor \\(\\approx 0.732\\))." }, { stepNumber: 12, description: "Sanity-check via iteration.", workingLatex: "x_{0} = -0.4 \\;\\to\\; x_{1} = -0.34,\\ x_{2} = -0.384,\\ x_{3} = -0.353", explanation: "Iterates near \\(\\alpha_{2} \\approx -0.366\\) bounce in towards it (cobweb), confirming attraction." }, { stepNumber: 13, description: "Summarise.", workingLatex: "\\alpha_{1} = \\displaystyle\\frac{1 + \\sqrt{3}}{2} \\approx 1.366\\ \\text{(repelling)};\\ \\alpha_{2} = \\displaystyle\\frac{1 - \\sqrt{3}}{2} \\approx -0.366\\ \\text{(attracting)}", explanation: "Only \\(\\alpha_{2}\\) can be found by iteration; iterates near \\(\\alpha_{1}\\) drift away to either \\(\\alpha_{2}\\) or to \\(+\\infty\\) (depending on which side and how far)." } ], finalAnswer: "\\(\\alpha_{1} = \\tfrac{1+\\sqrt{3}}{2} \\approx 1.366\\) (repelling); \\(\\alpha_{2} = \\tfrac{1-\\sqrt{3}}{2} \\approx -0.366\\) (attracting)." } },
  { id: "y2nm2-064", topicRef: "y2nm2", topicTitle: "Iteration 64", difficulty: "Challenge", questionText: "Consider \\(x_{n+1} = \\sqrt{5 - x_{n}}\\). Show that the fixed point \\(\\alpha\\) satisfies \\(\\alpha^{2} + \\alpha - 5 = 0\\) and find the value of \\(\\alpha > 0\\) correct to 3 decimal places using iteration with \\(x_{0} = 2\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\alpha = \\sqrt{5 - \\alpha} \\;\\to\\; \\alpha^{2} + \\alpha - 5 = 0;\\;\\;\\text{iterate from }x_{0} = 2", explanation: "We square the fixed-point relation to get the quadratic, solve for the positive root explicitly, iterate from \\(x_{0} = 2\\) carrying 4 d.p., spot a cobweb that brackets \\(\\alpha\\), and confirm to 3 d.p." }, { stepNumber: 2, description: "Derive the fixed-point relation.", workingLatex: "\\alpha = \\sqrt{5 - \\alpha}", explanation: "Set \\(x_{n+1} = x_{n} = \\alpha\\) in the recurrence. Note \\(\\alpha \\geq 0\\) automatically (it's a square root)." }, { stepNumber: 3, description: "Square both sides.", workingLatex: "\\alpha^{2} = 5 - \\alpha", explanation: "Squaring is reversible here because both sides are non-negative — no extraneous root introduced." }, { stepNumber: 4, description: "Rearrange to standard form.", workingLatex: "\\alpha^{2} + \\alpha - 5 = 0", explanation: "Bring all terms to the left. Shown." }, { stepNumber: 5, description: "Apply the quadratic formula.", workingLatex: "\\alpha = \\displaystyle\\frac{-1 \\pm \\sqrt{1 + 20}}{2} = \\displaystyle\\frac{-1 \\pm \\sqrt{21}}{2}", explanation: "Discriminant: \\(1 - 4 \\cdot 1 \\cdot (-5) = 1 + 20 = 21\\). Two real roots." }, { stepNumber: 6, description: "Select the positive root.", workingLatex: "\\alpha = \\displaystyle\\frac{-1 + \\sqrt{21}}{2} \\approx \\displaystyle\\frac{-1 + 4.5826}{2} \\approx 1.7913", explanation: "\\(\\sqrt{21} \\approx 4.5826\\). The negative root is extraneous (would not satisfy the original \\(\\alpha = \\sqrt{5 - \\alpha} \\geq 0\\))." }, { stepNumber: 7, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\sqrt{5 - 2} = \\sqrt{3} \\approx 1.7321", explanation: "Iterate from \\(x_{0} = 2\\). \\(\\sqrt{3} = 1.7320508\\ldots\\), round to \\(1.7321\\)." }, { stepNumber: 8, description: "Compute \\(x_{2}\\).", workingLatex: "x_{2} = \\sqrt{5 - 1.7321} = \\sqrt{3.2679} \\approx 1.8077", explanation: "Note: \\(1.8077^{2} = 3.26779\\), confirms 4 d.p." }, { stepNumber: 9, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\sqrt{5 - 1.8077} = \\sqrt{3.1923} \\approx 1.7867", explanation: "Cobweb: \\(1.73 \\to 1.81 \\to 1.79\\) — clear straddling of \\(\\alpha \\approx 1.79\\)." }, { stepNumber: 10, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\sqrt{5 - 1.7867} = \\sqrt{3.2133} \\approx 1.7926", explanation: "Above the true value." }, { stepNumber: 11, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = \\sqrt{5 - 1.7926} = \\sqrt{3.2074} \\approx 1.7909", explanation: "Below, but very close. Successive differences: \\(0.076, 0.021, 0.006, 0.002\\) — shrinking by a factor of \\(\\sim 0.28\\) per step." }, { stepNumber: 12, description: "Check convergence rate.", workingLatex: "g(x) = \\sqrt{5 - x} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{1}{2\\sqrt{5 - x}} \\;\\Rightarrow\\; g'(1.7913) = -\\displaystyle\\frac{1}{2 \\cdot 1.7913} \\approx -0.279", explanation: "Used the fixed-point relation \\(\\sqrt{5 - \\alpha} = \\alpha\\) to simplify the derivative. \\(|g'(\\alpha)| \\approx 0.28 < 1\\) (cobweb, since negative) — matches observed shrinkage factor." }, { stepNumber: 13, description: "Round to 3 d.p.", workingLatex: "x_{4} \\approx 1.793,\\ x_{5} \\approx 1.791 \\;\\Rightarrow\\; \\alpha \\approx 1.791", explanation: "Both \\(x_{4}\\) and \\(x_{5}\\) round to within \\(0.001\\) of \\(1.791\\) (\\(x_{4}\\) rounds up, \\(x_{5}\\) down) — agreeing with the quadratic-formula value." }, { stepNumber: 14, description: "Sanity-check.", workingLatex: "1.791^{2} + 1.791 - 5 \\approx 3.208 + 1.791 - 5 = -0.001 \\approx 0", explanation: "Substituting \\(\\alpha = 1.791\\) into the quadratic gives essentially zero — root confirmed to 3 d.p." } ], finalAnswer: "\\(\\alpha \\approx 1.791\\) to 3 d.p." } },
  { id: "y2nm2-065", topicRef: "y2nm2", topicTitle: "Iteration 65", difficulty: "Challenge", questionText: "The equation \\(x^{3} + x - 1 = 0\\) has a single real root \\(\\alpha\\). Rearrange as \\(x = \\tfrac{1}{x^{2} + 1}\\) and, starting from \\(x_{0} = 0.5\\), compute \\(x_{5}\\) to 5 decimal places.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["iteration"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x^{3} + x = 1 \\;\\to\\; x = \\displaystyle\\frac{1}{x^{2} + 1};\\;\\;\\text{iterate 5 times from }x_{0} = 0.5", explanation: "We re-write the cubic as \\(x = g(x)\\), iterate five times carrying 5 d.p. throughout, then evaluate \\(g'(\\alpha)\\) to explain the slow cobweb convergence." }, { stepNumber: 2, description: "Rearrange the cubic — factor.", workingLatex: "x^{3} + x - 1 = 0 \\;\\Longrightarrow\\; x^{3} + x = 1 \\;\\Longrightarrow\\; x(x^{2} + 1) = 1", explanation: "Add 1 to both sides; factor out the common \\(x\\). Note \\(x^{2} + 1 > 0\\) always." }, { stepNumber: 3, description: "Divide to isolate \\(x\\).", workingLatex: "x = \\displaystyle\\frac{1}{x^{2} + 1}", explanation: "Divide by \\((x^{2} + 1)\\), which is always positive — no roots gained or lost." }, { stepNumber: 4, description: "State the iteration formula.", workingLatex: "x_{n+1} = \\displaystyle\\frac{1}{x_{n}^{2} + 1},\\quad x_{0} = 0.5", explanation: "" }, { stepNumber: 5, description: "Compute \\(x_{1}\\).", workingLatex: "x_{1} = \\displaystyle\\frac{1}{0.5^{2} + 1} = \\displaystyle\\frac{1}{1.25} = 0.80000", explanation: "Exact. \\(0.5^{2} = 0.25\\); \\(1/1.25 = 0.8\\)." }, { stepNumber: 6, description: "Compute \\(x_{2}\\) — set-up.", workingLatex: "x_{2} = \\displaystyle\\frac{1}{0.8^{2} + 1} = \\displaystyle\\frac{1}{1.64}", explanation: "Square: \\(0.8^{2} = 0.64\\). Add 1: \\(1.64\\)." }, { stepNumber: 7, description: "Evaluate \\(x_{2}\\).", workingLatex: "x_{2} = \\displaystyle\\frac{1}{1.64} \\approx 0.60976", explanation: "Long division: \\(1/1.64 = 0.609756\\ldots\\); round to \\(0.60976\\)." }, { stepNumber: 8, description: "Compute \\(x_{3}\\).", workingLatex: "x_{3} = \\displaystyle\\frac{1}{0.60976^{2} + 1} = \\displaystyle\\frac{1}{1.37181} \\approx 0.72897", explanation: "\\(0.60976^{2} \\approx 0.37181\\); add 1 to get \\(1.37181\\); reciprocal \\(\\approx 0.72897\\)." }, { stepNumber: 9, description: "Compute \\(x_{4}\\).", workingLatex: "x_{4} = \\displaystyle\\frac{1}{0.72897^{2} + 1} = \\displaystyle\\frac{1}{1.53140} \\approx 0.65300", explanation: "\\(0.72897^{2} \\approx 0.53140\\); reciprocal of \\(1.53140\\) is \\(0.65300\\)." }, { stepNumber: 10, description: "Compute \\(x_{5}\\).", workingLatex: "x_{5} = \\displaystyle\\frac{1}{0.65300^{2} + 1} = \\displaystyle\\frac{1}{1.42641} \\approx 0.70106", explanation: "\\(0.65300^{2} \\approx 0.42641\\); reciprocal of \\(1.42641\\) is \\(0.70106\\)." }, { stepNumber: 11, description: "Tabulate the cobweb.", workingLatex: "0.50000 \\to 0.80000 \\to 0.60976 \\to 0.72897 \\to 0.65300 \\to 0.70106 \\to \\cdots", explanation: "Iterates alternate above and below the limit \\(\\alpha \\approx 0.6823\\). Odd subsequence is decreasing from above; even is increasing from below." }, { stepNumber: 12, description: "Diagnose the slow convergence.", workingLatex: "g'(x) = -\\displaystyle\\frac{2x}{(x^{2} + 1)^{2}} \\;\\Rightarrow\\; g'(0.6823) = -\\displaystyle\\frac{1.3646}{(1.4655)^{2}} \\approx -0.635", explanation: "\\(|g'(\\alpha)| \\approx 0.64 < 1\\) — convergent — but close to 1, so slow. Each step shrinks the error by only \\(\\sim 36\\%\\)." }, { stepNumber: 13, description: "Predict ultimate limit.", workingLatex: "x_{n} \\to \\alpha \\approx 0.6823", explanation: "After about 25 iterations both subsequences converge to 5 d.p. \\(\\alpha = 0.682328\\ldots\\) is the real root of the original cubic." } ], finalAnswer: "\\(x_{5} \\approx 0.70106\\); approaches \\(\\approx 0.6823\\)." } },
  { id: "y2nm2-066", topicRef: "y2nm2", topicTitle: "Iteration 66", difficulty: "Challenge", questionText: "Suggest a rearrangement of \\(x^{3} + x - 1 = 0\\) that gives more rapid convergence than \\(x = \\tfrac{1}{x^{2} + 1}\\), and justify your answer using \\(g'(\\alpha)\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence", "comparison"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Compute }|g_{0}'(\\alpha)|;\\;\\text{propose Newton form;}\\;\\text{cite }g_{N}'(\\alpha) = 0", explanation: "We first compute the original rearrangement's derivative \\(|g_{0}'(\\alpha)|\\) to establish the slow rate, then propose the Newton–Raphson form whose derivative is guaranteed to be zero at any simple root (Q62 result), so it gives quadratic convergence." }, { stepNumber: 2, description: "Locate the root.", workingLatex: "f(x) = x^{3} + x - 1,\\;\\alpha \\approx 0.6823", explanation: "Standard numerical value of the unique real root (the discriminant is negative, so only one real root)." }, { stepNumber: 3, description: "Differentiate the original \\(g_{0}\\).", workingLatex: "g_{0}(x) = \\displaystyle\\frac{1}{x^{2} + 1} = (x^{2} + 1)^{-1} \\;\\Rightarrow\\; g_{0}'(x) = -(x^{2} + 1)^{-2} \\cdot 2x = -\\displaystyle\\frac{2x}{(x^{2} + 1)^{2}}", explanation: "Chain rule on the negative-power form." }, { stepNumber: 4, description: "Evaluate \\(g_{0}'(\\alpha)\\).", workingLatex: "g_{0}'(0.6823) = -\\displaystyle\\frac{2 \\cdot 0.6823}{(0.6823^{2} + 1)^{2}} = -\\displaystyle\\frac{1.3646}{(1.4655)^{2}} \\approx -\\displaystyle\\frac{1.3646}{2.1477} \\approx -0.635", explanation: "\\(0.6823^{2} \\approx 0.4655\\); add 1 to get \\(1.4655\\); square it to get \\(2.1477\\)." }, { stepNumber: 5, description: "Diagnose the rate.", workingLatex: "|g_{0}'(\\alpha)| \\approx 0.64,\\ \\text{close to 1}", explanation: "Convergent but only linearly, with the error shrinking by \\(\\sim 36\\%\\) per step. We saw the slow cobweb in Q65." }, { stepNumber: 6, description: "Propose the Newton–Raphson rearrangement.", workingLatex: "g_{N}(x) = x - \\displaystyle\\frac{f(x)}{f'(x)} = x - \\displaystyle\\frac{x^{3} + x - 1}{3x^{2} + 1}", explanation: "Standard Newton iteration for \\(f(x) = x^{3} + x - 1\\) (with \\(f'(x) = 3x^{2} + 1\\)) — this is itself a fixed-point scheme." }, { stepNumber: 7, description: "Quote the Q62 result.", workingLatex: "g_{N}'(\\alpha) = \\displaystyle\\frac{f(\\alpha)\\,f''(\\alpha)}{[f'(\\alpha)]^{2}} = 0", explanation: "From Q62, the Newton-iteration's derivative simplifies to \\(f f''/[f']^{2}\\), which vanishes at any simple root \\(\\alpha\\) because \\(f(\\alpha) = 0\\) and \\(f'(\\alpha) \\neq 0\\)." }, { stepNumber: 8, description: "Compare rates.", workingLatex: "|g_{0}'(\\alpha)| \\approx 0.64\\ \\text{(linear)};\\quad |g_{N}'(\\alpha)| = 0\\ \\text{(quadratic)}", explanation: "Old scheme: error shrinks by factor \\(0.64\\) per step. Newton: error squares per step. Massively faster, even after just a few iterations." }, { stepNumber: 9, description: "Demonstrate Newton from \\(x_{0} = 0.7\\).", workingLatex: "f(0.7) = 0.343 + 0.7 - 1 = 0.043,\\quad f'(0.7) = 3 \\cdot 0.49 + 1 = 2.47", explanation: "Compute the numerator and denominator of the Newton step." }, { stepNumber: 10, description: "Newton step 1.", workingLatex: "x_{1} = 0.7 - \\displaystyle\\frac{0.043}{2.47} \\approx 0.7 - 0.01741 \\approx 0.68259", explanation: "Already accurate to 3 d.p. after one step. Error went from \\(\\approx 0.018\\) to \\(\\approx 0.0003\\) — squared, as predicted." }, { stepNumber: 11, description: "Newton step 2.", workingLatex: "f(0.68259) \\approx -0.00010 \\;\\Rightarrow\\; x_{2} \\approx 0.68233", explanation: "Now correct to 5 d.p. Two Newton steps have outperformed five iterations of \\(g_{0}\\)." }, { stepNumber: 12, description: "Conclude.", workingLatex: "g_{N}(x) = x - \\displaystyle\\frac{x^{3} + x - 1}{3x^{2} + 1}\\quad\\text{gives quadratic convergence}", explanation: "The Newton rearrangement is dramatically faster: \\(|g'(\\alpha)| = 0\\) gives error squaring at every step, versus the original \\(0.64\\) factor." } ], finalAnswer: "Newton–Raphson form \\(g_{N}(x) = x - \\tfrac{x^{3}+x-1}{3x^{2}+1}\\) has \\(g'(\\alpha) = 0\\), giving quadratic (faster) convergence." } },
  { id: "y2nm2-067", topicRef: "y2nm2", topicTitle: "Iteration 67", difficulty: "Challenge", questionText: "Let \\(g(x) = \\tfrac{1}{2}(x + \\tfrac{c}{x})\\) for \\(c > 0\\). Show that the sequence \\(x_{n+1} = g(x_{n})\\) has error \\(\\epsilon_{n+1} = x_{n+1} - \\sqrt{c}\\) satisfying \\(\\epsilon_{n+1} = \\tfrac{\\epsilon_{n}^{2}}{2x_{n}}\\), and interpret this as quadratic convergence.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["convergence", "theory"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "g(x) - \\sqrt{c} = \\displaystyle\\frac{(x - \\sqrt{c})^{2}}{2x};\\quad \\text{translate to errors }\\epsilon_{n}", explanation: "We compute the error \\(g(x) - \\sqrt{c}\\) directly: combine over a common denominator, spot the perfect square in the numerator, then translate \\(x = x_{n}\\) and \\(g(x) = x_{n+1}\\) to read off the error recursion \\(\\epsilon_{n+1} = \\epsilon_{n}^{2}/(2x_{n})\\). We interpret this as quadratic convergence." }, { stepNumber: 2, description: "Write down the error expression.", workingLatex: "g(x) - \\sqrt{c} = \\displaystyle\\frac{1}{2}\\!\\left(x + \\displaystyle\\frac{c}{x}\\right) - \\sqrt{c}", explanation: "Subtract the target value \\(\\sqrt{c}\\) from the iteration formula." }, { stepNumber: 3, description: "Combine over a common denominator \\(2x\\).", workingLatex: "g(x) - \\sqrt{c} = \\displaystyle\\frac{x^{2}}{2x} + \\displaystyle\\frac{c}{2x} - \\displaystyle\\frac{2\\sqrt{c}\\,x}{2x}", explanation: "Each term is written with denominator \\(2x\\). Note: \\(\\sqrt{c} = \\tfrac{2\\sqrt{c}\\,x}{2x}\\)." }, { stepNumber: 4, description: "Combine into a single fraction.", workingLatex: "g(x) - \\sqrt{c} = \\displaystyle\\frac{x^{2} - 2\\sqrt{c}\\,x + c}{2x}", explanation: "Add the numerators over the common denominator." }, { stepNumber: 5, description: "Recognise the perfect square.", workingLatex: "x^{2} - 2\\sqrt{c}\\,x + c = (x - \\sqrt{c})^{2}", explanation: "Compare to \\((a - b)^{2} = a^{2} - 2ab + b^{2}\\) with \\(a = x\\), \\(b = \\sqrt{c}\\), \\(b^{2} = c\\). Exact match." }, { stepNumber: 6, description: "Write the closed-form identity.", workingLatex: "g(x) - \\sqrt{c} = \\displaystyle\\frac{(x - \\sqrt{c})^{2}}{2x}", explanation: "This identity holds for every \\(x > 0\\) — it is purely algebraic, not just asymptotic." }, { stepNumber: 7, description: "Translate to iteration notation.", workingLatex: "x_{n+1} - \\sqrt{c} = g(x_{n}) - \\sqrt{c} = \\displaystyle\\frac{(x_{n} - \\sqrt{c})^{2}}{2x_{n}}", explanation: "Apply the identity at \\(x = x_{n}\\), where \\(g(x_{n}) = x_{n+1}\\)." }, { stepNumber: 8, description: "Introduce error notation.", workingLatex: "\\epsilon_{n} = x_{n} - \\sqrt{c}", explanation: "Standard substitution — \\(\\epsilon_{n}\\) is the (signed) error in the \\(n\\)-th iterate." }, { stepNumber: 9, description: "Read off the error recursion.", workingLatex: "\\epsilon_{n+1} = \\displaystyle\\frac{\\epsilon_{n}^{2}}{2x_{n}}", explanation: "Shown. The next error is the current error \\emph{squared}, divided by \\(2x_{n}\\)." }, { stepNumber: 10, description: "Bound for quadratic convergence.", workingLatex: "x_{n} \\approx \\sqrt{c} \\;\\Rightarrow\\; \\displaystyle\\frac{1}{2x_{n}} \\approx \\displaystyle\\frac{1}{2\\sqrt{c}}", explanation: "Near the root, the denominator is approximately a constant \\(2\\sqrt{c}\\)." }, { stepNumber: 11, description: "State the quadratic bound.", workingLatex: "|\\epsilon_{n+1}| \\le \\displaystyle\\frac{1}{2\\sqrt{c}}\\,|\\epsilon_{n}|^{2} \\quad (\\text{for }x_{n}\\text{ close to }\\sqrt{c})", explanation: "Hence \\(|\\epsilon_{n+1}| \\leq K|\\epsilon_{n}|^{2}\\) with \\(K = 1/(2\\sqrt{c})\\) — quadratic convergence in the formal sense (cf. Q58)." }, { stepNumber: 12, description: "Interpret in terms of digit doubling.", workingLatex: "|\\epsilon_{n}| \\sim 10^{-k} \\;\\Rightarrow\\; |\\epsilon_{n+1}| \\sim 10^{-2k}", explanation: "If we currently have \\(k\\) correct decimal digits, after one step we have roughly \\(2k\\). After 4 steps starting from 1 correct digit: \\(1 \\to 2 \\to 4 \\to 8 \\to 16\\) correct digits — past double precision!" }, { stepNumber: 13, description: "Practical observation.", workingLatex: "\\text{Babylonian method: machine precision in 5–6 steps}", explanation: "This is exactly the iteration we used in Q43 (for \\(\\sqrt{7}\\)) and Q38 (for \\(\\sqrt{2}\\)). Both converged to 4 d.p. in just 2–3 iterations, perfectly matching the digit-doubling prediction." } ], finalAnswer: "\\(\\epsilon_{n+1} = \\tfrac{\\epsilon_{n}^{2}}{2x_{n}}\\) — quadratic convergence." } },
  { id: "y2nm2-068", topicRef: "y2nm2", topicTitle: "Iteration 68", difficulty: "Challenge", questionText: "The iteration \\(x_{n+1} = 1.5 x_{n}(1 - x_{n})\\) (a logistic map with parameter 1.5) has fixed points 0 and \\(\\tfrac{1}{3}\\). Determine which of these is attracting.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["fixed point", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "\\text{Verify the two given fixed points};\\ g'(x);\\ \\text{evaluate at each};\\ \\text{classify}", explanation: "We confirm the given fixed points by solving \\(\\alpha = g(\\alpha)\\), differentiate \\(g\\), evaluate \\(g'\\) at both fixed points, and apply the criterion \\(|g'(\\alpha)| < 1\\) to identify which is attracting. Finally we verify with a quick numerical iteration." }, { stepNumber: 2, description: "Set up the fixed-point equation.", workingLatex: "\\alpha = 1.5\\alpha(1 - \\alpha)", explanation: "Substitute \\(x = \\alpha\\) into the recurrence." }, { stepNumber: 3, description: "Expand and rearrange.", workingLatex: "\\alpha = 1.5\\alpha - 1.5\\alpha^{2} \\;\\Longrightarrow\\; 1.5\\alpha^{2} - 0.5\\alpha = 0", explanation: "Subtract \\(\\alpha\\) from both sides; collect terms." }, { stepNumber: 4, description: "Factor out \\(\\alpha\\).", workingLatex: "0.5\\alpha(3\\alpha - 1) = 0", explanation: "Common factor of \\(0.5\\alpha\\). The two zeros are \\(\\alpha = 0\\) and \\(\\alpha = \\tfrac{1}{3}\\), confirming the given fixed points." }, { stepNumber: 5, description: "Read off the fixed points.", workingLatex: "\\alpha_{1} = 0,\\quad \\alpha_{2} = \\displaystyle\\frac{1}{3}", explanation: "Two candidate limits." }, { stepNumber: 6, description: "Differentiate \\(g\\).", workingLatex: "g(x) = 1.5x(1 - x) = 1.5x - 1.5x^{2} \\;\\Rightarrow\\; g'(x) = 1.5 - 3x = 1.5(1 - 2x)", explanation: "Expand first, then power rule term by term. Factor for clarity." }, { stepNumber: 7, description: "Evaluate \\(g'(0)\\).", workingLatex: "g'(0) = 1.5(1 - 0) = 1.5", explanation: "Plug in \\(\\alpha_{1} = 0\\). Magnitude \\(1.5\\)." }, { stepNumber: 8, description: "Classify \\(\\alpha_{1} = 0\\).", workingLatex: "|g'(0)| = 1.5 > 1 \\;\\Rightarrow\\; \\alpha_{1} = 0\\text{ is repelling}", explanation: "The fixed point at 0 fails the contraction criterion. Iterates starting near 0 (but nonzero) grow at first." }, { stepNumber: 9, description: "Evaluate \\(g'(1/3)\\).", workingLatex: "g'\\!\\left(\\displaystyle\\frac{1}{3}\\right) = 1.5\\!\\left(1 - 2 \\cdot \\displaystyle\\frac{1}{3}\\right) = 1.5\\!\\left(1 - \\displaystyle\\frac{2}{3}\\right) = 1.5 \\cdot \\displaystyle\\frac{1}{3} = 0.5", explanation: "Plug in \\(\\alpha_{2} = \\tfrac{1}{3}\\). Magnitude \\(0.5\\)." }, { stepNumber: 10, description: "Classify \\(\\alpha_{2} = 1/3\\).", workingLatex: "|g'(1/3)| = 0.5 < 1 \\;\\Rightarrow\\; \\alpha_{2} = 1/3\\text{ is attracting}", explanation: "Criterion satisfied. Positive sign means monotone (staircase) approach — iterates climb steadily to \\(\\tfrac{1}{3}\\) without oscillating." }, { stepNumber: 11, description: "Sanity-check numerically.", workingLatex: "x_{0} = 0.1 \\to x_{1} = 0.135 \\to x_{2} = 0.175 \\to x_{3} = 0.217 \\to \\cdots \\to \\displaystyle\\frac{1}{3}", explanation: "Starting near \\(0\\) (repelling), the iterate moves \\emph{away} from 0 towards \\(\\tfrac{1}{3}\\) (attracting). Both classifications confirmed." }, { stepNumber: 12, description: "Conclude.", workingLatex: "\\alpha = \\displaystyle\\frac{1}{3}\\text{ attracting (}|g'| = 0.5\\text{)};\\quad \\alpha = 0\\text{ repelling (}|g'| = 1.5\\text{)}", explanation: "The basin of attraction for \\(\\tfrac{1}{3}\\) contains every \\(x_{0} \\in (0, 1)\\) (with the trivial exception of \\(x = 0\\) and \\(x = 1\\), which stay at 0 forever)." } ], finalAnswer: "\\(\\alpha = 1/3\\) is attracting (\\(|g'| = 0.5\\)); \\(\\alpha = 0\\) is repelling (\\(|g'| = 1.5\\))." } },
  { id: "y2nm2-069", topicRef: "y2nm2", topicTitle: "Iteration 69", difficulty: "Challenge", questionText: "A calculator repeats the iteration \\(x_{n+1} = \\cos x_{n}\\) (radians) starting from any value \\(x_{0}\\). Show that for any starting value in \\(\\mathbb{R}\\) the sequence converges to the same limit, and give this limit to 4 decimal places.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["convergence", "trigonometric"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "x_{1} \\in [-1, 1] \\to x_{2} \\in [\\cos 1, 1] \\to \\text{contraction} \\to \\text{global convergence}", explanation: "We show that after at most two iterations, any real starting value lies inside the invariant interval \\([\\cos 1, 1]\\). On this interval \\(|g'(x)| = |\\sin x| \\leq \\sin 1 < 1\\), so \\(g = \\cos\\) is a strict contraction. The Banach fixed-point theorem then gives existence, uniqueness and convergence — all independent of the starting value." }, { stepNumber: 2, description: "Range of \\(\\cos\\) — first step.", workingLatex: "x_{1} = \\cos x_{0} \\in [-1, 1]\\quad \\text{for any }x_{0} \\in \\mathbb{R}", explanation: "The cosine function has codomain \\([-1, 1]\\) — no matter what \\(x_{0}\\) is, the iterate \\(x_{1}\\) is squeezed into this interval." }, { stepNumber: 3, description: "Range of \\(\\cos\\) — second step.", workingLatex: "x_{2} = \\cos x_{1}", explanation: "Since \\(x_{1} \\in [-1, 1]\\), \\(x_{2}\\) is the cosine of a value in \\([-1, 1]\\)." }, { stepNumber: 4, description: "Cosine is even.", workingLatex: "\\cos x_{1} = \\cos|x_{1}|,\\ |x_{1}| \\in [0, 1]", explanation: "Apply the evenness of \\(\\cos\\): cosine of negative values equals cosine of the absolute value. So we only need to know the range of \\(\\cos\\) on \\([0, 1]\\)." }, { stepNumber: 5, description: "Range of \\(\\cos\\) on \\([0, 1]\\).", workingLatex: "\\cos\\text{ decreasing on }[0, \\pi/2] \\;\\Rightarrow\\; \\cos[0, 1] = [\\cos 1, \\cos 0] = [\\cos 1, 1]", explanation: "\\(\\cos\\) is strictly decreasing on \\([0, \\pi/2]\\), and \\([0, 1] \\subset [0, \\pi/2]\\). Endpoint values: \\(\\cos 0 = 1\\) and \\(\\cos 1 \\approx 0.5403\\)." }, { stepNumber: 6, description: "Hence \\(x_{2} \\in [\\cos 1, 1]\\).", workingLatex: "x_{2} \\in [\\cos 1, 1] \\approx [0.5403, 1]", explanation: "After two iterations, any real start is corralled into this small positive interval." }, { stepNumber: 7, description: "Show the interval is invariant.", workingLatex: "x \\in [\\cos 1, 1] \\;\\Rightarrow\\; \\cos x \\in [\\cos 1, \\cos(\\cos 1)] \\subset [\\cos 1, 1]", explanation: "Apply \\(\\cos\\) again: on \\([\\cos 1, 1]\\) (a subinterval of \\([0, 1] \\subset [0, \\pi/2]\\)) \\(\\cos\\) maps into \\([\\cos 1, 1]\\) too. So once inside, iterates stay." }, { stepNumber: 8, description: "Differentiate \\(g\\) and bound \\(|g'|\\).", workingLatex: "g(x) = \\cos x \\;\\Rightarrow\\; g'(x) = -\\sin x", explanation: "Standard derivative." }, { stepNumber: 9, description: "Find \\(\\max |\\sin x|\\) on \\([\\cos 1, 1]\\).", workingLatex: "\\sin\\text{ increasing on }[0, \\pi/2] \\;\\Rightarrow\\; |\\sin x| \\le \\sin 1\\text{ on }[\\cos 1, 1]", explanation: "\\(\\sin\\) increases on \\([0, \\pi/2]\\), and \\([\\cos 1, 1] \\subset [0, \\pi/2]\\). Max value of \\(\\sin\\) on the interval is at the right endpoint \\(x = 1\\)." }, { stepNumber: 10, description: "Numerical bound.", workingLatex: "|g'(x)| = |\\sin x| \\le \\sin 1 \\approx 0.8415 < 1\\ \\text{ on }[\\cos 1, 1]", explanation: "Strictly less than 1 — the contraction condition is satisfied uniformly on the interval." }, { stepNumber: 11, description: "Apply the Banach fixed-point theorem.", workingLatex: "g:[\\cos 1, 1] \\to [\\cos 1, 1]\\text{ is a contraction} \\;\\Rightarrow\\; \\exists!\\,\\alpha:\\ g(\\alpha) = \\alpha,\\;x_{n} \\to \\alpha", explanation: "A contraction on a closed interval has a unique fixed point, and iterates from any start in the interval converge to it. From step 6, any \\(x_{0} \\in \\mathbb{R}\\) puts \\(x_{2}\\) inside the interval, so global convergence follows." }, { stepNumber: 12, description: "Compute \\(\\alpha\\) numerically.", workingLatex: "\\alpha = \\cos \\alpha;\\quad\\text{iterating: }x \\to 1 \\to 0.5403 \\to 0.8576 \\to 0.6543 \\to \\cdots \\to 0.7391", explanation: "The transcendental equation \\(\\cos x = x\\) has no closed form. Numerical iteration (or Newton on \\(f(x) = \\cos x - x\\)) gives the (Dottie) number \\(\\alpha = 0.739085\\ldots\\)" }, { stepNumber: 13, description: "State the limit to 4 d.p.", workingLatex: "\\alpha \\approx 0.7391", explanation: "Same limit for every starting value \\(x_{0} \\in \\mathbb{R}\\) — a beautiful example of globally convergent fixed-point iteration." } ], finalAnswer: "Limit \\(\\alpha \\approx 0.7391\\)." } },
  { id: "y2nm2-070", topicRef: "y2nm2", topicTitle: "Iteration 70", difficulty: "Challenge", questionText: "Use the iteration \\(x_{n+1} = g(x_{n})\\) of your choice to find, to 4 decimal places, the positive real root of \\(e^{x} + 3x - 4 = 0\\). Justify that your chosen rearrangement converges.", marks: 6, examStyle: true, yearCreated: 2026, tags: ["iteration", "convergence"], workedSolution: { steps: [ { stepNumber: 1, description: "Strategy.", workingLatex: "f(x) = e^{x} + 3x - 4;\\ \\text{bracket via IVT};\\ x = \\displaystyle\\frac{4 - e^{x}}{3};\\ \\text{verify }|g'| < 1;\\ \\text{iterate}", explanation: "We bracket the root by sign change, choose the rearrangement \\(g(x) = (4 - e^{x})/3\\), verify \\(|g'(\\alpha)| < 1\\) for convergence, and iterate from \\(x_{0} = 0.7\\) (close to the root). The negative \\(g'\\) gives a cobweb, so we iterate enough times for both subsequences to settle to 4 d.p." }, { stepNumber: 2, description: "Locate the root by sign change.", workingLatex: "f(0) = 1 + 0 - 4 = -3,\\quad f(1) = e + 3 - 4 \\approx 2.7183 - 1 = 1.7183", explanation: "\\(f\\) is continuous; sign change between \\(0\\) and \\(1\\) means there is a root in \\((0, 1)\\) by IVT." }, { stepNumber: 3, description: "Refine the bracket.", workingLatex: "f(0.5) = e^{0.5} + 1.5 - 4 \\approx 1.6487 + 1.5 - 4 = -0.851,\\quad f(0.7) \\approx 2.0138 + 2.1 - 4 = 0.1138", explanation: "Sign change in \\((0.5, 0.7)\\). Numerical solution: \\(\\alpha \\approx 0.6772\\)." }, { stepNumber: 4, description: "Choose a rearrangement.", workingLatex: "e^{x} + 3x - 4 = 0 \\;\\Longrightarrow\\; 3x = 4 - e^{x} \\;\\Longrightarrow\\; x = \\displaystyle\\frac{4 - e^{x}}{3}", explanation: "Isolate \\(3x\\), divide by 3 to get \\(x = g(x)\\). Alternative rearrangements (e.g. \\(x = \\ln(4 - 3x)\\)) also work but this one is cleaner to differentiate." }, { stepNumber: 5, description: "Differentiate \\(g\\).", workingLatex: "g(x) = \\displaystyle\\frac{4 - e^{x}}{3} = \\displaystyle\\frac{4}{3} - \\displaystyle\\frac{e^{x}}{3} \\;\\Rightarrow\\; g'(x) = -\\displaystyle\\frac{e^{x}}{3}", explanation: "Constant differentiates to zero; \\(e^{x}\\) is its own derivative, with the factor \\(-\\tfrac{1}{3}\\) carrying through." }, { stepNumber: 6, description: "Evaluate \\(g'(\\alpha)\\).", workingLatex: "g'(0.6772) = -\\displaystyle\\frac{e^{0.6772}}{3} \\approx -\\displaystyle\\frac{1.9685}{3} \\approx -0.6562", explanation: "\\(e^{0.6772} = 1.9685\\) (calculator). Divide by 3 and attach minus sign." }, { stepNumber: 7, description: "Apply the convergence criterion.", workingLatex: "|g'(\\alpha)| \\approx 0.66 < 1 \\;\\Rightarrow\\; \\text{convergent (cobweb)}", explanation: "Strict inequality, with negative sign, so cobweb pattern (alternating sides of \\(\\alpha\\)). Rate \\(\\sim 66\\%\\) per step — moderately slow." }, { stepNumber: 8, description: "Compute \\(x_{1}\\) from \\(x_{0} = 0.7\\).", workingLatex: "x_{1} = \\displaystyle\\frac{4 - e^{0.7}}{3} = \\displaystyle\\frac{4 - 2.0138}{3} = \\displaystyle\\frac{1.9862}{3} \\approx 0.6621", explanation: "Start close to the root for fast convergence." }, { stepNumber: 9, description: "Compute \\(x_{2}\\) through \\(x_{5}\\).", workingLatex: "x_{2} \\approx 0.6871,\\ x_{3} \\approx 0.6707,\\ x_{4} \\approx 0.6815,\\ x_{5} \\approx 0.6744", explanation: "Each iterate: \\(e^{x_{n}}\\) by calculator, then \\((4 - e^{x_{n}})/3\\). Cobweb in full swing: \\(0.66 \\to 0.69 \\to 0.67 \\to 0.68 \\to 0.67\\)." }, { stepNumber: 10, description: "Compute \\(x_{6}\\) through \\(x_{9}\\).", workingLatex: "x_{6} \\approx 0.6790,\\ x_{7} \\approx 0.6760,\\ x_{8} \\approx 0.6780,\\ x_{9} \\approx 0.6767", explanation: "Amplitude has shrunk from \\(\\pm 0.025\\) to \\(\\pm 0.0010\\) — about \\(\\sim 0.66^{n}\\) decay, matching the predicted rate." }, { stepNumber: 11, description: "Compute \\(x_{10}\\) through \\(x_{12}\\).", workingLatex: "x_{10} \\approx 0.6775,\\ x_{11} \\approx 0.6770,\\ x_{12} \\approx 0.6772", explanation: "Both subsequences now agree to 4 d.p. at \\(0.6772\\)." }, { stepNumber: 12, description: "Sanity-check.", workingLatex: "e^{0.6772} + 3 \\cdot 0.6772 - 4 \\approx 1.9685 + 2.0316 - 4 \\approx -0.0001 \\approx 0", explanation: "Substituting \\(\\alpha = 0.6772\\) into the original equation gives essentially zero — root confirmed to 4 d.p." }, { stepNumber: 13, description: "State the answer.", workingLatex: "\\alpha \\approx 0.6772", explanation: "The positive real root of \\(e^{x} + 3x - 4 = 0\\), found via \\(g(x) = (4 - e^{x})/3\\) with verified \\(|g'(\\alpha)| \\approx 0.66 < 1\\). True value: \\(\\alpha = 0.677208\\ldots\\)" } ], finalAnswer: "Root \\(\\approx 0.6772\\)." } },
];
